INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93804, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "叫做；说。", "primary_collocate": null, "pronunciation": "chēng shuō", "ipa": "ʈʂʰɤŋ˥ ʂwo˥", "syllable_count": 2, "sentences": [{"text": "当地人称说这种鱼为“河豚”。", "target_word": "称说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人都称说他是好心人。", "target_word": "称说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山，人们称说它是“神山”。", "target_word": "称说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老一辈人称说火车为“火轮”。", "target_word": "称说", "complexity_tier": "T3", "furigana": "lǎo yī bèi rén chēng shuō huǒ chē wéi huǒ lún", "sentence_source": "generated"}, {"text": "他们称说自己的孩子为“小宝”。", "target_word": "称说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种做法，大家称说为“老规矩”。", "target_word": "称说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乡下人都称说这种草为“野菜”。", "target_word": "称说", "complexity_tier": "T3", "furigana": "xiāng xià rén dōu chēng shuō zhè zhǒng cǎo wéi yě cài", "sentence_source": "generated"}, {"text": "过去人们称说医生为“大夫”。", "target_word": "称说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们都称说她是热心肠。", "target_word": "称说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河，当地人称说为“母亲河”。", "target_word": "称说", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "称说：用某个名称来叫某人或某物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21d5d4e3-cb6a-4e49-9798-364dbe498c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93804, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "称说", "is_correct": true, "explanation": "称说：用“河豚”这一名称指称这种鱼，与“为”引出的称谓相合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”是进食动作，不能表示用名称指称，“吃这种鱼为河豚”说不通。"}, {"text": "游", "is_correct": false, "explanation": "配价：“游”是不及物动词，不能带“这种鱼”作宾语。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指烹调，与“为河豚”的命名义无关，句子说不通。"}], "explanations": {"称说": "称说：用“河豚”这一名称指称这种鱼，与“为”引出的称谓相合。", "吃": "语义：“吃”是进食动作，不能表示用名称指称，“吃这种鱼为河豚”说不通。", "游": "配价：“游”是不及物动词，不能带“这种鱼”作宾语。", "煮": "语义：“煮”指烹调，与“为河豚”的命名义无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "称说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拿锤子称说钉子。", "explanation": "这里应该用〈敲〉，表示用锤子击打；称说只表示用名称指称或说出，不能表示击打。"}, {"text": "医生用体温计称说体温。", "explanation": "这里应该用〈测〉，表示用仪器测量数值；称说只表示用名称指称或说出，不能表示测量。"}, {"text": "我每天早上称说体重。", "explanation": "这里应该用〈称〉，表示用秤测量重量；称说是“叫做、说”的意思，不能用于称量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93804, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "称说", "is_correct": true, "explanation": "称说：用“野菜”这一名称指称这种草，与“为”引出的称谓相合。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指燃烧或加热，“烧这种草为野菜”说不通，不能表示命名。"}, {"text": "跑", "is_correct": false, "explanation": "配价：“跑”是不及物动词，不能带“这种草”作宾语。"}, {"text": "闻", "is_correct": false, "explanation": "语义：“闻”指用鼻子感知气味，与“为野菜”的命名义无关。"}], "explanations": {"称说": "称说：用“野菜”这一名称指称这种草，与“为”引出的称谓相合。", "烧": "语义：“烧”指燃烧或加热，“烧这种草为野菜”说不通，不能表示命名。", "跑": "配价：“跑”是不及物动词，不能带“这种草”作宾语。", "闻": "语义：“闻”指用鼻子感知气味，与“为野菜”的命名义无关。"}, "sentence_index": 6, "correct_answer": "称说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在台上称说了一首歌。", "explanation": "这里应该用〈唱〉，表示用声音演唱歌曲；称说表示说出或指称，不能用于演唱。"}, {"text": "他称说着孩子走出门。", "explanation": "这里应该用〈抱〉，表示用手臂搂住；称说只表示用名称指称或说出，不能表示搂抱。"}, {"text": "他用布称说桌子。", "explanation": "这里应该用〈擦〉，表示用布抹去灰尘；称说不能表示擦拭动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93804, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们村里人称说这种花叫“喇叭花”。", "corrected_sentence": "我们村里人称说这种花为“喇叭花”。", "error_description": "错误形式：“称说这种花叫”。“称说”本身已有“叫做”的意思，后面再用“叫”重复，句子杂糅。正确形式为“称说这种花为“喇叭花””。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93804, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那座山，当地人称说它了为“圣山”。", "corrected_sentence": "那座山，当地人称说它为“圣山”。", "error_description": "错误形式：“称说它了为”。“了”应紧跟动词，不能插在宾语“它”与“为”之间。正确形式为“称说它为“圣山””。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
