INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93805, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "策划是先想好办法，再安排怎么做。", "primary_collocate": null, "pronunciation": "cè huà", "ipa": "tsʰɤ˥˩ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "我们要先策划，再动手做。", "target_word": "策划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司让他策划新年晚会。", "target_word": "策划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很会策划，每次活动都很顺利。", "target_word": "策划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们正在策划毕业典礼的节目。", "target_word": "策划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你打算怎么策划这次聚会？", "target_word": "策划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们策划了一次安静的海边旅行。", "target_word": "策划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理策划着下个月的新产品发布会。", "target_word": "策划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目是我们三个人一起策划的。", "target_word": "策划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟想策划一场家庭游戏比赛。", "target_word": "策划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她以前策划过很多有名的展览。", "target_word": "策划", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "策划了", "label": "体标"}, {"form": "策划着", "label": "体标"}, {"form": "策划过", "label": "体标"}, {"form": "策划者", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词：先想好办法，再安排具体怎么做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd05d25bf-15fb-4699-a34e-f76e1fe1de8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93805, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "策划", "is_correct": true, "explanation": "策划：先想好办法，再安排具体怎么做，与“先……再动手做”的顺序相符。"}, {"text": "动手", "is_correct": false, "explanation": "语义：“先动手”与“再动手做”重复，打乱了先想后做的顺序。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”与“再动手做”相矛盾，句子说的是先筹划再行动。"}, {"text": "拍卖", "is_correct": false, "explanation": "搭配：“拍卖”需要拍品作宾语，不说单独的先拍卖。"}], "explanations": {"策划": "策划：先想好办法，再安排具体怎么做，与“先……再动手做”的顺序相符。", "动手": "语义：“先动手”与“再动手做”重复，打乱了先想后做的顺序。", "放弃": "语义：“放弃”与“再动手做”相矛盾，句子说的是先筹划再行动。", "拍卖": "搭配：“拍卖”需要拍品作宾语，不说单独的先拍卖。"}, "sentence_index": 0, "correct_answer": "策划"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师策划了一块黑板。", "explanation": "这里应该用〈擦〉。策划指事先筹划安排事情，擦黑板是动手的具体动作，策划不能这样用。"}, {"text": "我策划今天买菜。", "explanation": "这里应该用〈计划〉。策划多用于需要统筹的活动、方案，买菜这样的日常小事用计划。"}, {"text": "他策划了一篇日记。", "explanation": "这里应该用〈写〉。写是动手完成文字，策划指事先筹划安排，不用于写日记这种具体动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78d0f3c9-01f1-4ba5-bc90-05fa44432b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93805, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "策划", "is_correct": true, "explanation": "策划：先想好办法再安排，与“下个月的新产品发布会”的筹备相符。"}, {"text": "怀念", "is_correct": false, "explanation": "语义：“怀念”指回想过去，下个月的发布会尚未举行，二者矛盾。"}, {"text": "回忆", "is_correct": false, "explanation": "语义：“回忆”指想起已经发生的事，与尚未举行的发布会不符。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象多是器物，不说修理发布会。"}], "explanations": {"策划": "策划：先想好办法再安排，与“下个月的新产品发布会”的筹备相符。", "怀念": "语义：“怀念”指回想过去，下个月的发布会尚未举行，二者矛盾。", "回忆": "语义：“回忆”指想起已经发生的事，与尚未举行的发布会不符。", "修理": "搭配：“修理”的对象多是器物，不说修理发布会。"}, "sentence_index": 6, "correct_answer": "策划"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她策划过一碗汤。", "explanation": "这里应该用〈煮〉。策划指事先筹划安排活动或事情，煮汤是动手做饭的具体动作，不说策划一碗汤。"}, {"text": "我策划了一棵大树。", "explanation": "这里应该用〈种〉。策划指事先筹划安排事情，大树是要种植的植物，策划不能用于这样的植物。"}, {"text": "他策划了一块石头。", "explanation": "这里应该用〈搬〉。策划指事先筹划安排事情，搬石头是动手的具体动作，策划不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78d0f3c9-01f1-4ba5-bc90-05fa44432b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93805, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学生们要先策划得，再动手做实验。", "corrected_sentence": "学生们要先策划，再动手做实验。", "error_description": "错误：“策划”后多加了“得”。“得”需要接补语（如“策划得很好”），这里没有补语，应删去。正确：“学生们要先策划，再动手做实验。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78d0f3c9-01f1-4ba5-bc90-05fa44432b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93805, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈正在策划了全家的春游。", "corrected_sentence": "妈妈正在策划全家的春游。", "error_description": "错误：“正在策划了”，多加了“了”。正确：“正在策划”。“正在”表示动作正在进行，“了”表示动作已完成，两者不能同用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78d0f3c9-01f1-4ba5-bc90-05fa44432b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
