INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93809, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "property", "definition": "感叹语，用于事情出了问题、令人着急的时候。", "primary_collocate": null, "pronunciation": "zāo gāo", "ipa": "tsɑʊ˥ kɑʊ˥", "syllable_count": 2, "sentences": [{"text": "糟糕！我忘了带钥匙。", "target_word": "糟糕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "糟糕，要迟到了，快跑！", "target_word": "糟糕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "糟糕！手机没电了，怎么办？", "target_word": "糟糕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哎呀，糟糕，我把作业放在家里了。", "target_word": "糟糕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "糟糕，下雨了，我没带伞。", "target_word": "糟糕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "糟糕！门锁上了，钥匙在里面。", "target_word": "糟糕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "糟糕，我的钱包不见了！", "target_word": "糟糕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "糟糕，这道菜忘了放盐。", "target_word": "糟糕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "糟糕！火车已经开走了。", "target_word": "糟糕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "糟糕，电影马上开始了，我们还在路上。", "target_word": "糟糕", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "事情出了问题，让人着急（感叹）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1ebf27a-bc60-422b-bfea-fa9b711a051c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93809, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可爱", "is_correct": false, "explanation": "语义：“可爱”是赞美，与忘带钥匙这种让人着急的事矛盾。"}, {"text": "糟糕", "is_correct": true, "explanation": "正确：“糟糕”表示事情变坏、让人着急的感叹，符合忘带钥匙的语境。"}, {"text": "认真", "is_correct": false, "explanation": "语义：“认真”形容态度，不能表达突然出问题后的懊恼。"}, {"text": "严重", "is_correct": false, "explanation": "语域：“严重”偏书面、客观，口语中不单独作感叹语。"}], "explanations": {"可爱": "语义：“可爱”是赞美，与忘带钥匙这种让人着急的事矛盾。", "糟糕": "正确：“糟糕”表示事情变坏、让人着急的感叹，符合忘带钥匙的语境。", "认真": "语义：“认真”形容态度，不能表达突然出问题后的懊恼。", "严重": "语域：“严重”偏书面、客观，口语中不单独作感叹语。"}, "sentence_index": 0, "correct_answer": "糟糕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "糟糕，我带了伞，所以没有被雨淋湿。", "explanation": "这里应该用〈幸亏〉。“糟糕”表示事情出了问题、让人着急；这里说带了伞没被雨淋湿，是庆幸的事，感情色彩相反。"}, {"text": "糟糕！今天的考试我得了满分。", "explanation": "这里应该用〈太棒了〉。“糟糕”表示让人着急的坏事，考满分是喜事，两者不能搭配。"}, {"text": "糟糕，我们的球队赢了比赛，大家都很开心。", "explanation": "这里应该用〈太好了〉。“糟糕”表示事情变坏，球队获胜、大家开心是好事，感情色彩相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93809, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "光荣", "is_correct": false, "explanation": "语域：“光荣”是书面语，口语中不用来表达丢东西的懊恼。"}, {"text": "轻松", "is_correct": false, "explanation": "语义：“轻松”表示没有压力，与钱包不见时的紧张相反。"}, {"text": "糟糕", "is_correct": true, "explanation": "正确：“糟糕”表示懊恼、着急，符合钱包不见了的语境。"}, {"text": "精彩", "is_correct": false, "explanation": "语义：“精彩”是称赞，与钱包丢失的懊恼矛盾。"}], "explanations": {"光荣": "语域：“光荣”是书面语，口语中不用来表达丢东西的懊恼。", "轻松": "语义：“轻松”表示没有压力，与钱包不见时的紧张相反。", "糟糕": "正确：“糟糕”表示懊恼、着急，符合钱包不见了的语境。", "精彩": "语义：“精彩”是称赞，与钱包丢失的懊恼矛盾。"}, "sentence_index": 6, "correct_answer": "糟糕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "糟糕，老朋友，好久不见！", "explanation": "这里应该用〈嗨〉。“糟糕”是表示懊恼、着急的感叹，不能用来打招呼。"}, {"text": "糟糕，你考上了大学！", "explanation": "这里应该用〈恭喜〉。“糟糕”表示事情变坏、让人着急，考上大学是喜事，应当用“恭喜”。"}, {"text": "糟糕，今天是你的生日，祝你生日快乐！", "explanation": "这里应该用〈祝贺〉。“糟糕”表示事情变坏，生日祝福是喜事，感情色彩相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93809, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "糟糕，我的眼镜糟糕不见了。", "corrected_sentence": "糟糕，我的眼镜不见了。", "error_description": "句中多用了一个「糟糕」：「糟糕不见了」不通，应删去多余的一个。正确说法：「糟糕，我的眼镜不见了。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93809, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "糟糕的，我的雨伞丢在地铁上了！", "corrected_sentence": "糟糕，我的雨伞丢在地铁上了！", "error_description": "“糟糕”作感叹语时后面不能加“的”；加“的”后“糟糕的”变成定语，缺少中心词，句子不通。正确说法：“糟糕，我的雨伞丢在地铁上了！”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93810, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安静", "is_correct": false, "explanation": "安静与“吵闹”相对，与“糟糕”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚与“模糊”相对，与“糟糕”没有反义关系。"}, {"text": "好", "is_correct": true, "explanation": "正确：“好”与“糟糕”构成反义，指情况良好。"}, {"text": "复杂", "is_correct": false, "explanation": "复杂与“简单”相对，与“糟糕”没有反义关系。"}], "correct_answer": "好", "explanations": {"安静": "安静与“吵闹”相对，与“糟糕”没有反义关系。", "清楚": "清楚与“模糊”相对，与“糟糕”没有反义关系。", "好": "正确：“好”与“糟糕”构成反义，指情况良好。", "复杂": "复杂与“简单”相对，与“糟糕”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
