INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93810, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "事情或情况很坏；不好。", "primary_collocate": null, "pronunciation": "zāo gāo", "ipa": "tsɑʊ˥ kɑʊ˥", "syllable_count": 2, "sentences": [{"text": "今天天气很糟糕，我们不出门了。", "target_word": "糟糕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他考试的成绩非常糟糕。", "target_word": "糟糕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆的服务太糟糕了。", "target_word": "糟糕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上的情况糟糕极了，车一动不动。", "target_word": "糟糕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨晚睡得很糟糕，今天没精神。", "target_word": "糟糕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的字写得糟糕，老师看不清。", "target_word": "糟糕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛输了，大家的心情都很糟糕。", "target_word": "糟糕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的空气越来越糟糕。", "target_word": "糟糕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那是一次糟糕的旅行，天天下雨。", "target_word": "糟糕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的身体状况很糟糕，要马上去医院。", "target_word": "糟糕", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "糟糕透了", "label": "程度补语"}, {"form": "糟糕的", "label": "的字结构"}], "register": "口语", "sense_fingerprint": "事情、情况、状态很差很坏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1ebf27a-bc60-422b-bfea-fa9b711a051c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93810, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "晴朗", "is_correct": false, "explanation": "语义：“晴朗”表示天气好，与“不出门”的原因矛盾。"}, {"text": "严肃", "is_correct": false, "explanation": "搭配：“严肃”形容人的神情或态度，不能用来形容天气。"}, {"text": "糟糕", "is_correct": true, "explanation": "正确：“糟糕”指情况很坏，符合天气不好、不出门的语境。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：“漂亮”是称赞，与天气不好、不出门的结果矛盾。"}], "explanations": {"晴朗": "语义：“晴朗”表示天气好，与“不出门”的原因矛盾。", "严肃": "搭配：“严肃”形容人的神情或态度，不能用来形容天气。", "糟糕": "正确：“糟糕”指情况很坏，符合天气不好、不出门的语境。", "漂亮": "语义：“漂亮”是称赞，与天气不好、不出门的结果矛盾。"}, "sentence_index": 0, "correct_answer": "糟糕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我考上了梦想中的大学，心情真糟糕。", "explanation": "这里应该用〈愉快〉。“糟糕”指情况很坏，考上理想的大学是好事，与“心情糟糕”矛盾。"}, {"text": "他的工资比去年翻了一倍，真糟糕。", "explanation": "这里应该用〈好〉。“糟糕”指情况很坏，工资翻倍是好事，感情色彩相反。"}, {"text": "他的成绩提高了很多，真糟糕。", "explanation": "这里应该用〈高兴〉。“糟糕”指情况很坏，成绩提高是值得高兴的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93810, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "灿烂", "is_correct": false, "explanation": "搭配：“灿烂”形容阳光或笑容，不能用来形容心情。"}, {"text": "糟糕", "is_correct": true, "explanation": "正确：“糟糕”指情况很坏，符合比赛输了、大家心情不好的语境。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”表示开心，与比赛输了的语境矛盾。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”形容光线或眼睛，不能用来形容心情。"}], "explanations": {"灿烂": "搭配：“灿烂”形容阳光或笑容，不能用来形容心情。", "糟糕": "正确：“糟糕”指情况很坏，符合比赛输了、大家心情不好的语境。", "高兴": "语义：“高兴”表示开心，与比赛输了的语境矛盾。", "明亮": "搭配：“明亮”形容光线或眼睛，不能用来形容心情。"}, "sentence_index": 6, "correct_answer": "糟糕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这次考试考了一百分，成绩很糟糕。", "explanation": "这里应该用〈优秀〉。「糟糕」指情况很坏，考了一百分是好成绩，与「糟糕」矛盾。"}, {"text": "公司的新产品大受欢迎，销售状况非常糟糕。", "explanation": "这里应该用〈很好〉。「糟糕」指情况很坏，产品大受欢迎是好事，与「糟糕」矛盾。"}, {"text": "我们的新房子又大又亮，环境非常糟糕。", "explanation": "这里应该用〈舒适〉。「糟糕」指情况很坏，「又大又亮」的房子与「糟糕」矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93810, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天的天气很糟糕透了，我们都不想出门。", "corrected_sentence": "今天的天气糟糕透了，我们都不想出门。", "error_description": "错误形式：「今天的天气很糟糕透了」。正确形式：「今天的天气糟糕透了」。“糟糕透了”中“透了”是补语，不能与程度副词“很”同时出现，“很”应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93810, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家饭馆的服务很很糟糕，我们不想再来。", "corrected_sentence": "这家饭馆的服务很糟糕，我们不想再来。", "error_description": "错误形式：「很很糟糕」。正确形式：「很糟糕」。程度副词“很”只用一次，重复的“很很”不符合汉语语法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
