INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93811, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "结局是故事或事情最后变成什么样。", "primary_collocate": null, "pronunciation": "jié jú", "ipa": "tɕjɛ˧˥ tɕy˧˥", "syllable_count": 2, "sentences": [{"text": "这部电影的结局很感人。", "target_word": "结局", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我不喜欢这本小说的结局。", "target_word": "结局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "故事的结局是王子和公主结婚了。", "target_word": "结局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她看了一半，就想知道结局。", "target_word": "结局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请不要告诉我这部电视剧的结局。", "target_word": "结局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事有一个快乐的结局。", "target_word": "结局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人猜错了电影的结局。", "target_word": "结局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作者把小说的结局改了。", "target_word": "结局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都喜欢结局幸福的故事。", "target_word": "结局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书的结局太快了，我没看懂。", "target_word": "结局", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "大结局", "label": "复合"}], "register": "中性", "sense_fingerprint": "故事、电影、小说的结尾", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ab86027-31e9-470c-a719-029cfab81c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93811, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "结局", "is_correct": true, "explanation": "结局：故事或电影最后的情节，读作 jié jú。"}, {"text": "洁具", "is_correct": false, "explanation": "jù（第四声）与 jú（第二声）声调不同，意思是卫生洁具。"}, {"text": "借据", "is_correct": false, "explanation": "jiè 与 jié、jù 与 jú 声调都不同，意思是借条。"}, {"text": "借居", "is_correct": false, "explanation": "jiè 与 jié、jū 与 jú 声调不同，意思是暂时住在别人家。"}], "explanations": {"结局": "结局：故事或电影最后的情节，读作 jié jú。", "洁具": "jù（第四声）与 jú（第二声）声调不同，意思是卫生洁具。", "借据": "jiè 与 jié、jù 与 jú 声调都不同，意思是借条。", "借居": "jiè 与 jié、jū 与 jú 声调不同，意思是暂时住在别人家。"}, "sentence_index": null, "correct_answer": "结局"}, "level_3": {"options": [{"text": "结局", "is_correct": true, "explanation": "结局：电影的结尾，符合“很感人”的语境。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指人或物的重量，不能说“很感人”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”只说钱数，与“感人”的语境无关。"}, {"text": "形状", "is_correct": false, "explanation": "搭配：“形状”指外形，“形状很感人”不成立。"}], "explanations": {"结局": "结局：电影的结尾，符合“很感人”的语境。", "体重": "语义：“体重”指人或物的重量，不能说“很感人”。", "价格": "语义：“价格”只说钱数，与“感人”的语境无关。", "形状": "搭配：“形状”指外形，“形状很感人”不成立。"}, "sentence_index": 0, "correct_answer": "结局"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这一把结局让我很期待。", "explanation": "这里应该用量词〈个〉。结局用“个”，“把”多用于有柄的器具。"}, {"text": "他用了很卑鄙的结局。", "explanation": "这里应该用〈手段〉。“用”后面接的是采取的方法，要说〈手段〉；结局指事情最后的状况，不能和“用”搭配。"}, {"text": "这件事的结局很大。", "explanation": "这里应该用〈影响〉。事情产生的作用和范围要用〈影响〉，结局指事情最后的状况，不能说“很大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93811, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "结局", "is_correct": true, "explanation": "结局：故事或电影的结尾，符合“猜错了”的语境。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人的高矮，不能用来说“猜错了电影的身高”。"}, {"text": "海报", "is_correct": false, "explanation": "语义：“海报”是宣传图片，与电影的情节无关，不用来“猜错”。"}, {"text": "包装", "is_correct": false, "explanation": "搭配：“包装”指外面的包裹，不说“电影的包装”被猜错。"}], "explanations": {"结局": "结局：故事或电影的结尾，符合“猜错了”的语境。", "身高": "语义：“身高”指人的高矮，不能用来说“猜错了电影的身高”。", "海报": "语义：“海报”是宣传图片，与电影的情节无关，不用来“猜错”。", "包装": "搭配：“包装”指外面的包裹，不说“电影的包装”被猜错。"}, "sentence_index": 6, "correct_answer": "结局"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇论文的结局很重要。", "explanation": "这里应该用〈结论〉。论文最后的判断要用〈结论〉，结局指故事或事情的结尾。"}, {"text": "会议的结局时间是下午五点。", "explanation": "这里应该用〈结束〉。会议终止的时间要用〈结束〉，结局指事情最后的状况。"}, {"text": "这张结局让我很失望。", "explanation": "这里应该用量词〈个〉。结局用“个”，“张”多用于纸张、桌子等平面的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93811, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部电影已经结局了。", "corrected_sentence": "这部电影已经有结局了。", "error_description": "错误形式：“结局了”；正确形式：“有结局了”。“结局”是名词，不能直接作谓语，要加“有”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93811, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部小说有一位悲伤的结局。", "corrected_sentence": "这部小说有一个悲伤的结局。", "error_description": "错误形式：“一位悲伤的结局”；正确形式：“一个悲伤的结局”。“结局”的量词是“个”，“位”只用于人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
