INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93812, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情发展到最后的结果。", "primary_collocate": null, "pronunciation": "jié jú", "ipa": "tɕjɛ˧˥ tɕy˧˥", "syllable_count": 2, "sentences": [{"text": "这件事的结局让大家都很意外。", "target_word": "结局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没想到比赛的结局会这么好。", "target_word": "结局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吵了一个晚上，结局还是分手了。", "target_word": "结局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不管努力多久，结局都不会改变。", "target_word": "结局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也不知道这场战争的结局是什么。", "target_word": "结局", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做错了决定，结局很不好。", "target_word": "结局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们都希望这次谈判有好结局。", "target_word": "结局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那家公司最后的结局是关门了。", "target_word": "结局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看到他的结局，我心里很难过。", "target_word": "结局", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，坏习惯的结局不会太好。", "target_word": "结局", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "大结局", "label": "复合"}], "register": "中性", "sense_fingerprint": "事情发展到最后的结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ab86027-31e9-470c-a719-029cfab81c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93812, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "结局", "is_correct": true, "explanation": "结局：事情或故事最后的结果，读作 jié jú。"}, {"text": "洁具", "is_correct": false, "explanation": "jù（第四声）与 jú（第二声）声调不同，意思是卫生洁具。"}, {"text": "借据", "is_correct": false, "explanation": "jiè 与 jié、jù 与 jú 声调都不同，意思是借条。"}, {"text": "借居", "is_correct": false, "explanation": "jiè 与 jié、jū 与 jú 声调不同，意思是暂时住在别人家。"}], "explanations": {"结局": "结局：事情或故事最后的结果，读作 jié jú。", "洁具": "jù（第四声）与 jú（第二声）声调不同，意思是卫生洁具。", "借据": "jiè 与 jié、jù 与 jú 声调都不同，意思是借条。", "借居": "jiè 与 jié、jū 与 jú 声调不同，意思是暂时住在别人家。"}, "sentence_index": null, "correct_answer": "结局"}, "level_3": {"options": [{"text": "结局", "is_correct": true, "explanation": "结局：事情最后的结果，符合“让大家都很意外”的语境。"}, {"text": "形状", "is_correct": false, "explanation": "搭配：“形状”指物体的外形，事情没有形状，不说“这件事的形状”。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”描述物体的色彩，不用来说事情。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”只指人或物的高矮，与事情带来的意外感不相关。"}], "explanations": {"结局": "结局：事情最后的结果，符合“让大家都很意外”的语境。", "形状": "搭配：“形状”指物体的外形，事情没有形状，不说“这件事的形状”。", "颜色": "搭配：“颜色”描述物体的色彩，不用来说事情。", "身高": "语义：“身高”只指人或物的高矮，与事情带来的意外感不相关。"}, "sentence_index": 0, "correct_answer": "结局"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道数学题的结局很高，很多人都不会做。", "explanation": "这里应该用〈难度〉。题目难不难要说〈难度〉，结局指事情最后的结果，不能说“结局很高”。"}, {"text": "这一把结局让大家都很意外。", "explanation": "这里应该用量词〈个〉。结局用“个”，“把”多用于有柄的器具。"}, {"text": "他喝了一口结局。", "explanation": "这里应该用〈汤〉。“一口”多用于可以喝的东西，结局不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93812, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "结局", "is_correct": true, "explanation": "结局：事情最后的结果，符合“希望有好结局”的语境。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指人的性情，不用来形容谈判的情况。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”指人或物的重量，不用来修饰“好”。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人的高矮，谈判不能“有好身高”。"}], "explanations": {"结局": "结局：事情最后的结果，符合“希望有好结局”的语境。", "脾气": "语义：“脾气”指人的性情，不用来形容谈判的情况。", "体重": "搭配：“体重”指人或物的重量，不用来修饰“好”。", "身高": "语义：“身高”指人的高矮，谈判不能“有好身高”。"}, "sentence_index": 6, "correct_answer": "结局"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条规定的结局很严格。", "explanation": "这里应该用〈标准〉。规定的严格程度要说〈标准〉，结局指事情最后的状况，不能用来形容规定。"}, {"text": "会议的结局时间是下午五点。", "explanation": "这里应该用〈结束〉。会议终止的时间要用〈结束〉，结局指事情最后的状况。"}, {"text": "这张结局让我很失望。", "explanation": "这里应该用量词〈个〉。结局用“个”，“张”多用于纸张、桌子等平面的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93812, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事已经结局了。", "corrected_sentence": "这件事已经有结局了。", "error_description": "错误形式：“结局了”；正确形式：“有结局了”。“结局”是名词，不能直接作谓语，要加“有”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93812, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没想到比赛有一条好结局。", "corrected_sentence": "他没想到比赛有一个好结局。", "error_description": "错误形式：“一条好结局”；正确形式：“一个好结局”。“结局”的量词是“个”，“条”多用于线状或细长的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
