INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93814, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "检查并修理，使恢复正常使用。", "primary_collocate": null, "pronunciation": "wéi xiū", "ipa": "weɪ˧˥ ɕjoʊ˥", "syllable_count": 2, "sentences": [{"text": "工人们正在维修马路。", "target_word": "维修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁每个星期都要维修。", "target_word": "维修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师每月维修一次机器。", "target_word": "维修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电梯停了，因为要维修。", "target_word": "维修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司派人来维修空调。", "target_word": "维修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂把旧机器维修了一遍。", "target_word": "维修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥正在维修，暂时不能通车。", "target_word": "维修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车开了十年，要定期维修。", "target_word": "维修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的机器坏了，需要马上维修。", "target_word": "维修", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的灯坏了，工人下午来维修。", "target_word": "维修", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "维修了", "label": "体标"}, {"form": "维修过", "label": "体标"}, {"form": "维修工", "label": "复合"}, {"form": "維修", "label": "繁体"}], "register": "中性", "sense_fingerprint": "检查并修理机器、设施，使它恢复正常使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01308c1-157a-474f-8335-9b2ec1714ab6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93814, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "维修", "is_correct": true, "explanation": "正确。“维修”指检查并修理设施，马路是设施，工人们正在维修。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”指给人或动物送食物，马路不能被喂，句子说不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与修理马路的行为不符。"}, {"text": "叠", "is_correct": false, "explanation": "语义：“叠”指折叠，马路不能被叠，句子说不通。"}], "explanations": {"维修": "正确。“维修”指检查并修理设施，马路是设施，工人们正在维修。", "喂": "语义：“喂”指给人或动物送食物，马路不能被喂，句子说不通。", "唱": "语义：“唱”指发出歌声，与修理马路的行为不符。", "叠": "语义：“叠”指折叠，马路不能被叠，句子说不通。"}, "sentence_index": 0, "correct_answer": "维修"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要维修两人的感情。", "explanation": "这里应该用〈修复〉。“维修”指修理机器、设施，感情不是机器，要说修复。"}, {"text": "他把这篇作文维修了一遍。", "explanation": "这里应该用〈修改〉。作文不是机器或设施，不能维修，要说修改。"}, {"text": "医生正在维修那个病人。", "explanation": "这里应该用〈治疗〉。“维修”用于机器、设施等物品，病人要说治疗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '565832eb-6e16-435c-bc95-9b8b731e7e39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93814, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "维修", "is_correct": true, "explanation": "正确。这座桥正在维修，所以暂时不能通车。"}, {"text": "开放", "is_correct": false, "explanation": "语义：“开放”指允许通行，与“暂时不能通车”矛盾。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”用于烹饪食物，桥不能被煮，句子不成立。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：“游泳”是不及物动词，不能以“这座桥”作施事，句子不成立。"}], "explanations": {"维修": "正确。这座桥正在维修，所以暂时不能通车。", "开放": "语义：“开放”指允许通行，与“暂时不能通车”矛盾。", "煮": "语义：“煮”用于烹饪食物，桥不能被煮，句子不成立。", "游泳": "搭配：“游泳”是不及物动词，不能以“这座桥”作施事，句子不成立。"}, "sentence_index": 6, "correct_answer": "维修"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想维修我的弟弟。", "explanation": "这里应该用〈照顾〉。“维修”的对象是机器、设施等物品，不能用来指人。"}, {"text": "老师要求我们维修自己的坏习惯。", "explanation": "这里应该用〈改掉〉。“维修”用于恢复有形物品的功能，坏习惯要说改掉。"}, {"text": "他每天都要维修自己的记忆力。", "explanation": "这里应该用〈锻炼〉。“维修”用于修理坏了的东西，记忆力要说锻炼或提高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '565832eb-6e16-435c-bc95-9b8b731e7e39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93814, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工程队正在维修了那段马路。", "corrected_sentence": "工程队正在维修那段马路。", "error_description": "时体冲突：“正在”表示动作进行中，不能与“了”同用，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '565832eb-6e16-435c-bc95-9b8b731e7e39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93814, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人正在维修过那座老桥。", "corrected_sentence": "工人正在维修那座老桥。", "error_description": "时体冲突：“正在”表示动作进行，不能与“过”同用，应去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '565832eb-6e16-435c-bc95-9b8b731e7e39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
