INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93815, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "自称是自己说自己是什么样的人。", "primary_collocate": null, "pronunciation": "zì chēng", "ipa": "tsɹ̩⁵¹ ʈʂʰɤŋ⁵⁵", "syllable_count": 2, "sentences": [{"text": "他自称是一名医生。", "target_word": "自称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人自称是我的老朋友。", "target_word": "自称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她自称是运动员，可是从不跑步。", "target_word": "自称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口来了一个自称是快递员的人。", "target_word": "自称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他自称是学校的老师，却没带工作证。", "target_word": "自称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位自称画家的年轻人住在山上。", "target_word": "自称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话里的人自称是银行的工作人员。", "target_word": "自称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟自称是全家最会做饭的人。", "target_word": "自称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她自称是穷人，却天天买新衣服。", "target_word": "自称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位自称歌手的男人唱得不太好。", "target_word": "自称", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自稱", "label": "繁体"}], "register": "中性", "sense_fingerprint": "自己说自己是某种身份或样子的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6ac4a1-2343-42ab-ba2b-c2fbb8aa55f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93815, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "自称", "is_correct": true, "explanation": "正确。自称是自己说自己是某种身份或样子。"}, {"text": "自成", "is_correct": false, "explanation": "chéng（第二声）与 chēng（第一声）声调不同，意思是自成一体，不是自己说自己是什么人。"}, {"text": "自生", "is_correct": false, "explanation": "shēng 与 chēng 声母不同（sh 与 ch），意思是自己产生或自然生长。"}, {"text": "自乘", "is_correct": false, "explanation": "chéng（第二声）与 chēng（第一声）声调不同，自乘是数学用语，指一个数乘以它自己，不是自己说自己是什么人。"}], "explanations": {"自称": "正确。自称是自己说自己是某种身份或样子。", "自成": "chéng（第二声）与 chēng（第一声）声调不同，意思是自成一体，不是自己说自己是什么人。", "自生": "shēng 与 chēng 声母不同（sh 与 ch），意思是自己产生或自然生长。", "自乘": "chéng（第二声）与 chēng（第一声）声调不同，自乘是数学用语，指一个数乘以它自己，不是自己说自己是什么人。"}, "sentence_index": null, "correct_answer": "自称"}, "level_3": {"options": [{"text": "自称", "is_correct": true, "explanation": "正确。“自称”表示自己说自己是医生，与句意相符。"}, {"text": "担任", "is_correct": false, "explanation": "配价：“担任”后要接职务作宾语，不能直接跟“是一名医生”这样的判断句。"}, {"text": "辞职", "is_correct": false, "explanation": "语义：“辞职”指离开工作岗位，与“是一名医生”的身份说明不相容。"}, {"text": "梦见", "is_correct": false, "explanation": "配价：“梦见”后接的是梦境内容，不能直接跟“是一名医生”组成判断句。"}], "explanations": {"自称": "正确。“自称”表示自己说自己是医生，与句意相符。", "担任": "配价：“担任”后要接职务作宾语，不能直接跟“是一名医生”这样的判断句。", "辞职": "语义：“辞职”指离开工作岗位，与“是一名医生”的身份说明不相容。", "梦见": "配价：“梦见”后接的是梦境内容，不能直接跟“是一名医生”组成判断句。"}, "sentence_index": 0, "correct_answer": "自称"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "室友自称我的作文写得很好。", "explanation": "这里应该用〈夸奖〉。自称只能说主语自己的情况或身份，不能用来评价别人的作文；应说“室友夸奖我的作文写得很好”。"}, {"text": "他自称我撒了谎。", "explanation": "这里应该用〈指责〉。自称只能说主语本人的身份或情况，不能用来指出别人的过错；应说“他指责我撒了谎”。"}, {"text": "大家自称他为老师。", "explanation": "这里应该用〈称呼〉。自称只能说自己，不能用来称呼别人；应说“大家称呼他为老师”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93815, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自称", "is_correct": true, "explanation": "正确。“自称”表示自己说自己是银行工作人员，与句意相符。"}, {"text": "挂断", "is_correct": false, "explanation": "语义：“挂断”指结束通话，与“是银行的工作人员”的身份说明不相容。"}, {"text": "录取", "is_correct": false, "explanation": "配价：“录取”的宾语是被录用的人或学校，不能直接跟“是……工作人员”组成判断句。"}, {"text": "拨打", "is_correct": false, "explanation": "搭配：“拨打”后接的是电话号码或通话对象，不能接身份判断句。"}], "explanations": {"自称": "正确。“自称”表示自己说自己是银行工作人员，与句意相符。", "挂断": "语义：“挂断”指结束通话，与“是银行的工作人员”的身份说明不相容。", "录取": "配价：“录取”的宾语是被录用的人或学校，不能直接跟“是……工作人员”组成判断句。", "拨打": "搭配：“拨打”后接的是电话号码或通话对象，不能接身份判断句。"}, "sentence_index": 6, "correct_answer": "自称"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同桌自称小玲是班里的第一名。", "explanation": "这里应该用〈夸奖〉。自称只说主语本人的身份或情况，不能用来评价别人；应说“同桌夸小玲是班里的第一名”。"}, {"text": "妈妈自称弟弟说了谎。", "explanation": "这里应该用〈指责〉。自称是自我宣称，不能用来指出别人的过错；应说“妈妈指责弟弟说了谎”。"}, {"text": "朋友自称我去过那家店。", "explanation": "这里应该用〈说〉。自称只说主语本人宣称的情况，不能用来转述朋友对我经历的说法；应说“朋友说我去过那家店”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93815, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她自称了是一名律师。", "corrected_sentence": "她自称是一名律师。", "error_description": "了的位置错误：“自称”后不能直接加“了”。正确说法是“她自称是一名律师。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93815, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他被自称是一名厨师。", "corrected_sentence": "他自称是一名厨师。", "error_description": "被字句用错：“自称”是主动行为，不能用“被”构成被动句。正确说法是“他自称是一名厨师。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
