INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93816, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "自己宣称关于自己的某种情况。", "primary_collocate": null, "pronunciation": "zì chēng", "ipa": "tsɹ̩⁵¹ ʈʂʰɤŋ⁵⁵", "syllable_count": 2, "sentences": [{"text": "他自称已经三天没睡觉了。", "target_word": "自称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王自称从来没有迟到过。", "target_word": "自称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家饭店自称从不用冷冻食材。", "target_word": "自称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她自称不怕黑，晚上却开着灯睡。", "target_word": "自称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板自称从不骗人，可是东西很贵。", "target_word": "自称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网站自称能帮你找到工作。", "target_word": "自称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他自称没看过那部电影，其实看了两遍。", "target_word": "自称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥自称会说五种语言。", "target_word": "自称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个商店自称天天都有便宜的东西。", "target_word": "自称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机自称对这里的路很熟。", "target_word": "自称", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自稱", "label": "繁体"}], "register": "中性", "sense_fingerprint": "自己宣称关于自己的某种情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6ac4a1-2343-42ab-ba2b-c2fbb8aa55f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93816, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "自称", "is_correct": true, "explanation": "正确。自称在这里表示自己宣称某事如此。"}, {"text": "自成", "is_correct": false, "explanation": "chéng（第二声）与 chēng（第一声）声调不同，意思是自成一体，不表示宣称。"}, {"text": "自生", "is_correct": false, "explanation": "shēng 与 chēng 声母不同（sh 与 ch），意思是自己产生或自然生长。"}, {"text": "自乘", "is_correct": false, "explanation": "chéng（第二声）与 chēng（第一声）声调不同，自乘是数学用语，指一个数乘以它自己，不表示宣称。"}], "explanations": {"自称": "正确。自称在这里表示自己宣称某事如此。", "自成": "chéng（第二声）与 chēng（第一声）声调不同，意思是自成一体，不表示宣称。", "自生": "shēng 与 chēng 声母不同（sh 与 ch），意思是自己产生或自然生长。", "自乘": "chéng（第二声）与 chēng（第一声）声调不同，自乘是数学用语，指一个数乘以它自己，不表示宣称。"}, "sentence_index": null, "correct_answer": "自称"}, "level_3": {"options": [{"text": "自称", "is_correct": true, "explanation": "正确。“自称”表示自己宣称已经三天没睡觉，与句意相符。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”指离开工作岗位，与“已经三天没睡觉”的状况没有关联。"}, {"text": "修理", "is_correct": false, "explanation": "配价：“修理”需要具体的东西作宾语，不能直接接“已经三天没睡觉了”这样的小句。"}, {"text": "报名", "is_correct": false, "explanation": "搭配：“报名”后接的是活动或课程，不能接表示睡眠状况的小句。"}], "explanations": {"自称": "正确。“自称”表示自己宣称已经三天没睡觉，与句意相符。", "退休": "语义：“退休”指离开工作岗位，与“已经三天没睡觉”的状况没有关联。", "修理": "配价：“修理”需要具体的东西作宾语，不能直接接“已经三天没睡觉了”这样的小句。", "报名": "搭配：“报名”后接的是活动或课程，不能接表示睡眠状况的小句。"}, "sentence_index": 0, "correct_answer": "自称"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我自称他没有说实话。", "explanation": "这里应该用〈怀疑〉。自称是说话人宣称自己的情况，不能用来表达对别人的怀疑；应说“我怀疑他没有说实话”。"}, {"text": "他自称天气太热。", "explanation": "这里应该用〈抱怨〉。自称的内容只能是主语自己宣称的事，天气不能由人自称；应说“他抱怨天气太热”。"}, {"text": "大家自称她的歌声很动听。", "explanation": "这里应该用〈赞美〉。自称的主语只能说自己，不能用来评价别人的歌声；应说“大家赞美她的歌声很动听”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93816, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自称", "is_correct": true, "explanation": "正确。“自称”表示自己宣称没看过电影，与句意相符。"}, {"text": "赞美", "is_correct": false, "explanation": "搭配：“赞美”的宾语是人或事物，不能接“没看过那部电影”这样的小句。"}, {"text": "演奏", "is_correct": false, "explanation": "搭配：“演奏”后接的是乐曲或乐器，不能接表示观影经历的小句。"}, {"text": "打扫", "is_correct": false, "explanation": "配价：“打扫”后接房间、地方等宾语，不能接“没看过那部电影”这样的小句。"}], "explanations": {"自称": "正确。“自称”表示自己宣称没看过电影，与句意相符。", "赞美": "搭配：“赞美”的宾语是人或事物，不能接“没看过那部电影”这样的小句。", "演奏": "搭配：“演奏”后接的是乐曲或乐器，不能接表示观影经历的小句。", "打扫": "配价：“打扫”后接房间、地方等宾语，不能接“没看过那部电影”这样的小句。"}, "sentence_index": 6, "correct_answer": "自称"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察自称他是小偷。", "explanation": "这里应该用〈认定〉。自称是自己宣称自己的身份，警察不能用来判定别人的身份；应说“警察认定他是小偷”。"}, {"text": "老板自称小王的口音很重。", "explanation": "这里应该用〈指出〉。自称只能说主语本人的情况，不能用来指出别人的口音；应说“老板指出小王的口音很重”。"}, {"text": "医生自称我少吃甜食。", "explanation": "这里应该用〈劝〉。自称的内容是主语本人的情况，不能用来对别人提建议；应说“医生劝我少吃甜食”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93816, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他自称了已经学会游泳。", "corrected_sentence": "他自称已经学会游泳。", "error_description": "了的位置错误：“自称”后不能直接加“了”。正确说法是“他自称已经学会游泳。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93816, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她被自称能修好手机。", "corrected_sentence": "她自称能修好手机。", "error_description": "被字句用错：“自称”不能用“被”构成被动句。正确说法是“她自称能修好手机。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
