INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93819, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "号召是大声叫大家一起去做一件事。", "primary_collocate": null, "pronunciation": "hào zhào", "ipa": "xau˥˩ ʈʂau˥˩", "syllable_count": 2, "sentences": [{"text": "队长号召大家一起把车推上山。", "target_word": "号召", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师号召同学们一起唱歌。", "target_word": "号召", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他号召邻居们一起打扫院子。", "target_word": "号召", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班长号召大家为生病的同学捐钱。", "target_word": "号召", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村长号召村民一起修路。", "target_word": "号召", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她号召朋友们周末去海边捡垃圾。", "target_word": "号召", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理号召大家一起加班把工作做完。", "target_word": "号召", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练号召队员们努力训练，争取冠军。", "target_word": "号召", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长号召全校学生一起种树。", "target_word": "号召", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社长号召社员们一起参加志愿活动。", "target_word": "号召", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "号召了", "label": "体标（了）"}, {"form": "号召过", "label": "体标（过）"}, {"form": "号召力", "label": "复合词"}], "register": "中性", "sense_fingerprint": "号召：出声招呼众人一起行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33f1f67f-f906-4ff1-b27e-6aefc2c445ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93819, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "号召", "is_correct": true, "explanation": "号召指出声招呼众人一起行动，「队长号召大家一起把车推上山」自然。"}, {"text": "怠慢", "is_correct": false, "explanation": "语义：怠慢是冷落、不重视，与带领大家一起行动相反。"}, {"text": "分散", "is_correct": false, "explanation": "语义：「分散」与「一起」意思相反，不能指示大家同做一件事。"}, {"text": "冷落", "is_correct": false, "explanation": "搭配：「冷落」多接人或关系，不接「大家一起把车推上山」这种行动要求。"}], "explanations": {"号召": "号召指出声招呼众人一起行动，「队长号召大家一起把车推上山」自然。", "怠慢": "语义：怠慢是冷落、不重视，与带领大家一起行动相反。", "分散": "语义：「分散」与「一起」意思相反，不能指示大家同做一件事。", "冷落": "搭配：「冷落」多接人或关系，不接「大家一起把车推上山」这种行动要求。"}, "sentence_index": 0, "correct_answer": "号召"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "班长号召大家在教室睡觉。", "explanation": "这里应该用〈允许〉。号召是呼吁大家去做正当的事，不能用来表示允许睡觉。"}, {"text": "班长号召同学们偷钱。", "explanation": "这里应该用〈指使〉。号召是呼吁大家去做正当的事，不能表示指使别人偷钱。"}, {"text": "这块石头号召大家为生病的同学捐钱。", "explanation": "这里应该用〈提醒〉。号召的主语要是人或组织，「石头」不能发出呼吁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '068d6e78-5434-461a-91c4-d2f1ef1559a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93819, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "号召", "is_correct": true, "explanation": "号召指出声招呼众人一起行动，「经理号召大家一起加班把工作做完」符合语境。"}, {"text": "解雇", "is_correct": false, "explanation": "语义：解雇是辞退员工，与号召大家加班的意思不符。"}, {"text": "驳斥", "is_correct": false, "explanation": "语义：驳斥是反驳，与号召大家行动的意思相反。"}, {"text": "赔偿", "is_correct": false, "explanation": "搭配：「赔偿」多接损失或对象，不能接「大家一起加班」这类要求。"}], "explanations": {"号召": "号召指出声招呼众人一起行动，「经理号召大家一起加班把工作做完」符合语境。", "解雇": "语义：解雇是辞退员工，与号召大家加班的意思不符。", "驳斥": "语义：驳斥是反驳，与号召大家行动的意思相反。", "赔偿": "搭配：「赔偿」多接损失或对象，不能接「大家一起加班」这类要求。"}, "sentence_index": 6, "correct_answer": "号召"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场大雨号召社员们一起参加志愿活动。", "explanation": "这里应该用〈提醒〉。号召的主语要是人或组织，「大雨」不能发出呼吁。"}, {"text": "社长号召社员们把书扔进河里。", "explanation": "这里应该用〈指使〉。号召是呼吁大家去做正当的事，不能表示让社员把书扔进河里。"}, {"text": "警察号召了小偷。", "explanation": "这里应该用〈抓捕〉。号召是呼吁众人去做事，不能用来表示抓捕小偷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '068d6e78-5434-461a-91c4-d2f1ef1559a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93819, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "班长的号召很强，大家都愿意听他的。", "corrected_sentence": "班长的号召力很强，大家都愿意听他的。", "error_description": "词形错误：「号召」用作名词时常说「号召力」，不说「号召很强」，这里应补上「力」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '068d6e78-5434-461a-91c4-d2f1ef1559a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93819, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "队长很号召大家一起推车上山。", "corrected_sentence": "队长号召大家一起推车上山。", "error_description": "副词错误：「很」不能修饰动作动词「号召」，应去掉「很」，说「队长号召大家……」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '068d6e78-5434-461a-91c4-d2f1ef1559a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
