INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93821, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "见地是一个人对事情的想法，而且想得很好。", "primary_collocate": null, "pronunciation": "jiàn dì", "ipa": "tɕjɛn˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "这位老师对教育很有见地。", "target_word": "见地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他虽然年轻，说话却很有见地。", "target_word": "见地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都佩服她独到的见地。", "target_word": "见地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的见地让我学到了很多。", "target_word": "见地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了他的发言，我觉得他很有见地。", "target_word": "见地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章里有不少深刻的见地。", "target_word": "见地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷读过很多书，对生活很有见地。", "target_word": "见地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对音乐的见地，连老师也很欣赏。", "target_word": "见地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想请教一位有见地的朋友。", "target_word": "见地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个年轻人的见地，比很多大人还高。", "target_word": "见地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "一个人对事情有很好的想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '838411ca-cf0b-4532-ae63-837208e58bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93821, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "见地", "is_correct": true, "explanation": "正确：“很有见地”指对教育有独到的看法，与句意吻合。"}, {"text": "力气", "is_correct": false, "explanation": "搭配：“有力气”说的是身体的力量，不能用于对教育的看法。"}, {"text": "香味", "is_correct": false, "explanation": "语义：“香味”指气味，“对教育很有香味”说不通。"}, {"text": "食欲", "is_correct": false, "explanation": "语义：“食欲”指想吃东西的欲望，与“对教育”没有关系。"}], "explanations": {"见地": "正确：“很有见地”指对教育有独到的看法，与句意吻合。", "力气": "搭配：“有力气”说的是身体的力量，不能用于对教育的看法。", "香味": "语义：“香味”指气味，“对教育很有香味”说不通。", "食欲": "语义：“食欲”指想吃东西的欲望，与“对教育”没有关系。"}, "sentence_index": 0, "correct_answer": "见地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个见地离我家很远，我每天都要坐很久的车。", "explanation": "这里的“见地”被当成了地点，见地指对事情的看法，不能指地方，应说“地方”。"}, {"text": "这个见地是今天早上才从仓库里搬出来的，我一个人搬不动。", "explanation": "这里的“见地”被当成了货物，见地指对事情的看法，不能从仓库里搬出来，应说“货物”。"}, {"text": "这个孩子的见地只有零点五，所以要配一副眼镜。", "explanation": "这里的“见地”被当成了视力，见地指对事情的看法，不能用“零点五”来说眼睛看得清不清楚，应说“视力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93821, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "见地", "is_correct": true, "explanation": "正确：“对生活很有见地”指对生活有深刻的看法，与句意吻合。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指身体的重量，“对生活很有体重”句意不通。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“有面积”不能与“对生活”搭配，句子说不通。"}, {"text": "价钱", "is_correct": false, "explanation": "语义：“价钱”指价格，“对生活很有价钱”说不通。"}], "explanations": {"见地": "正确：“对生活很有见地”指对生活有深刻的看法，与句意吻合。", "体重": "语义：“体重”指身体的重量，“对生活很有体重”句意不通。", "面积": "搭配：“有面积”不能与“对生活”搭配，句子说不通。", "价钱": "语义：“价钱”指价格，“对生活很有价钱”说不通。"}, "sentence_index": 6, "correct_answer": "见地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个苹果的见地很甜，大家都爱吃。", "explanation": "“甜”形容味道，见地不是食物，不能说“甜”。见地指对事情的看法。"}, {"text": "他把见地放进箱子里，带着去旅行。", "explanation": "见地是对事情的看法，不是能装进箱子的东西，这里不能把它当作物品。"}, {"text": "他迟到的见地是路上堵车。", "explanation": "这里的“见地”被当成了原因，见地指对事情的看法，不能指迟到的理由，应说“原因”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93821, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对这个问题很是见地。", "corrected_sentence": "他对这个问题很有见地。", "error_description": "搭配错误：“见地”是名词，要说“很有见地”，不能说“很是见地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93821, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她是一个很见地的人。", "corrected_sentence": "她是一个很有见地的人。", "error_description": "缺词错误：“见地”是名词，不能直接受“很”修饰，应说“很有见地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93822, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93822, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93822, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "见解；独到的看法。", "primary_collocate": null, "pronunciation": "jiàn dì", "ipa": "tɕjɛn˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "关于这件事，你有什么见地？", "target_word": "见地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的见地很独特，和别人不一样。", "target_word": "见地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板很看重员工的见地。", "target_word": "见地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书里有作者多年来的见地。", "target_word": "见地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在会上说出了自己的见地。", "target_word": "见地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对历史有自己的见地，不会随便听别人的。", "target_word": "见地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生的见地让我们换了方法。", "target_word": "见地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家对城市生活的见地很深。", "target_word": "见地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把自己的见地写在这张纸上。", "target_word": "见地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的见地有时让大人吃惊。", "target_word": "见地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "独到的见解或看法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '838411ca-cf0b-4532-ae63-837208e58bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93822, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "见地", "is_correct": true, "explanation": "正确：“有什么见地”问的是对这件事的看法，与句意吻合。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是身体外形的一部分，不能用来问对这件事的看法。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资”指劳动报酬，与“关于这件事”的看法无关。"}, {"text": "力气", "is_correct": false, "explanation": "语义：“力气”指身体的力量，问“关于这件事有什么力气”说不通。"}], "explanations": {"见地": "正确：“有什么见地”问的是对这件事的看法，与句意吻合。", "身高": "体貌：“身高”是身体外形的一部分，不能用来问对这件事的看法。", "工资": "语义：“工资”指劳动报酬，与“关于这件事”的看法无关。", "力气": "语义：“力气”指身体的力量，问“关于这件事有什么力气”说不通。"}, "sentence_index": 0, "correct_answer": "见地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块见地很肥沃，适合种庄稼。", "explanation": "这里的“见地”被当成了土地，见地指看法，不能指田地，应说“土地”。"}, {"text": "这块布的见地有五米，正好够做一条裙子。", "explanation": "这里的“见地”被当成了长度，见地指对事情的看法，不能用“有五米”来说，应说“长度”。"}, {"text": "他的视力很差，见地模糊，连黑板都看不清。", "explanation": "这里的“见地”被当成了视力，这不是这个词的意思。见地指对事情的看法，不能形容眼睛看东西的能力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93822, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "见地", "is_correct": true, "explanation": "正确：“医生的见地”指医生对问题的看法，能让人改变方法，与句意吻合。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指身体的外形，不能让我们换了方法，句意不通。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指身体的温度，“医生的体温让我们换了方法”说不通。"}, {"text": "薪水", "is_correct": false, "explanation": "语义：“薪水”指工资，不能让人换方法，句意说不通。"}], "explanations": {"见地": "正确：“医生的见地”指医生对问题的看法，能让人改变方法，与句意吻合。", "身材": "体貌：“身材”指身体的外形，不能让我们换了方法，句意不通。", "体温": "语义：“体温”指身体的温度，“医生的体温让我们换了方法”说不通。", "薪水": "语义：“薪水”指工资，不能让人换方法，句意说不通。"}, "sentence_index": 6, "correct_answer": "见地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子的见地很软，可以拿来当枕头。", "explanation": "“软”指物体的质地，见地不是实物，不能说“软”，也不能当枕头用。"}, {"text": "这台新电脑的见地很快，打开文件只用一秒。", "explanation": "这里的“见地”被当成了电脑的运行速度，见地指对事情的看法，不能用来说机器快慢，应说“速度”。"}, {"text": "他今天没来上课的见地是生病了。", "explanation": "这里的“见地”被当成了原因，见地指看法，不能指没来上课的理由，应说“原因”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93822, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对这个方案很是见地。", "corrected_sentence": "他对这个方案很有见地。", "error_description": "搭配错误：“见地”是名词，要说“很有见地”，不能说“很是见地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93822, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他提出的一件见地让大家很佩服。", "corrected_sentence": "他提出的一个见地让大家很佩服。", "error_description": "量词错误：“见地”应用“个”，不用“件”（“件”多用于事情或物品，不能修饰见地）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
