INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93824, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "预先规定或确定。", "primary_collocate": null, "pronunciation": "shè dìng", "ipa": "ʂɤ˥˩ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "出发以前，我们先设定路线。", "target_word": "设定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司设定了今年的销售目标。", "target_word": "设定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校为考试设定了统一时间。", "target_word": "设定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛前要设定好比赛规则。", "target_word": "设定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生给病人设定了吃药时间。", "target_word": "设定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店设定的价格不高。", "target_word": "设定", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师为每个学生设定了不同的复习计划。", "target_word": "设定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们设定过三个不同的计划。", "target_word": "设定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司设定了每天最多工作八小时。", "target_word": "设定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先设定时间，再找地方。", "target_word": "设定", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "设定了", "label": "完成体"}, {"form": "设定过", "label": "经历体"}, {"form": "設定", "label": "繁体"}], "register": "中性", "sense_fingerprint": "预先规定或确定目标、规则、时间、价格等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6ac4a1-2343-42ab-ba2b-c2fbb8aa55f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93824, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "设定", "is_correct": true, "explanation": "正确。“设定”表示预先确定路线，符合“出发以前”的语境。"}, {"text": "摘", "is_correct": false, "explanation": "语义：“摘”指采摘，不能用于路线。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的宾语应是歌曲，不能说“唱路线”。"}, {"text": "拆", "is_correct": false, "explanation": "语义：路线不能被“拆”开，与预先确定路线的语境不符。"}], "explanations": {"设定": "正确。“设定”表示预先确定路线，符合“出发以前”的语境。", "摘": "语义：“摘”指采摘，不能用于路线。", "唱": "搭配：“唱”的宾语应是歌曲，不能说“唱路线”。", "拆": "语义：路线不能被“拆”开，与预先确定路线的语境不符。"}, "sentence_index": 0, "correct_answer": "设定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们设定了一家新公司。", "explanation": "这里应该用〈创办〉。创办用于企业、学校，〈设定〉用于预先确定的目标、规则、时间等，不用于开办机构。"}, {"text": "这座大楼是建筑师设定的。", "explanation": "这里应该用〈设计〉。设计用于建筑、产品等有形的东西，〈设定〉用于目标、规则、时间等，不说“设定大楼”。"}, {"text": "两个公司设定了合作关系。", "explanation": "这里应该用〈建立〉。建立用于关系、制度，〈设定〉用于预先规定的目标、规则、时间等，不用于合作关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93824, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "设定", "is_correct": true, "explanation": "正确。老师预先为学生确定了复习计划，符合语境。"}, {"text": "背诵", "is_correct": false, "explanation": "搭配：“背诵”的宾语应是课文、诗词，不能背诵计划。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”指清理，与“为学生安排计划”的语境不符。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”的对象通常是人或动物，不能说“喂计划”。"}], "explanations": {"设定": "正确。老师预先为学生确定了复习计划，符合语境。", "背诵": "搭配：“背诵”的宾语应是课文、诗词，不能背诵计划。", "打扫": "语义：“打扫”指清理，与“为学生安排计划”的语境不符。", "喂": "搭配：“喂”的对象通常是人或动物，不能说“喂计划”。"}, "sentence_index": 6, "correct_answer": "设定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他设定了一条鱼。", "explanation": "这里应该用〈钓〉。〈钓〉指用鱼竿、鱼线捕鱼，〈设定〉指预先规定时间、目标、规则，不能用于捕鱼。"}, {"text": "他设定了一封信。", "explanation": "这里应该用〈写〉。〈写〉用于信件、文章，〈设定〉指预先规定时间、目标、规则，不能用于写信。"}, {"text": "她设定了一条围巾。", "explanation": "这里应该用〈编织〉。〈编织〉用于围巾、毛衣等织物，〈设定〉指预先规定时间、目标、规则，不能用于织物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
