INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93825, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "许是答应别人，说好要做。", "primary_collocate": null, "pronunciation": "xǔ", "ipa": "ɕy˨˩˦", "syllable_count": 1, "sentences": [{"text": "妈妈许我考好就买新手机。", "target_word": "许", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸许我暑假带我去海边。", "target_word": "许", "complexity_tier": "T3", "furigana": "bàba xǔ wǒ shǔjià dài wǒ qù hǎibiān", "sentence_source": "generated"}, {"text": "他许了我一个小礼物，可是忘了。", "target_word": "许", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师许我们考完试就带我们去春游。", "target_word": "许", "complexity_tier": "T3", "furigana": "lǎoshī xǔ wǒmen kǎowán shì jiù dài wǒmen qù chūnyóu", "sentence_source": "generated"}, {"text": "姐姐许过我下个月请客。", "target_word": "许", "complexity_tier": "T3", "furigana": "jiějie xǔguo wǒ xiàge yuè qǐngkè", "sentence_source": "generated"}, {"text": "他许我下周还钱，可是一直没还。", "target_word": "许", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶许我过年给我买新衣服。", "target_word": "许", "complexity_tier": "T3", "furigana": "nǎinai xǔ wǒ guònián gěi wǒ mǎi xīn yīfu", "sentence_source": "generated"}, {"text": "我许过他一件事，就一定要做到。", "target_word": "许", "complexity_tier": "T3", "furigana": "wǒ xǔguo tā yí jiàn shì, jiù yídìng yào zuòdào", "sentence_source": "generated"}, {"text": "公司许他年底发一笔奖金。", "target_word": "许", "complexity_tier": "T3", "furigana": "gōngsī xǔ tā niándǐ fā yì bǐ jiǎngjīn", "sentence_source": "generated"}, {"text": "朋友许我下次带我去旅行，我很期待。", "target_word": "许", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "许了", "label": "完成体"}, {"form": "许过", "label": "经历体"}, {"form": "许诺", "label": "复合词"}], "register": "中性", "sense_fingerprint": "答应别人并说好以后要做某事，即许诺", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '239c4ca9-a8a6-4a41-8dd0-af48221448b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93825, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "许", "is_correct": true, "explanation": "许（xǔ，第三声）是本词，意思是答应别人、说好要做某事。"}, {"text": "虚", "is_correct": false, "explanation": "虚（xū，第一声）与许声调不同，意思是空、不实。"}, {"text": "举", "is_correct": false, "explanation": "举（jǔ）与许声母不同（j 与 x），意思是抬起。"}, {"text": "雨", "is_correct": false, "explanation": "雨（yǔ）与许声母不同（y 与 x），意思是从天上落下的水滴。"}, {"text": "续", "is_correct": false, "explanation": "续（xù，第四声）与许声调不同，意思是接着做下去。"}, {"text": "语", "is_correct": false, "explanation": "语（yǔ）与许声母不同（y 与 x），意思是话、言语。"}], "explanations": {"许": "许（xǔ，第三声）是本词，意思是答应别人、说好要做某事。", "虚": "虚（xū，第一声）与许声调不同，意思是空、不实。", "举": "举（jǔ）与许声母不同（j 与 x），意思是抬起。", "雨": "雨（yǔ）与许声母不同（y 与 x），意思是从天上落下的水滴。", "续": "续（xù，第四声）与许声调不同，意思是接着做下去。", "语": "语（yǔ）与许声母不同（y 与 x），意思是话、言语。"}, "sentence_index": null, "correct_answer": "许"}, "level_3": {"options": [{"text": "许", "is_correct": true, "explanation": "正确：“许”表示答应、许诺，与“考好就买新手机”的奖励承诺相符。"}, {"text": "禁止", "is_correct": false, "explanation": "语义：“禁止”表示不许做某事，与“考好就买”的奖励承诺相反。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”表示不接受，与“考好就买新手机”的承诺相冲突。"}, {"text": "赐予", "is_correct": false, "explanation": "语域：“赐予”是书面语，且语义是给予，与口语化的家庭承诺不协调。"}], "explanations": {"许": "正确：“许”表示答应、许诺，与“考好就买新手机”的奖励承诺相符。", "禁止": "语义：“禁止”表示不许做某事，与“考好就买”的奖励承诺相反。", "拒绝": "语义：“拒绝”表示不接受，与“考好就买新手机”的承诺相冲突。", "赐予": "语域：“赐予”是书面语，且语义是给予，与口语化的家庭承诺不协调。"}, "sentence_index": 0, "correct_answer": "许"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他许了我的道歉，我没有生气。", "explanation": "这里应该用〈接受〉。接受可接道歉、礼物等；“许”表示许诺，宾语须是能许给别人的东西或事情，不能接“道歉”。"}, {"text": "他许了我的建议，我很高兴。", "explanation": "这里应该用〈同意〉。同意可以接建议、意见；“许”是许诺，宾语须是能许给别人的东西或事情，不能接“建议”。"}, {"text": "他许了我这个问题，然后就走了。", "explanation": "这里应该用〈回答〉。回答可接问题；“许”表示许诺，宾语须是能许给别人的东西或事情，不能接“问题”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd20b62b5-68ab-48ae-88ed-a0f89a5c1533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93825, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "许", "is_correct": true, "explanation": "许（xǔ，第三声）是本词，意思是答应别人、说好要做某事。"}, {"text": "叙", "is_correct": false, "explanation": "叙（xù，第四声）与许声调不同，意思是叙述。"}, {"text": "取", "is_correct": false, "explanation": "取（qǔ）与许声母不同（q 与 x），意思是拿。"}, {"text": "洗", "is_correct": false, "explanation": "洗（xǐ）与许韵母不同（i 与 u），意思是清洗。"}, {"text": "徐", "is_correct": false, "explanation": "徐（xú，第二声）与许声调不同，意思是慢、缓慢。"}, {"text": "喜", "is_correct": false, "explanation": "喜（xǐ）与许韵母不同（i 与 u），意思是高兴。"}], "explanations": {"许": "许（xǔ，第三声）是本词，意思是答应别人、说好要做某事。", "叙": "叙（xù，第四声）与许声调不同，意思是叙述。", "取": "取（qǔ）与许声母不同（q 与 x），意思是拿。", "洗": "洗（xǐ）与许韵母不同（i 与 u），意思是清洗。", "徐": "徐（xú，第二声）与许声调不同，意思是慢、缓慢。", "喜": "喜（xǐ）与许韵母不同（i 与 u），意思是高兴。"}, "sentence_index": null, "correct_answer": "许"}, "level_3": {"options": [{"text": "许", "is_correct": true, "explanation": "正确：“许”表示答应、许诺，与“过年买新衣服”的承诺语境相符。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”表示清除灰尘，后面不能接“我过年给我买新衣服”这样的内容。"}, {"text": "恩赐", "is_correct": false, "explanation": "语域：“恩赐”是文言色彩很浓的书面词，与家中口语对话不符，且语义是施予恩惠。"}, {"text": "冒充", "is_correct": false, "explanation": "语义：“冒充”表示假扮别人，与“过年买新衣服”搭配不通。"}], "explanations": {"许": "正确：“许”表示答应、许诺，与“过年买新衣服”的承诺语境相符。", "打扫": "语义：“打扫”表示清除灰尘，后面不能接“我过年给我买新衣服”这样的内容。", "恩赐": "语域：“恩赐”是文言色彩很浓的书面词，与家中口语对话不符，且语义是施予恩惠。", "冒充": "语义：“冒充”表示假扮别人，与“过年买新衣服”搭配不通。"}, "sentence_index": 6, "correct_answer": "许"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朋友许了一声，就挂了电话。", "explanation": "这里应该用〈答应〉。“答应”可指应声回答（答应了一声）；许诺义的“许”不能这样用，它要求的是答应给予某物或做某事。"}, {"text": "他许了自己的错误，还想再来一次。", "explanation": "这里应该用〈承认〉。承认的对象可以是错误；“许”的宾语是可以许给别人的东西或事情，不能接“错误”。"}, {"text": "他许了我昨天就做完作业。", "explanation": "这里应该用〈说〉。许诺只能针对将来的事，不能指已经发生的事；“说”可用于已经发生的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd20b62b5-68ab-48ae-88ed-a0f89a5c1533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93825, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈许我了一个生日礼物。", "corrected_sentence": "妈妈许了我一个生日礼物。", "error_description": "错误：完成体“了”放在了宾语“我”后面，写成“许我了”。正确应为“许了我”，“了”紧跟动词“许”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd20b62b5-68ab-48ae-88ed-a0f89a5c1533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93825, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他许了过我一本新书。", "corrected_sentence": "他许了我一本新书。", "error_description": "错误：动词“许”后已有完成体“了”，又多加了体标“过”，写成“许了过”。两个体标不能同时用在同一动词后，应只保留“了”，写作“许了我”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd20b62b5-68ab-48ae-88ed-a0f89a5c1533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93826, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "禁止", "is_correct": true, "explanation": "禁止与“许”（允许）的意思相反，是此义的反义词。"}, {"text": "鼓励", "is_correct": false, "explanation": "鼓励是激励别人去做，与准许的意思无关，不构成反义关系。"}, {"text": "推荐", "is_correct": false, "explanation": "推荐是介绍好的人或事物，与准许无关，不是反义词。"}, {"text": "催促", "is_correct": false, "explanation": "催促是要求对方快做，与准许不构成反义关系。"}], "correct_answer": "禁止", "explanations": {"禁止": "禁止与“许”（允许）的意思相反，是此义的反义词。", "鼓励": "鼓励是激励别人去做，与准许的意思无关，不构成反义关系。", "推荐": "推荐是介绍好的人或事物，与准许无关，不是反义词。", "催促": "催促是要求对方快做，与准许不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd20b62b5-68ab-48ae-88ed-a0f89a5c1533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93826, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "禁止", "is_correct": true, "explanation": "禁止与“许”（允许）的意思相反，是此义的反义词。"}, {"text": "劝告", "is_correct": false, "explanation": "劝告是建议对方去做或不做，与准许不构成反义关系。"}, {"text": "赞扬", "is_correct": false, "explanation": "赞扬是称赞，与准许的意思无关，不是反义词。"}, {"text": "引导", "is_correct": false, "explanation": "引导是带领、指点，与准许不构成反义关系。"}], "correct_answer": "禁止", "explanations": {"禁止": "禁止与“许”（允许）的意思相反，是此义的反义词。", "劝告": "劝告是建议对方去做或不做，与准许不构成反义关系。", "赞扬": "赞扬是称赞，与准许的意思无关，不是反义词。", "引导": "引导是带领、指点，与准许不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd20b62b5-68ab-48ae-88ed-a0f89a5c1533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93826, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "允许、准许别人做某事。", "primary_collocate": null, "pronunciation": "xǔ", "ipa": "ɕy˨˩˦", "syllable_count": 1, "sentences": [{"text": "妈妈不许我玩手机。", "target_word": "许", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "图书馆里不许大声说话。", "target_word": "许", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生不许他喝酒。", "target_word": "许", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今天有雨，老师许我们早点回家。", "target_word": "许", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸只许我看一个小时电视。", "target_word": "许", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里不许停车，快开走吧。", "target_word": "许", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校不许学生带手机进教室。", "target_word": "许", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家里人不许他一个人去外地。", "target_word": "许", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶许我吃一块蛋糕，不能多吃。", "target_word": "许", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说过，作业没写完，不许看电视。", "target_word": "许", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不许", "label": "否定式"}, {"form": "允许", "label": "复合词"}, {"form": "许可", "label": "复合词"}], "register": "中性", "sense_fingerprint": "同意或准许别人做某事，常用否定式“不许”表示禁止", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '239c4ca9-a8a6-4a41-8dd0-af48221448b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93826, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "许", "is_correct": true, "explanation": "许（xǔ，第三声）是本词，意思是准许、同意别人做某事。"}, {"text": "虚", "is_correct": false, "explanation": "虚（xū，第一声）与许声调不同，意思是空、不实。"}, {"text": "取", "is_correct": false, "explanation": "取（qǔ）与许声母不同（q 与 x），意思是拿。"}, {"text": "续", "is_correct": false, "explanation": "续（xù，第四声）与许声调不同，意思是接着做下去。"}, {"text": "洗", "is_correct": false, "explanation": "洗（xǐ）与许韵母不同（i 与 u），意思是清洗。"}], "explanations": {"许": "许（xǔ，第三声）是本词，意思是准许、同意别人做某事。", "虚": "虚（xū，第一声）与许声调不同，意思是空、不实。", "取": "取（qǔ）与许声母不同（q 与 x），意思是拿。", "续": "续（xù，第四声）与许声调不同，意思是接着做下去。", "洗": "洗（xǐ）与许韵母不同（i 与 u），意思是清洗。"}, "sentence_index": null, "correct_answer": "许"}, "level_3": {"options": [{"text": "许", "is_correct": true, "explanation": "正确：“许”表示准许，与“不许玩手机”的禁止语境相符。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”表示谢意，与“不……我玩手机”的禁止语境不符。"}, {"text": "赐", "is_correct": false, "explanation": "语域：“赐”是文言词，表示给予，与口语化的禁止语境不符。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需接事物或人作宾语，不能直接接“玩手机”这样的动作。"}], "explanations": {"许": "正确：“许”表示准许，与“不许玩手机”的禁止语境相符。", "感谢": "语义：“感谢”表示谢意，与“不……我玩手机”的禁止语境不符。", "赐": "语域：“赐”是文言词，表示给予，与口语化的禁止语境不符。", "送": "配价：“送”需接事物或人作宾语，不能直接接“玩手机”这样的动作。"}, "sentence_index": 0, "correct_answer": "许"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天有雨，老师许我们的雨伞。", "explanation": "这里应该用〈借〉。“借”可接物品；“许”表示准许，宾语应是可以准许的行为，不能接“雨伞”。"}, {"text": "今天有雨，老师许了我的看法，我很高兴。", "explanation": "这里应该用〈赞成〉。赞成可接看法、意见；“许”表示准许，宾语应是可以准许的行为，不能接“看法”。"}, {"text": "我许老师早点回家。", "explanation": "这里应该用〈建议〉。“许”表示准许，要求说话人有权批准；学生不能“许”老师做事，应说〈建议〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd20b62b5-68ab-48ae-88ed-a0f89a5c1533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93826, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "许", "is_correct": true, "explanation": "许（xǔ，第三声）是本词，意思是准许、同意别人做某事。"}, {"text": "叙", "is_correct": false, "explanation": "叙（xù，第四声）与许声调不同，意思是叙述。"}, {"text": "雨", "is_correct": false, "explanation": "雨（yǔ）与许声母不同（y 与 x），意思是从天上落下的水滴。"}, {"text": "徐", "is_correct": false, "explanation": "徐（xú，第二声）与许声调不同，意思是慢、缓慢。"}, {"text": "喜", "is_correct": false, "explanation": "喜（xǐ）与许韵母不同（i 与 u），意思是高兴。"}], "explanations": {"许": "许（xǔ，第三声）是本词，意思是准许、同意别人做某事。", "叙": "叙（xù，第四声）与许声调不同，意思是叙述。", "雨": "雨（yǔ）与许声母不同（y 与 x），意思是从天上落下的水滴。", "徐": "徐（xú，第二声）与许声调不同，意思是慢、缓慢。", "喜": "喜（xǐ）与许韵母不同（i 与 u），意思是高兴。"}, "sentence_index": null, "correct_answer": "许"}, "level_3": {"options": [{"text": "许", "is_correct": true, "explanation": "正确：“许”表示准许，与“学校不许学生带手机”的禁止语境相符。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：“夸奖”表示称赞，与学校禁止带手机进教室的语境相悖。"}, {"text": "资助", "is_correct": false, "explanation": "配价：“资助”后接的是款项或事业，不能直接接“学生带手机进教室”这类动作。"}, {"text": "恩赐", "is_correct": false, "explanation": "语域：“恩赐”是文言词，与学校规定的口语语境不符，且语义是施予恩惠。"}], "explanations": {"许": "正确：“许”表示准许，与“学校不许学生带手机”的禁止语境相符。", "夸奖": "语义：“夸奖”表示称赞，与学校禁止带手机进教室的语境相悖。", "资助": "配价：“资助”后接的是款项或事业，不能直接接“学生带手机进教室”这类动作。", "恩赐": "语域：“恩赐”是文言词，与学校规定的口语语境不符，且语义是施予恩惠。"}, "sentence_index": 6, "correct_answer": "许"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸许了我的作业，说没有错。", "explanation": "这里应该用〈检查〉。“检查”可接作业；“许”表示准许，宾语应是可以准许的行为，不能接“作业”。"}, {"text": "老师许了我们的讲台。", "explanation": "这里应该用〈擦〉。“擦”可接桌子、讲台；“许”表示准许，宾语应是可以准许的行为，不能接“讲台”。"}, {"text": "妈妈许了我的鞋子。", "explanation": "这里应该用〈穿〉。“穿”可接鞋子；“许”表示准许，宾语应是可以准许的行为，不能接“鞋子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd20b62b5-68ab-48ae-88ed-a0f89a5c1533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93826, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈许不我吃甜食。", "corrected_sentence": "妈妈不许我吃甜食。", "error_description": "错误：否定副词“不”放在了“许”后面，写成“许不”。正确应为“不许”，“不”要放在动词前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd20b62b5-68ab-48ae-88ed-a0f89a5c1533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93826, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校不许了学生在教室里吃东西。", "corrected_sentence": "学校不许学生在教室里吃东西。", "error_description": "错误：否定句中“许”后多加了完成体“了”，应为“不许学生”。否定句中的动词后不能用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd20b62b5-68ab-48ae-88ed-a0f89a5c1533') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
