INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93830, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "彻底执行；把方针、政策等落实到行动中。", "primary_collocate": null, "pronunciation": "guàn chè", "ipa": "kwan⁵¹ ʈʂʰɤ⁵¹", "syllable_count": 2, "sentences": [{"text": "学校要贯彻国家的新政策。", "target_word": "贯彻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司没有贯彻老板的要求。", "target_word": "贯彻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一定要把这个办法贯彻到底。", "target_word": "贯彻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里认真贯彻了上级的指示。", "target_word": "贯彻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些规定在各个学校都贯彻得很好。", "target_word": "贯彻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要贯彻环保政策，让河水变干净。", "target_word": "贯彻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们贯彻着政府的新方针，工作很有效。", "target_word": "贯彻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划没有人贯彻，所以失败了。", "target_word": "贯彻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师们正在贯彻新的教育政策。", "target_word": "贯彻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说，必须贯彻公司的新规定。", "target_word": "贯彻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "贯彻了", "label": "体标"}, {"form": "贯彻着", "label": "体标"}, {"form": "贯彻过", "label": "体标"}, {"form": "贯彻执行", "label": "复合词"}], "register": "书面", "sense_fingerprint": "把方针、政策、规定等彻底落实", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ac5386f-a5c3-4a5f-b7d7-6ad2731789e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93830, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "贯彻", "is_correct": true, "explanation": "“贯彻”指把国家政策落实到行动中，与句中的“新政策”相符。"}, {"text": "养成", "is_correct": false, "explanation": "搭配：“养成”的对象是习惯、品质等，不能说“养成政策”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，与“政策”的内容不相容。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”用于具体的建筑、物品，不能说“拆政策”。"}], "explanations": {"贯彻": "“贯彻”指把国家政策落实到行动中，与句中的“新政策”相符。", "养成": "搭配：“养成”的对象是习惯、品质等，不能说“养成政策”。", "吃": "语义：“吃”指进食，与“政策”的内容不相容。", "拆": "搭配：“拆”用于具体的建筑、物品，不能说“拆政策”。"}, "sentence_index": 0, "correct_answer": "贯彻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河贯彻了整个城市。", "explanation": "这里应该用〈贯穿〉。“贯穿”可以说河流贯穿城市，“贯彻”指把方针、政策落实到行动中，不能用于河流。"}, {"text": "我们认真贯彻了那碗汤。", "explanation": "这里应该用〈喝〉。“贯彻”指把方针、政策落实到行动中，只用于指示、政策等抽象内容，不能用于汤等食物；喝汤要用〈喝〉。"}, {"text": "他贯彻了一块蛋糕给妹妹。", "explanation": "这里应该用〈切〉。“切”用于蛋糕等食物，“贯彻”指把方针、政策落实到行动中，不能用于蛋糕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93830, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "贯彻", "is_correct": true, "explanation": "“贯彻着”表示持续地落实方针，与“工作很有效”的结果相符。"}, {"text": "违背", "is_correct": false, "explanation": "语义：“违背”指不遵守，与后句“工作很有效”的因果关系不合。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：“撕”的对象是纸张等具体物，不能说“撕方针”。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：“忽视”指不重视，与“工作很有效”的前因不相容。"}], "explanations": {"贯彻": "“贯彻着”表示持续地落实方针，与“工作很有效”的结果相符。", "违背": "语义：“违背”指不遵守，与后句“工作很有效”的因果关系不合。", "撕": "搭配：“撕”的对象是纸张等具体物，不能说“撕方针”。", "忽视": "语义：“忽视”指不重视，与“工作很有效”的前因不相容。"}, "sentence_index": 6, "correct_answer": "贯彻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们已经贯彻完了这份作业。", "explanation": "这里应该用〈完成〉。“完成”可以用于作业、任务，“贯彻”用于方针、政策、指示，不用于作业。"}, {"text": "他终于贯彻了那件衣服。", "explanation": "这里应该用〈穿〉。“穿”用于衣服，“贯彻”用于方针、政策、指示，不用于衣服。"}, {"text": "经理认真贯彻了公司的责任。", "explanation": "这里应该用〈落实〉。“落实”可以用于责任、任务，而“贯彻”用于方针、政策、指示，不用于责任。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93830, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校认真贯彻了着国家的新政策。", "corrected_sentence": "学校认真贯彻了国家的新政策。", "error_description": "“了”和“着”都是动态助词，不能同时用在同一个动词后；“贯彻了”表示动作完成，应去掉“着”，写作“认真贯彻了国家的新政策”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93830, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们明天贯彻了政府的新方针。", "corrected_sentence": "他们明天贯彻政府的新方针。", "error_description": "错误：“明天”指将来，句中不能用表示完成的“了”，应去掉“了”，即“他们明天贯彻政府的新方针”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93831, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93831, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93831, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "账户是存放你的钱的地方，记着你有多少钱。", "primary_collocate": null, "pronunciation": "zhàng hù", "ipa": "ʈʂɑŋ⁵¹ xu⁵¹", "syllable_count": 2, "sentences": [{"text": "我在银行开了一个账户。", "target_word": "账户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的账户里只有一百块钱。", "target_word": "账户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把钱存到我的账户里。", "target_word": "账户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每个月往我的账户打钱。", "target_word": "账户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忘了账户的密码，进不去。", "target_word": "账户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个账户上还有很多钱。", "target_word": "账户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有两个银行账户。", "target_word": "账户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想看看账户里还有多少钱。", "target_word": "账户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的账户今天没有收到钱。", "target_word": "账户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸给弟弟开了一个新账户。", "target_word": "账户", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "银行账户", "label": "复合"}, {"form": "賬戶", "label": "繁体"}], "register": "中性", "sense_fingerprint": "存钱并记录余额的户头", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6ac4a1-2343-42ab-ba2b-c2fbb8aa55f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93831, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "账户", "is_correct": true, "explanation": "正确。“开了一个账户”是在银行开设存钱户头，与句意相符。"}, {"text": "电影", "is_correct": false, "explanation": "语义：电影是看的作品，不能在银行“开”，与开户的语境不符。"}, {"text": "密码", "is_correct": false, "explanation": "搭配：密码要“设置”，不能用“开”来搭配，“开一个密码”不成立。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：食堂是用餐的场所，与在银行办理存钱的情境不符。"}], "explanations": {"账户": "正确。“开了一个账户”是在银行开设存钱户头，与句意相符。", "电影": "语义：电影是看的作品，不能在银行“开”，与开户的语境不符。", "密码": "搭配：密码要“设置”，不能用“开”来搭配，“开一个密码”不成立。", "食堂": "语义：食堂是用餐的场所，与在银行办理存钱的情境不符。"}, "sentence_index": 0, "correct_answer": "账户"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月的账户是三百块。", "explanation": "这里应该用〈账单〉。账户是存钱的户头，不能用来表示每月应付的金额；应说“这个月的账单是三百块”。"}, {"text": "我的账户放在抽屉里。", "explanation": "这里应该用〈存折〉。账户是银行里记账的户头，看不见摸不着，放不进抽屉；存折是纸质的，应说“我的存折放在抽屉里”。"}, {"text": "他是这个家的账户。", "explanation": "这里应该用〈户主〉。账户是资金往来的户头，不指人；应说“他是这个家的户主”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93831, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "账户", "is_correct": true, "explanation": "正确。“他有两个银行账户”指他在两家银行或两处开设的户头，与句意相符。"}, {"text": "行长", "is_correct": false, "explanation": "语义：“行长”指人，“他有两个银行行长”在逻辑上不成立。"}, {"text": "大厅", "is_correct": false, "explanation": "语义：“大厅”是建筑中的空间，不能说一个人拥有两个银行大厅。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“工资”不用量词“个”来数，说“有两个银行工资”不成立。"}], "explanations": {"账户": "正确。“他有两个银行账户”指他在两家银行或两处开设的户头，与句意相符。", "行长": "语义：“行长”指人，“他有两个银行行长”在逻辑上不成立。", "大厅": "语义：“大厅”是建筑中的空间，不能说一个人拥有两个银行大厅。", "工资": "搭配：“工资”不用量词“个”来数，说“有两个银行工资”不成立。"}, "sentence_index": 6, "correct_answer": "账户"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈给姐姐开了一张账户。", "explanation": "这里应该用〈个〉，而不是〈张〉。“张”多用于纸、卡片等平面物，账户是抽象的户头，量词用“个”。"}, {"text": "他给公司开了一台账户。", "explanation": "这里应该用〈个〉，而不是〈台〉。“台”用于机器、设备，账户是抽象的户头，量词用“个”。"}, {"text": "他在这本账户上写下了每天的心情。", "explanation": "这里应该用〈日记〉。账户是资金往来的户头，不能用来写心情；应说“他在这本日记上写下了每天的心情。”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93831, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在银行办了一张账户。", "corrected_sentence": "他在银行办了一个账户。", "error_description": "量词错误：账户的量词应为“个”，“张”多用于纸张、卡片。正确说法是“他在银行办了一个账户。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93831, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈给女儿修了一个新账户。", "corrected_sentence": "妈妈给女儿开了一个新账户。", "error_description": "搭配错误：“修”用于机器、房屋、道路等有形物，不能修账户；“账户”应与“开”搭配，说“开一个账户”。正确说法是“妈妈给女儿开了一个新账户。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
