INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93832, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93832, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在银行或网络平台上开设的、用于记录资金往来的户头。", "primary_collocate": null, "pronunciation": "zhàng hù", "ipa": "ʈʂɑŋ⁵¹ xu⁵¹", "syllable_count": 2, "sentences": [{"text": "你需要先注册一个网络账户。", "target_word": "账户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的账户上周收到一笔钱。", "target_word": "账户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个支付账户可以买东西。", "target_word": "账户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手机登录了自己的账户。", "target_word": "账户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网店账户里的钱不能马上取出来。", "target_word": "账户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请核对一下公司账户的信息。", "target_word": "账户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在网上开设了一个理财账户。", "target_word": "账户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个账户每天都会记录钱的进出。", "target_word": "账户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把两个账户的钱放在一起了。", "target_word": "账户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店的账户里有一笔钱没有记录。", "target_word": "账户", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "网络账户", "label": "复合"}, {"form": "賬戶", "label": "繁体"}], "register": "中性", "sense_fingerprint": "银行或网络平台上记录资金往来的户头", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6ac4a1-2343-42ab-ba2b-c2fbb8aa55f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93832, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "账户", "is_correct": true, "explanation": "正确。“注册一个网络账户”指在网络平台上开设户头，与句意相符。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“注册”网络账户的对象是账号，而非通讯工具；“注册一个网络手机”不成立，与网络账户的情境不符。"}, {"text": "邮件", "is_correct": false, "explanation": "搭配：“注册”后接的是邮箱或账号，不能接“邮件”，“注册邮件”不成立。"}, {"text": "文章", "is_correct": false, "explanation": "语义：“文章”是文字作品，不能被注册，与网络注册的情境不符。"}], "explanations": {"账户": "正确。“注册一个网络账户”指在网络平台上开设户头，与句意相符。", "手机": "语义：“注册”网络账户的对象是账号，而非通讯工具；“注册一个网络手机”不成立，与网络账户的情境不符。", "邮件": "搭配：“注册”后接的是邮箱或账号，不能接“邮件”，“注册邮件”不成立。", "文章": "语义：“文章”是文字作品，不能被注册，与网络注册的情境不符。"}, "sentence_index": 0, "correct_answer": "账户"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个网站是一个知识账户。", "explanation": "这里应该用〈门户〉。门户是网站的入口，账户是资金往来的户头，不能用来指网站；应说“这个网站是一个知识门户”。"}, {"text": "她是这家网店的账户。", "explanation": "这里应该用〈店主〉。账户是资金往来的户头，不指人；应说“她是这家网店的店主”。"}, {"text": "我们周末去账户露营。", "explanation": "这里应该用〈户外〉。账户是资金户头，不表示野外场所；应说“我们周末去户外露营”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93832, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "账户", "is_correct": true, "explanation": "正确。“开设一个理财账户”指开设用于理财的资金户头，与句意相符。"}, {"text": "菜谱", "is_correct": false, "explanation": "语义：“菜谱”是烹饪用的书，与理财的情境不符。"}, {"text": "餐厅", "is_correct": false, "explanation": "语义：“餐厅”是用餐的场所，不能作为“理财”的开设对象。"}, {"text": "手术", "is_correct": false, "explanation": "搭配：“开设”多用于商店、课程、账户，不能用来说“开设手术”。"}], "explanations": {"账户": "正确。“开设一个理财账户”指开设用于理财的资金户头，与句意相符。", "菜谱": "语义：“菜谱”是烹饪用的书，与理财的情境不符。", "餐厅": "语义：“餐厅”是用餐的场所，不能作为“理财”的开设对象。", "手术": "搭配：“开设”多用于商店、课程、账户，不能用来说“开设手术”。"}, "sentence_index": 6, "correct_answer": "账户"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在网上开了一部账户。", "explanation": "这里应该用〈个〉，而不是〈部〉。“部”用于手机、电影等，账户是抽象的户头，量词用“个”。"}, {"text": "我们那台账户很快就要过期了。", "explanation": "这里应该用〈个〉，而不是〈台〉。“台”用于机器、设备，账户是抽象的户头，量词用“个”。"}, {"text": "他在这本账户上写下了每天的心情。", "explanation": "这里应该用〈日记〉。账户是资金往来的户头，不能用来写心情；应说“他在这本日记上写下了每天的心情。”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93832, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在网上办了一张账户。", "corrected_sentence": "他在网上办了一个账户。", "error_description": "量词错误：账户的量词应为“个”，不能用“张”。正确说法是“他在网上办了一个账户。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93832, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她修理了一个网络账户。", "corrected_sentence": "她申请了一个网络账户。", "error_description": "搭配错误：“修理”用于机器、物品，不能修理账户；“账户”应说“申请”。正确说法是“她申请了一个网络账户。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
