INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93833, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "办事是去做一件需要做的事情。", "primary_collocate": null, "pronunciation": "bàn shì", "ipa": "pan⁵¹ ʂɻ̩⁵¹", "syllable_count": 2, "sentences": [{"text": "妈妈出门办事，晚上才回来。", "target_word": "办事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我下午要去办事，不能陪你。", "target_word": "办事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他请了半天假去办事。", "target_word": "办事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸开车到城里办事。", "target_word": "办事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我要出去办事，一会儿就回来。", "target_word": "办事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她去区政府办事，排了很久的队。", "target_word": "办事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天我进城办事，顺便看看朋友。", "target_word": "办事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说要去外地办事，下周回来。", "target_word": "办事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你去哪儿？我去邮局办事。", "target_word": "办事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王带着材料去办事了。", "target_word": "办事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "办过事", "label": "体标（过）"}, {"form": "办事员", "label": "复合词"}, {"form": "办事处", "label": "复合词"}], "register": "中性", "sense_fingerprint": "外出去办一件具体要办的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4215d43d-f30b-4b99-bb09-a9960ea2a2a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93833, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "办事", "is_correct": true, "explanation": "正确答案。读音 bàn shì，指外出去办具体的事情。"}, {"text": "干事", "is_correct": false, "explanation": "gàn 与 bàn 的声母不同（g 与 b），意思是机关里做具体工作的人员。"}, {"text": "版式", "is_correct": false, "explanation": "bǎn（第三声）与 bàn（第四声）声调不同，意思是版面的格式。"}, {"text": "板式", "is_correct": false, "explanation": "bǎn（第三声）与 bàn（第四声）声调不同，意思是板的样式。"}], "explanations": {"办事": "正确答案。读音 bàn shì，指外出去办具体的事情。", "干事": "gàn 与 bàn 的声母不同（g 与 b），意思是机关里做具体工作的人员。", "版式": "bǎn（第三声）与 bàn（第四声）声调不同，意思是版面的格式。", "板式": "bǎn（第三声）与 bàn（第四声）声调不同，意思是板的样式。"}, "sentence_index": null, "correct_answer": "办事"}, "level_3": {"options": [{"text": "办事", "is_correct": true, "explanation": "正确。“出门办事”指出去办具体的事情。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：出门去“睡觉”不合常理，与外出办事的意思不符。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“出门生病”说不通，与“晚上才回来”的叙述不合。"}, {"text": "搞事", "is_correct": false, "explanation": "语域：“搞事”是口语，多指惹麻烦，不用于描述正常的外出。"}], "explanations": {"办事": "正确。“出门办事”指出去办具体的事情。", "睡觉": "语义：出门去“睡觉”不合常理，与外出办事的意思不符。", "生病": "语义：“出门生病”说不通，与“晚上才回来”的叙述不合。", "搞事": "语域：“搞事”是口语，多指惹麻烦，不用于描述正常的外出。"}, "sentence_index": 0, "correct_answer": "办事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台冰箱去城里办事了。", "explanation": "这里应该用〈运送〉。“办事”指人去处理事务，冰箱只能被运送，不能自己去办事。"}, {"text": "这块石头去城里办事了。", "explanation": "这里应该用〈搬运〉。“办事”指人去处理事务，石头只能被搬运。"}, {"text": "这辆自行车去城里办事了。", "explanation": "这里应该用〈骑〉。“办事”指人去处理事务，自行车只能被骑，不能自己去办事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93833, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "办事", "is_correct": true, "explanation": "正确。“进城办事，顺便看看朋友”说的是进城去办具体的事情。"}, {"text": "出生", "is_correct": false, "explanation": "语义：人不能“进城出生”后再“顺便看看朋友”，前后不合。"}, {"text": "生孩子", "is_correct": false, "explanation": "语义：“进城生孩子”不是外出办事的情况，前后不合。"}, {"text": "睡懒觉", "is_correct": false, "explanation": "搭配：“进城睡懒觉”与“顺便看看朋友”的说法不搭配。"}], "explanations": {"办事": "正确。“进城办事，顺便看看朋友”说的是进城去办具体的事情。", "出生": "语义：人不能“进城出生”后再“顺便看看朋友”，前后不合。", "生孩子": "语义：“进城生孩子”不是外出办事的情况，前后不合。", "睡懒觉": "搭配：“进城睡懒觉”与“顺便看看朋友”的说法不搭配。"}, "sentence_index": 6, "correct_answer": "办事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这摞材料去办事了。", "explanation": "这里应该用〈被送去〉。“办事”指人去处理事务，材料只能被送去，不能自己去办事。"}, {"text": "这把铲子去办事了。", "explanation": "这里应该用〈放置〉。“办事”指人去处理事务，铲子只能被放置，不能自己去办事。"}, {"text": "这台饮水机的工作是办事，每天在公司烧水。", "explanation": "这里应该用〈供应〉。“办事”指人处理事务，饮水机只能说“供应”或“烧水”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93833, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天去邮局办着一次事，很快就回来了。", "corrected_sentence": "他昨天去邮局办了一次事，很快就回来了。", "error_description": "离合词“办事”带动量补语“一次”表示已完成的动作时，“办”后要用“了”，应说“办了一次事”。“着”表示持续，不能和“一次”连用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93833, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去城里办事得很快，下午就回来了。", "corrected_sentence": "他去城里办事办得很快，下午就回来了。", "error_description": "动词“办事”后接补语“得”时，要重复动词，应说“办事办得很快”，不能说“办事得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
