INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93834, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "处理事务；做事情。", "primary_collocate": null, "pronunciation": "bàn shì", "ipa": "pan⁵¹ ʂɻ̩⁵¹", "syllable_count": 2, "sentences": [{"text": "他在银行办事很认真。", "target_word": "办事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王经理办事很有效率。", "target_word": "办事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你放心，他办事一向很可靠。", "target_word": "办事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张办事公道，大家都信他。", "target_word": "办事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他办事太慢，客户都等急了。", "target_word": "办事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人办事不讲规矩。", "target_word": "办事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李刚来，还不懂怎么办事。", "target_word": "办事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在机关办事已经三年了。", "target_word": "办事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她办事利索，从不拖拉。", "target_word": "办事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他办事总是先想清楚再动手。", "target_word": "办事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "办过事", "label": "体标（过）"}, {"form": "办事员", "label": "复合词"}, {"form": "办事处", "label": "复合词"}], "register": "中性", "sense_fingerprint": "处理事务、做事的方式或能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4215d43d-f30b-4b99-bb09-a9960ea2a2a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93834, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "办事", "is_correct": true, "explanation": "正确答案。读音 bàn shì，指处理事务、做事情。"}, {"text": "干事", "is_correct": false, "explanation": "gàn 与 bàn 的声母不同（g 与 b），意思是机关里做具体工作的人员。"}, {"text": "版式", "is_correct": false, "explanation": "bǎn（第三声）与 bàn（第四声）声调不同，意思是版面的格式。"}, {"text": "板式", "is_correct": false, "explanation": "bǎn（第三声）与 bàn（第四声）声调不同，意思是板的样式。"}], "explanations": {"办事": "正确答案。读音 bàn shì，指处理事务、做事情。", "干事": "gàn 与 bàn 的声母不同（g 与 b），意思是机关里做具体工作的人员。", "版式": "bǎn（第三声）与 bàn（第四声）声调不同，意思是版面的格式。", "板式": "bǎn（第三声）与 bàn（第四声）声调不同，意思是板的样式。"}, "sentence_index": null, "correct_answer": "办事"}, "level_3": {"options": [{"text": "办事", "is_correct": true, "explanation": "正确。“办事很认真”说的是处理事务的态度。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌不是处理事务，“在银行唱歌很认真”说不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：银行里不能游泳，与“认真”也不搭。"}, {"text": "搞事", "is_correct": false, "explanation": "语域：“搞事”是口语，多指惹事，不适合描述银行里的工作。"}], "explanations": {"办事": "正确。“办事很认真”说的是处理事务的态度。", "唱歌": "语义：唱歌不是处理事务，“在银行唱歌很认真”说不通。", "游泳": "语义：银行里不能游泳，与“认真”也不搭。", "搞事": "语域：“搞事”是口语，多指惹事，不适合描述银行里的工作。"}, "sentence_index": 0, "correct_answer": "办事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子办事很认真。", "explanation": "这里应该用〈结实〉。“办事”指人处理事务，椅子不能办事，形容椅子应说“结实”。"}, {"text": "这张桌子办事很认真。", "explanation": "这里应该用〈结实〉。“办事”指人处理事务，桌子不能办事，形容桌子应说“结实”。"}, {"text": "这盏灯办事很认真。", "explanation": "这里应该用〈发光〉。“办事”指人处理事务，灯只能说“发光”，不能“办事”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93834, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "办事", "is_correct": true, "explanation": "正确。“不懂怎么办事”指不知道如何处理事务。"}, {"text": "退休", "is_correct": false, "explanation": "语义：小李刚来，不可能是退休的问题。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”不能用在“不懂怎么……”的语境里。"}, {"text": "哭泣", "is_correct": false, "explanation": "语域：“哭泣”偏书面，与这里的口语叙述不协调，也不是要学的技能。"}], "explanations": {"办事": "正确。“不懂怎么办事”指不知道如何处理事务。", "退休": "语义：小李刚来，不可能是退休的问题。", "出生": "语义：“出生”不能用在“不懂怎么……”的语境里。", "哭泣": "语域：“哭泣”偏书面，与这里的口语叙述不协调，也不是要学的技能。"}, "sentence_index": 6, "correct_answer": "办事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器办事很认真。", "explanation": "这里应该用〈运转〉。“办事”指人处理事务，机器只能说“运转”。"}, {"text": "这辆车办事很认真。", "explanation": "这里应该用〈行驶〉。“办事”指人处理事务，车只能说“行驶”。"}, {"text": "这个水龙头办事很认真。", "explanation": "这里应该用〈出水〉。“办事”指人处理事务，水龙头只能说“出水”，不能“办事”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93834, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在财务科办事了很细心。", "corrected_sentence": "她在财务科办事很细心。", "error_description": "“办事”后面的“了”表示完成，此处描述做事的态度，不用“了”，应说“办事很细心”，不能说“办事了很细心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93834, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他办事得很快，客户都很满意。", "corrected_sentence": "他办事办得很快，客户都很满意。", "error_description": "动词“办事”后接补语“得”时，要重复动词，应说“办事办得很快”，不能说“办事得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
