INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93836, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向上级或下级、公众传达情况或信息。", "primary_collocate": null, "pronunciation": "tōng bào", "ipa": "tʰʊŋ˥ pɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "公司向全体员工通报了会议结果。", "target_word": "通报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院每天向社会通报最新情况。", "target_word": "通报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校通报了这次考试的情况。", "target_word": "通报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警方及时通报了事故原因。", "target_word": "通报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理把工作进展通报给总公司。", "target_word": "通报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府会向公众通报最新消息。", "target_word": "通报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你向领导通报一下今天的情况。", "target_word": "通报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们没有向我们通报过这件事。", "target_word": "通报", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部门每周通报一次工作进度。", "target_word": "通报", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市里已经通报了天气变化的情况。", "target_word": "通报", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "通报了", "label": "完成体"}, {"form": "通报过", "label": "经历体"}, {"form": "通報", "label": "繁体"}], "register": "正式", "sense_fingerprint": "机关、单位向上下级或公众正式传达情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6ac4a1-2343-42ab-ba2b-c2fbb8aa55f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93836, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "请示", "is_correct": false, "explanation": "语义：请示是下级向上级请求指示，员工不是上级，与“向全体员工”传达结果的语境不符。"}, {"text": "通报", "is_correct": true, "explanation": "正确：通报表示向员工传达会议结果，符合“向全体员工”的语境。"}, {"text": "感谢", "is_correct": false, "explanation": "搭配：“感谢”的对象是人或帮助，不能用于“会议结果”。"}, {"text": "讨论", "is_correct": false, "explanation": "配价：“讨论”是多方商议，不能用“向全体员工”引出对象，与单向传达不符。"}], "explanations": {"请示": "语义：请示是下级向上级请求指示，员工不是上级，与“向全体员工”传达结果的语境不符。", "通报": "正确：通报表示向员工传达会议结果，符合“向全体员工”的语境。", "感谢": "搭配：“感谢”的对象是人或帮助，不能用于“会议结果”。", "讨论": "配价：“讨论”是多方商议，不能用“向全体员工”引出对象，与单向传达不符。"}, "sentence_index": 0, "correct_answer": "通报"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天通报了一顿饭。", "explanation": "这里应该用〈吃〉。通报的对象是情况或信息，吃饭要用“吃”。"}, {"text": "他通报了一棵大树。", "explanation": "这里应该用〈种〉。通报的对象是情况或信息，树不能作为通报的内容，种树要用“种”。"}, {"text": "我给朋友通报了一个笑话。", "explanation": "这里应该用〈讲〉。通报是正式传达情况或信息，讲笑话要用“讲”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93836, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”多用于树枝、头发，不能用于“情况”。"}, {"text": "通报", "is_correct": true, "explanation": "正确：通报表示向领导传达今天的情况，与“向领导”搭配。"}, {"text": "赞美", "is_correct": false, "explanation": "搭配：“赞美”的对象是人或事迹，不说“赞美情况”。"}, {"text": "报销", "is_correct": false, "explanation": "搭配：“报销”针对费用或开支，不能用于“情况”。"}], "explanations": {"修剪": "搭配：“修剪”多用于树枝、头发，不能用于“情况”。", "通报": "正确：通报表示向领导传达今天的情况，与“向领导”搭配。", "赞美": "搭配：“赞美”的对象是人或事迹，不说“赞美情况”。", "报销": "搭配：“报销”针对费用或开支，不能用于“情况”。"}, "sentence_index": 6, "correct_answer": "通报"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "作家通报了一篇新小说。", "explanation": "这里应该用〈发表〉。通报传达的是情况或信息，发表作品要用“发表”。"}, {"text": "他通报了一首好听的歌。", "explanation": "这里应该用〈唱〉。通报的对象是情况或信息，唱歌要用“唱”。"}, {"text": "老师通报了一堆作业。", "explanation": "这里应该用〈批改〉。通报不能用于作业，批改作业才用“批改”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93836, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天会议上我向大家通报了工作进展。", "corrected_sentence": "明天会议上我向大家通报工作进展。", "error_description": "“了”误用：“明天”表示将来，动作尚未发生，不能用“了”。应去掉“了”，说“通报工作进展”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93836, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市里通报了过天气变化的情况。", "corrected_sentence": "市里通报过天气变化的情况。", "error_description": "“了过”重复：“过”已表示经历，不能再加“了”。应去掉“了”，说“通报过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
