INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93837, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "过去时是说已经过去的事时用的说法。", "primary_collocate": null, "pronunciation": "guò qù shí", "ipa": "kwo˥˩ tɕʰy˥˩ ʂɻ̩˧˥", "syllable_count": 3, "sentences": [{"text": "说昨天的事，英语要用过去时。", "target_word": "过去时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲故事的时候一直用过去时。", "target_word": "过去时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么说过去时。", "target_word": "过去时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个句子用的是过去时。", "target_word": "过去时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说上个月的旅行，要用过去时。", "target_word": "过去时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我常常把过去时说错。", "target_word": "过去时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说已经发生的事，可以用过去时。", "target_word": "过去时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书先讲现在时，再讲过去时。", "target_word": "过去时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写日记时，我们多用过去时。", "target_word": "过去时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你用过去时说一遍昨天的事吧。", "target_word": "过去时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一般过去时", "label": "复合"}, {"form": "过去完成时", "label": "复合"}, {"form": "過去時", "label": "繁体"}], "register": "中性", "sense_fingerprint": "讲已经发生的事时所用的说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01308c1-157a-474f-8335-9b2ec1714ab6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93837, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "过去时", "is_correct": true, "explanation": "正确。句中说的是昨天的事，已经发生，应用过去时。"}, {"text": "现在时", "is_correct": false, "explanation": "语义：“昨天的事”已经发生，用现在时表示当下，与“昨天”矛盾。"}, {"text": "将来时", "is_correct": false, "explanation": "语义：“将来时”表示尚未发生的事，与“昨天的事”冲突。"}, {"text": "命令式", "is_correct": false, "explanation": "语义：“命令式”用于发出指令，与“说昨天的事”无关。"}], "explanations": {"过去时": "正确。句中说的是昨天的事，已经发生，应用过去时。", "现在时": "语义：“昨天的事”已经发生，用现在时表示当下，与“昨天”矛盾。", "将来时": "语义：“将来时”表示尚未发生的事，与“昨天的事”冲突。", "命令式": "语义：“命令式”用于发出指令，与“说昨天的事”无关。"}, "sentence_index": 0, "correct_answer": "过去时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我过去时常常去图书馆。", "explanation": "这里应该用〈以前〉。“过去时”是表示时态的语法术语，不能当作“从前”的时间副词；表示“从前”要说“以前”。"}, {"text": "说明天的安排，要用过去时。", "explanation": "这里应该用〈将来时〉。明天的安排还没有发生，要用将来时；过去时只用于已经发生的事。"}, {"text": "他每天早上都跑步，这句要用过去时。", "explanation": "这里应该用〈现在时〉。每天重复的动作是现在的习惯，要用现在时；过去时只用于过去的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '565832eb-6e16-435c-bc95-9b8b731e7e39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93837, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过去时", "is_correct": true, "explanation": "正确。“已经发生的事”用过去时来说。"}, {"text": "进行时", "is_correct": false, "explanation": "语义：“进行时”表示正在发生的事，与“已经发生的事”不符。"}, {"text": "疑问式", "is_correct": false, "explanation": "语义：“疑问式”用于提问，与陈述已发生的事不符。"}, {"text": "比较级", "is_correct": false, "explanation": "语义：“比较级”用于比较两样东西，不用来说已经发生的事。"}], "explanations": {"过去时": "正确。“已经发生的事”用过去时来说。", "进行时": "语义：“进行时”表示正在发生的事，与“已经发生的事”不符。", "疑问式": "语义：“疑问式”用于提问，与陈述已发生的事不符。", "比较级": "语义：“比较级”用于比较两样东西，不用来说已经发生的事。"}, "sentence_index": 6, "correct_answer": "过去时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们一起度过了很多美好的过去时。", "explanation": "这里应该用〈时光〉。“过去时”是语法术语，指动词的时态，不指一段时间；“度过”的对象要用“时光”。"}, {"text": "正在发生的事，要用过去时。", "explanation": "这里应该用〈进行时〉。正在发生的事用进行时；过去时只表示已经发生或过去的动作。"}, {"text": "下个星期要做的事，要用过去时。", "explanation": "这里应该用〈将来时〉。下个星期的事还没有发生，要用将来时；过去时只用于已经发生的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '565832eb-6e16-435c-bc95-9b8b731e7e39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93837, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只过去时的规则比较多。", "corrected_sentence": "这种过去时的规则比较多。", "error_description": "量词错误：“过去时”是语法术语，应说“这种过去时”；“只”用于动物或成对的东西，不用于时态。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '565832eb-6e16-435c-bc95-9b8b731e7e39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93837, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个学生已经喝完了过去时的用法。", "corrected_sentence": "这个学生已经学会了过去时的用法。", "error_description": "搭配错误：“喝”不能搭配“过去时的用法”，应说“学会了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '565832eb-6e16-435c-bc95-9b8b731e7e39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
