INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93840, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "挑选出来。", "primary_collocate": null, "pronunciation": "xuǎn chū", "ipa": "ɕɥan˨˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "老师从全班选出了十名学生。", "target_word": "选出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们选出了最好的照片。", "target_word": "选出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家投票，选出新的班长。", "target_word": "选出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从一堆苹果里选出最红的。", "target_word": "选出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司选出三个人去北京开会。", "target_word": "选出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你选出正确的答案。", "target_word": "选出", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "比赛后，评委选出了第一名。", "target_word": "选出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈从书店选出了几本好书。", "target_word": "选出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校选出了一些同学去参加比赛。", "target_word": "选出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我从这些画里选出了一张。", "target_word": "选出", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "选出了", "label": "完成体"}, {"form": "选出过", "label": "经历体"}, {"form": "选出来", "label": "趋向补语"}], "register": "中性", "sense_fingerprint": "从一群中挑选出若干个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43035244-64f2-4d65-bc07-110cd48c7371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93840, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "选出", "is_correct": true, "explanation": "正确答案：选出（xuǎn chū），意思是从若干人或物中挑出来。"}, {"text": "显出", "is_correct": false, "explanation": "xiǎn（第三声）与 xuǎn（第三声）韵母不同（ian 与 uan），意思是显露出来，不是挑选。"}, {"text": "选区", "is_correct": false, "explanation": "第二音节 qū 与 chū 声母不同（q 与 ch），第一音节相同，意思是选举的区域。"}, {"text": "现出", "is_correct": false, "explanation": "xiàn（第四声）与 xuǎn（第三声）韵母和声调都不同，意思是显现出来。"}], "explanations": {"选出": "正确答案：选出（xuǎn chū），意思是从若干人或物中挑出来。", "显出": "xiǎn（第三声）与 xuǎn（第三声）韵母不同（ian 与 uan），意思是显露出来，不是挑选。", "选区": "第二音节 qū 与 chū 声母不同（q 与 ch），第一音节相同，意思是选举的区域。", "现出": "xiàn（第四声）与 xuǎn（第三声）韵母和声调都不同，意思是显现出来。"}, "sentence_index": null, "correct_answer": "选出"}, "level_3": {"options": [{"text": "选出", "is_correct": true, "explanation": "正确：“选出”表示从全班挑出若干人，与“从全班”相呼应。"}, {"text": "打", "is_correct": false, "explanation": "语义：“打”是击打，句子读成打了十名学生，与“从全班挑选”的意思不合。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：“从全班”表示来源，“增加”指数量增长，不能说从全班增加了十名学生。"}, {"text": "出现", "is_correct": false, "explanation": "语义：“出现”指显露、露面，与老师从全班挑选学生的意思不合。"}], "explanations": {"选出": "正确：“选出”表示从全班挑出若干人，与“从全班”相呼应。", "打": "语义：“打”是击打，句子读成打了十名学生，与“从全班挑选”的意思不合。", "增加": "搭配：“从全班”表示来源，“增加”指数量增长，不能说从全班增加了十名学生。", "出现": "语义：“出现”指显露、露面，与老师从全班挑选学生的意思不合。"}, "sentence_index": 0, "correct_answer": "选出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他选出了我的毛病，让我很不舒服。", "explanation": "这里应该用〈挑出〉。挑出毛病是固定说法，选出强调从若干对象中定下一个，不能与“毛病”搭配。"}, {"text": "面对困难，他选出了逃避。", "explanation": "这里应该用〈选择〉。选出要从一群具体的人或物中挑出，不能用于“逃避”这类抽象的态度。"}, {"text": "我们选出了周末去爬山。", "explanation": "这里应该用〈选定〉。选出的对象是从一群事物中挑出的，不能用来确定一个出行计划。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c08b9c-b1af-4e17-92b2-5465fba6be22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93840, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "选出", "is_correct": true, "explanation": "正确：“选出”表示从若干人中挑出第一名，与“比赛后”“评委”的语境相合。"}, {"text": "打败", "is_correct": false, "explanation": "语义：“打败”的对象是对手，评委不能打败第一名，与“评委选出”的意思不合。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”的宾语应是食物，不能说吃掉了第一名。"}, {"text": "参加", "is_correct": false, "explanation": "配价：“参加”的宾语应是活动，不能说参加了第一名。"}], "explanations": {"选出": "正确：“选出”表示从若干人中挑出第一名，与“比赛后”“评委”的语境相合。", "打败": "语义：“打败”的对象是对手，评委不能打败第一名，与“评委选出”的意思不合。", "吃掉": "搭配：“吃掉”的宾语应是食物，不能说吃掉了第一名。", "参加": "配价：“参加”的宾语应是活动，不能说参加了第一名。"}, "sentence_index": 6, "correct_answer": "选出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的沉默选出了同意。", "explanation": "这里应该用〈表示〉。选出是从若干对象中挑出一个，不能用于说明沉默所表达的态度。"}, {"text": "法官选出他无罪，案件就此结束。", "explanation": "这里应该用〈认定〉。认定是作出判断，选出只能用于从若干对象中挑出，不能用于判断是否无罪。"}, {"text": "我选出了辞职去外地工作。", "explanation": "这里应该用〈决定〉。选出是从若干对象中挑出一个，不用于决定自己要做的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c08b9c-b1af-4e17-92b2-5465fba6be22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93840, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "班里要选出了两名值日生。", "corrected_sentence": "班里要选出两名值日生。", "error_description": "错误在“选出了”。“要”表示将来，动作还没发生，“选出”后不能加“了”；正确应为“班里要选出两名值日生”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c08b9c-b1af-4e17-92b2-5465fba6be22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93840, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们从三个方案里选出着一个最好的。", "corrected_sentence": "我们从三个方案里选出了一个最好的。", "error_description": "错误在“选出着”。“着”表示持续的状态，而“选出”是一次完成的动作，应用“了”；正确为“我们从三个方案里选出了一个最好的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c08b9c-b1af-4e17-92b2-5465fba6be22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
