INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93842, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "糖类的旧称或台湾用字，即碳水化合物。", "primary_collocate": null, "pronunciation": "táng", "ipa": "tʰɑŋ˧˥", "syllable_count": 1, "sentences": [{"text": "米饭和面包里有很多醣。", "target_word": "醣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃太多醣，容易变胖。", "target_word": "醣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最近少吃醣，多吃菜。", "target_word": "醣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋糕里的醣很多。", "target_word": "醣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动以后，身体需要一点醣。", "target_word": "醣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种饼干含有很多醣。", "target_word": "醣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "糖尿病人要注意吃进去的醣。", "target_word": "醣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水果里也有醣，但不太多。", "target_word": "醣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说我每天不能吃太多醣。", "target_word": "醣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面条、土豆和米饭都是醣的来源。", "target_word": "醣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "醣类", "label": "复合"}], "register": "书面", "sense_fingerprint": "碳水化合物的台湾用字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f254cf03-f386-45b9-9358-a04ac5249126') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93842, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "醣", "is_correct": true, "explanation": "醣：糖类的旧称，即碳水化合物，读作 táng（第二声）。"}, {"text": "汤", "is_correct": false, "explanation": "tāng（第一声）与 táng（第二声）声调不同，意思是汤。"}, {"text": "躺", "is_correct": false, "explanation": "tǎng（第三声）与 táng（第二声）声调不同，意思是躺下。"}, {"text": "烫", "is_correct": false, "explanation": "tàng（第四声）与 táng（第二声）声调不同，意思是烫手。"}, {"text": "谈", "is_correct": false, "explanation": "tán 与 táng 韵母不同（an/ang），声调相同，意思是谈话。"}, {"text": "同", "is_correct": false, "explanation": "tóng 与 táng 声调相同，韵母不同（ong/ang），意思是相同。"}], "explanations": {"醣": "醣：糖类的旧称，即碳水化合物，读作 táng（第二声）。", "汤": "tāng（第一声）与 táng（第二声）声调不同，意思是汤。", "躺": "tǎng（第三声）与 táng（第二声）声调不同，意思是躺下。", "烫": "tàng（第四声）与 táng（第二声）声调不同，意思是烫手。", "谈": "tán 与 táng 韵母不同（an/ang），声调相同，意思是谈话。", "同": "tóng 与 táng 声调相同，韵母不同（ong/ang），意思是相同。"}, "sentence_index": null, "correct_answer": "醣"}, "level_3": {"options": [{"text": "醣", "is_correct": true, "explanation": "醣：碳水化合物的台湾用字，米饭和面包里都含有它。"}, {"text": "石头", "is_correct": false, "explanation": "语义：米饭和面包是食物，里面不会有很多石头。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油不能吃，面包里不可能有很多汽油。"}, {"text": "硝酸", "is_correct": false, "explanation": "语义：硝酸是化学药品，米饭和面包里不会有很多硝酸。"}], "explanations": {"醣": "醣：碳水化合物的台湾用字，米饭和面包里都含有它。", "石头": "语义：米饭和面包是食物，里面不会有很多石头。", "汽油": "语义：汽油不能吃，面包里不可能有很多汽油。", "硝酸": "语义：硝酸是化学药品，米饭和面包里不会有很多硝酸。"}, "sentence_index": 0, "correct_answer": "醣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "车快没油了，他去加了一些醣。", "explanation": "这里应该用〈汽油〉。醣是糖类的名称，不能用来给车加油，给车加油要说汽油。"}, {"text": "我吃了一只醣。", "explanation": "量词错误：醣是物质，不能用“只”（“只”多用于动物或器物），这里应说“一些醣”。"}, {"text": "他把醣插进了锁孔。", "explanation": "这里应该用〈钥匙〉。醣不能插进锁孔，开锁要用钥匙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e0e01c-984c-44d7-8f29-d4e18d1a7f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93842, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "醣", "is_correct": true, "explanation": "醣：糖类的旧称，即碳水化合物，读作 táng（第二声）。"}, {"text": "长", "is_correct": false, "explanation": "cháng 与 táng 声母不同（ch/t），声调相同，意思是长短的长。"}, {"text": "疼", "is_correct": false, "explanation": "téng 与 táng 韵母不同（eng/ang），声调相同，意思是疼痛。"}, {"text": "汤", "is_correct": false, "explanation": "tāng（第一声）与 táng（第二声）声调不同，意思是汤。"}, {"text": "躺", "is_correct": false, "explanation": "tǎng（第三声）与 táng（第二声）声调不同，意思是躺下。"}], "explanations": {"醣": "醣：糖类的旧称，即碳水化合物，读作 táng（第二声）。", "长": "cháng 与 táng 声母不同（ch/t），声调相同，意思是长短的长。", "疼": "téng 与 táng 韵母不同（eng/ang），声调相同，意思是疼痛。", "汤": "tāng（第一声）与 táng（第二声）声调不同，意思是汤。", "躺": "tǎng（第三声）与 táng（第二声）声调不同，意思是躺下。"}, "sentence_index": null, "correct_answer": "醣"}, "level_3": {"options": [{"text": "醣", "is_correct": true, "explanation": "醣：碳水化合物的台湾用字，糖尿病人需要控制吃进去的量。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃不能吃，“吃玻璃”与句意不符。"}, {"text": "螺丝", "is_correct": false, "explanation": "语义：螺丝是金属零件，不是可以吃的东西。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“吃”一般不跟“空气”搭配，“吃空气”不是正常说法。"}], "explanations": {"醣": "醣：碳水化合物的台湾用字，糖尿病人需要控制吃进去的量。", "玻璃": "语义：玻璃不能吃，“吃玻璃”与句意不符。", "螺丝": "语义：螺丝是金属零件，不是可以吃的东西。", "空气": "搭配：“吃”一般不跟“空气”搭配，“吃空气”不是正常说法。"}, "sentence_index": 6, "correct_answer": "醣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "洗衣服的时候，他先倒了一些醣。", "explanation": "这里应该用〈洗衣粉〉。醣是糖类的名称，不能用来洗衣服，洗衣服要用洗衣粉。"}, {"text": "她出门前先穿上了醣。", "explanation": "这里应该用〈衣服〉。醣不能穿，出门前应说穿上衣服。"}, {"text": "渴了，我就去喝醣。", "explanation": "这里应该用〈水〉。醣是营养成分的名称，不能当饮料喝，渴了要喝水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e0e01c-984c-44d7-8f29-d4e18d1a7f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93842, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈让我少醣吃。", "corrected_sentence": "妈妈让我少吃醣。", "error_description": "宾语位置错误：“醣”是动词“吃”的宾语，应放在动词后，说“少吃醣”，不说“少醣吃”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e0e01c-984c-44d7-8f29-d4e18d1a7f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93842, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我今天吃了很多个醣。", "corrected_sentence": "我今天吃了很多醣。", "error_description": "量词错误：“醣”是物质名词，“很多”后不加个体量词“个”，应说“吃了很多醣”，不说“吃了很多个醣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e0e01c-984c-44d7-8f29-d4e18d1a7f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
