INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93843, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "医药是看病用的药和治病的办法。", "primary_collocate": null, "pronunciation": "yī yào", "ipa": "i˥ jɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "山里的人缺少医药。", "target_word": "医药", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们给灾区送去了医药。", "target_word": "医药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里没有医药，病人很难受。", "target_word": "医药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小岛上医药很缺乏。", "target_word": "医药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医药不够，医生很着急。", "target_word": "医药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他生病后得不到医药，病越来越重。", "target_word": "医药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人靠医药延长了寿命。", "target_word": "医药", "complexity_tier": "T3", "furigana": "lǎo rén kào yī yào yán cháng le shòu mìng", "sentence_source": "generated"}, {"text": "古时候很难买到好的医药。", "target_word": "医药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "部队带着足够的医药出发。", "target_word": "医药", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争期间，前线非常缺乏医药。", "target_word": "医药", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "医药费", "label": "复合"}, {"form": "医药箱", "label": "复合"}, {"form": "醫藥", "label": "繁体"}], "register": "中性", "sense_fingerprint": "看病用的药物和治病的办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6ac4a1-2343-42ab-ba2b-c2fbb8aa55f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93843, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心跳", "is_correct": false, "explanation": "搭配：“缺少”针对可拥有或可供给的东西，不说缺少“心跳”。"}, {"text": "医药", "is_correct": true, "explanation": "正确：医药指看病用的药和治病的办法，是山里人缺少的东西。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”是身体状态，不能作“缺少”的对象。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”是人的自然属性，不能作“缺少”的供给对象。"}], "explanations": {"心跳": "搭配：“缺少”针对可拥有或可供给的东西，不说缺少“心跳”。", "医药": "正确：医药指看病用的药和治病的办法，是山里人缺少的东西。", "体温": "搭配：“体温”是身体状态，不能作“缺少”的对象。", "年龄": "语义：“年龄”是人的自然属性，不能作“缺少”的供给对象。"}, "sentence_index": 0, "correct_answer": "医药"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天用医药做饭。", "explanation": "这里应该用〈锅〉。医药是药物，不能用来做饭，做饭要用“锅”。"}, {"text": "我感冒了，要吃医药。", "explanation": "这里应该用〈药〉。医药是泛称，吃具体的药要说“药”。"}, {"text": "他用医药写信。", "explanation": "这里应该用〈笔〉。医药是药物，不是书写工具，写信要用“笔”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93843, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能延长寿命，与“靠”的语境不符。"}, {"text": "医药", "is_correct": true, "explanation": "正确：医药是看病用的药和治病的办法，老人靠它延长寿命，符合语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能延长寿命，与“靠”的语境不符。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“靠汽车延长寿命”不成立，汽车不能作为延长寿命的依靠。"}], "explanations": {"颜色": "语义：颜色不能延长寿命，与“靠”的语境不符。", "医药": "正确：医药是看病用的药和治病的办法，老人靠它延长寿命，符合语境。", "石头": "语义：石头不能延长寿命，与“靠”的语境不符。", "汽车": "搭配：“靠汽车延长寿命”不成立，汽车不能作为延长寿命的依靠。"}, "sentence_index": 6, "correct_answer": "医药"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "村里的孩子得到了一个医药。", "explanation": "这里不宜用〈个〉。医药是泛称，可说“一些医药”或“一种药”。"}, {"text": "村里的孩子去医药上学。", "explanation": "这里应该用〈学校〉。医药不是场所，不能作“去”的处所。"}, {"text": "村里的孩子看了医药。", "explanation": "这里应该用〈书〉。医药不是读物，“看”的对象要用“书”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93843, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们给灾区送去了一只医药。", "corrected_sentence": "他们给灾区送去了一批医药。", "error_description": "量词误用：“医药”应量作“批”，不能用“只”。应把“只”改为“批”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93843, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村里运来了一只医药。", "corrected_sentence": "村里运来了一些医药。", "error_description": "量词误用：“医药”是泛称，不能用个体量词“只”修饰，应说“一些医药”。应把“一只”改为“一些”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
