INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93844, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "医疗和药物的合称。", "primary_collocate": null, "pronunciation": "yī yào", "ipa": "i˥ jɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司做医药生意。", "target_word": "医药", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医药行业需要很多人才。", "target_word": "医药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在大学学习医药知识。", "target_word": "医药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家加大了对医药的投入。", "target_word": "医药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "近年来医药发展得很快。", "target_word": "医药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山区的医药供应还不充足。", "target_word": "医药", "complexity_tier": "T3", "furigana": "shān qū de yī yào gōng yìng hái bù chōng zú", "sentence_source": "generated"}, {"text": "她想去国外学医药技术。", "target_word": "医药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多医药公司在这个城市。", "target_word": "医药", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医药和教育都是大事。", "target_word": "医药", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我国的医药水平不断提高。", "target_word": "医药", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "医药费", "label": "复合"}, {"form": "医药箱", "label": "复合"}, {"form": "醫藥", "label": "繁体"}], "register": "中性", "sense_fingerprint": "医疗和药物合称，指行业、学科、事业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6ac4a1-2343-42ab-ba2b-c2fbb8aa55f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93844, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "叹息", "is_correct": false, "explanation": "搭配：“叹息”是动作，不能作为买卖的对象，不说“做叹息生意”。"}, {"text": "医药", "is_correct": true, "explanation": "正确：医药指医疗和药物，“医药生意”即医药行业的买卖。"}, {"text": "心跳", "is_correct": false, "explanation": "搭配：“心跳”是生理现象，不能作为买卖的对象，不说“做心跳生意”。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是自然天体，不能用于“做生意”。"}], "explanations": {"叹息": "搭配：“叹息”是动作，不能作为买卖的对象，不说“做叹息生意”。", "医药": "正确：医药指医疗和药物，“医药生意”即医药行业的买卖。", "心跳": "搭配：“心跳”是生理现象，不能作为买卖的对象，不说“做心跳生意”。", "太阳": "语义：太阳是自然天体，不能用于“做生意”。"}, "sentence_index": 0, "correct_answer": "医药"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天吃医药。", "explanation": "这里应该用〈药〉。医药是医疗和药物的合称，吃具体的药要说“药”。"}, {"text": "他正在用医药写作业。", "explanation": "这里应该用〈笔〉。医药是医疗和药物的合称，不是书写工具，写字要用“笔”。"}, {"text": "我买了一瓶医药。", "explanation": "这里应该用〈药〉。医药是合称，不指具体的瓶装物，量“瓶”要用具体的药。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93844, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诗歌", "is_correct": false, "explanation": "语义：诗歌属于文学，不是可以学习的技术。"}, {"text": "医药", "is_correct": true, "explanation": "正确：“医药技术”指医疗和药物方面的技术，符合语境。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：咳嗽是症状，不能作为“学”的技术对象。"}, {"text": "月光", "is_correct": false, "explanation": "语义：“月光”是自然现象，不是可以学习的技术。"}], "explanations": {"诗歌": "语义：诗歌属于文学，不是可以学习的技术。", "医药": "正确：“医药技术”指医疗和药物方面的技术，符合语境。", "咳嗽": "语义：咳嗽是症状，不能作为“学”的技术对象。", "月光": "语义：“月光”是自然现象，不是可以学习的技术。"}, "sentence_index": 6, "correct_answer": "医药"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家医药很大。", "explanation": "这里应该用〈医院〉。医药是泛称，不指建筑或场所。"}, {"text": "他是一位很好的医药。", "explanation": "这里应该用〈护士〉。医药不指人，不能作为身份名词。"}, {"text": "我们一起去医药玩。", "explanation": "这里应该用〈公园〉。医药不是地方，不能作为“去”的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93844, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司的主要业务是个医药。", "corrected_sentence": "这家公司的主要业务是医药。", "error_description": "量词误用：“医药”是集合概念，不能加量词“个”，应去掉“个”，说“是医药”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93844, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个城市有很多家医药。", "corrected_sentence": "这个城市有很多家医药公司。", "error_description": "量词误用：“医药”是行业合称，不能直接用“家”计量；指企业要说“医药公司”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38dff3e8-c56f-4a97-8a5a-56b1205391db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
