INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93845, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "青是像草和天空那样的颜色，有时是蓝，有时是绿。", "primary_collocate": null, "pronunciation": "qīng", "ipa": "tɕʰiŋ˥", "syllable_count": 1, "sentences": [{"text": "春天，山都青了。", "target_word": "青", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "草还青着呢。", "target_word": "青", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后的树特别青。", "target_word": "青", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树叶还是青的，没有变黄。", "target_word": "青", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那块石头是青的。", "target_word": "青", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "河水很青，像一块玉。", "target_word": "青", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夏天的草又青又高。", "target_word": "青", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "山青水绿，空气也好。", "target_word": "青", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个苹果还青着，别吃。", "target_word": "青", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天青得像刚洗过一样。", "target_word": "青", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "青青", "label": "重叠"}, {"form": "青色", "label": "复合"}], "register": "中性", "sense_fingerprint": "青：像草和天空的颜色，蓝或绿，如山青、草青", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c06df7cf-85a1-4808-b16a-c416a651824e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93845, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "青", "is_correct": true, "explanation": "青（qīng）指像草和天空那样的蓝或绿色，是正确答案。"}, {"text": "请", "is_correct": false, "explanation": "请（qǐng）为第三声，与 qīng（第一声）声调不同，意思是“邀请”。"}, {"text": "情", "is_correct": false, "explanation": "情（qíng）为第二声，与 qīng（第一声）声调不同，意思是“感情”。"}, {"text": "亲", "is_correct": false, "explanation": "亲（qīn）韵尾是 in，与 qīng 的 ing 只差一个韵母，意思是“亲近”或“亲人”。"}, {"text": "晴", "is_correct": false, "explanation": "晴（qíng）为第二声，与 qīng（第一声）声调不同，意思是“天气晴朗”。"}], "explanations": {"青": "青（qīng）指像草和天空那样的蓝或绿色，是正确答案。", "请": "请（qǐng）为第三声，与 qīng（第一声）声调不同，意思是“邀请”。", "情": "情（qíng）为第二声，与 qīng（第一声）声调不同，意思是“感情”。", "亲": "亲（qīn）韵尾是 in，与 qīng 的 ing 只差一个韵母，意思是“亲近”或“亲人”。", "晴": "晴（qíng）为第二声，与 qīng（第一声）声调不同，意思是“天气晴朗”。"}, "sentence_index": null, "correct_answer": "青"}, "level_3": {"options": [{"text": "青", "is_correct": true, "explanation": "正确。“山都青了”指山变成青绿色，符合春天的景象。"}, {"text": "黄", "is_correct": false, "explanation": "语义：春天山色为绿，黄色是秋天的颜色，与“春天”矛盾。"}, {"text": "白", "is_correct": false, "explanation": "语义：春天山上不会整体变白，白多指雪景或白色，与春天不符。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不能用来形容山的颜色。"}], "explanations": {"青": "正确。“山都青了”指山变成青绿色，符合春天的景象。", "黄": "语义：春天山色为绿，黄色是秋天的颜色，与“春天”矛盾。", "白": "语义：春天山上不会整体变白，白多指雪景或白色，与春天不符。", "甜": "搭配：“甜”形容味道，不能用来形容山的颜色。"}, "sentence_index": 0, "correct_answer": "青"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他刚参加工作，人还很青。", "explanation": "这里用了“年轻、阅历少”的义项。青在本义项中只指草木、天空那样的蓝或绿色，不能用来形容人，这样用不对。"}, {"text": "熟透的西红柿青得发亮。", "explanation": "这里应该用表示红色的词。熟透的西红柿是红色的；青在本义项中只指草木、天空那样的蓝或绿色，这样用不对。"}, {"text": "秋天了，树叶都青了，变成金黄色。", "explanation": "这里应该用表示变黄的词。秋天树叶变黄，青指蓝、绿色，不指变黄后的颜色，与“金黄色”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df2ab6c9-3636-4fce-84e3-76b71cc52b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93845, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "青", "is_correct": true, "explanation": "正确。“又青又高”描写夏天草的颜色和高度，符合句意。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”形容味道，不能用来形容草的颜色和高度。"}, {"text": "苦", "is_correct": false, "explanation": "语义：“苦”形容味道，与描写草的外观不符。"}, {"text": "烫", "is_correct": false, "explanation": "搭配：“烫”多形容温度或物体的热感，不用来描写草的颜色和高度。"}], "explanations": {"青": "正确。“又青又高”描写夏天草的颜色和高度，符合句意。", "咸": "语义：“咸”形容味道，不能用来形容草的颜色和高度。", "苦": "语义：“苦”形容味道，与描写草的外观不符。", "烫": "搭配：“烫”多形容温度或物体的热感，不用来描写草的颜色和高度。"}, "sentence_index": 6, "correct_answer": "青"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那面红旗在风中飘扬，颜色却青得很鲜艳。", "explanation": "这里应该用表示红色的词。红旗是红色的，青在本义项中只指草木、天空那样的蓝或绿色，不能这样形容。"}, {"text": "这件粉色的毛衣青得很好看。", "explanation": "这里应该用表示粉红色的词。粉红色的毛衣不能用“青”来形容，青在本义项中只指蓝或绿色。"}, {"text": "他听了表扬，羞得脸都青了。", "explanation": "这里应该用表示红色的词。害羞时脸色变红，而青在本义项中只指草木、天空那样的蓝或绿色，不用于形容害羞的脸色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df2ab6c9-3636-4fce-84e3-76b71cc52b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93845, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏天的山青很，看着很舒服。", "corrected_sentence": "夏天的山很青，看着很舒服。", "error_description": "错误在“很”与“青”的顺序。正确形式是“很青”，程度副词“很”应放在形容词前；“青很”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df2ab6c9-3636-4fce-84e3-76b71cc52b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93845, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "远处的山是的青。", "corrected_sentence": "远处的山是青的。", "error_description": "错误在“的”与“青”的位置。正确形式是“青的”，“青”后接“的”构成描写性结构；“的青”结构不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df2ab6c9-3636-4fce-84e3-76b71cc52b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
