INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93846, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "蓝色或绿色，也可指黑色。", "primary_collocate": null, "pronunciation": "qīng", "ipa": "tɕʰiŋ˥", "syllable_count": 1, "sentences": [{"text": "他的脸冷得发青。", "target_word": "青", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他气得脸都青了。", "target_word": "青", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手摔得又青又紫。", "target_word": "青", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "奶奶的布衣是青的，很干净。", "target_word": "青", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人穿一身青，走在雨里。", "target_word": "青", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路边的石板是青的，下雨后很滑。", "target_word": "青", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天黑以前，远山看上去很青。", "target_word": "青", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一晚没睡，眼圈发青。", "target_word": "青", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块布青得发黑。", "target_word": "青", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那片海看上去很青，我心里很平静。", "target_word": "青", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "青青", "label": "重叠"}, {"form": "青色", "label": "复合"}], "register": "中性", "sense_fingerprint": "青：蓝绿或深黑的颜色，如脸色发青、青布", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c06df7cf-85a1-4808-b16a-c416a651824e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93846, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "青", "is_correct": true, "explanation": "青（qīng）指蓝或绿色，是正确答案。"}, {"text": "请", "is_correct": false, "explanation": "请（qǐng）为第三声，与 qīng（第一声）声调不同，意思是“邀请”。"}, {"text": "情", "is_correct": false, "explanation": "情（qíng）为第二声，与 qīng（第一声）声调不同，意思是“感情”。"}, {"text": "亲", "is_correct": false, "explanation": "亲（qīn）韵尾是 in，与 qīng 的 ing 只差一个韵母，意思是“亲近”或“亲人”。"}, {"text": "晴", "is_correct": false, "explanation": "晴（qíng）为第二声，与 qīng（第一声）声调不同，意思是“天气晴朗”。"}], "explanations": {"青": "青（qīng）指蓝或绿色，是正确答案。", "请": "请（qǐng）为第三声，与 qīng（第一声）声调不同，意思是“邀请”。", "情": "情（qíng）为第二声，与 qīng（第一声）声调不同，意思是“感情”。", "亲": "亲（qīn）韵尾是 in，与 qīng 的 ing 只差一个韵母，意思是“亲近”或“亲人”。", "晴": "晴（qíng）为第二声，与 qīng（第一声）声调不同，意思是“天气晴朗”。"}, "sentence_index": null, "correct_answer": "青"}, "level_3": {"options": [{"text": "青", "is_correct": true, "explanation": "正确。“发青”指因冷而脸色发青，符合句意。"}, {"text": "烫", "is_correct": false, "explanation": "语义：脸因“冷”不会发烫，与前面的“冷”矛盾。"}, {"text": "亮", "is_correct": false, "explanation": "搭配：“发亮”指发光，脸冷时不会发亮，搭配不当。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”形容味道，不能用来形容脸色。"}], "explanations": {"青": "正确。“发青”指因冷而脸色发青，符合句意。", "烫": "语义：脸因“冷”不会发烫，与前面的“冷”矛盾。", "亮": "搭配：“发亮”指发光，脸冷时不会发亮，搭配不当。", "甜": "语义：“甜”形容味道，不能用来形容脸色。"}, "sentence_index": 0, "correct_answer": "青"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小伙子很青，才刚毕业。", "explanation": "这里用了“年轻、阅历少”的义项。青在本义项中只表示蓝、绿或黑色，这样用不对。"}, {"text": "这件粉色的连衣裙青得很好看。", "explanation": "这里应该用表示粉红色的词。粉红色的连衣裙不能用“青”来形容颜色，青指蓝、绿或黑色。"}, {"text": "他害羞得脸都青了。", "explanation": "这里应该用表示红色的词。害羞时脸色变红，青指蓝、绿或黑色，不能用来形容害羞的脸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df2ab6c9-3636-4fce-84e3-76b71cc52b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93846, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "青", "is_correct": true, "explanation": "正确。“很青”在这里指远山呈现青色，符合句意。"}, {"text": "辣", "is_correct": false, "explanation": "语义：“辣”形容味道，不能用来形容远山的样子。"}, {"text": "酸", "is_correct": false, "explanation": "语义：“酸”形容味道，远山看上去不会是酸的。"}, {"text": "软", "is_correct": false, "explanation": "搭配：“软”多用于物体的质地，不说远山看上去很软。"}], "explanations": {"青": "正确。“很青”在这里指远山呈现青色，符合句意。", "辣": "语义：“辣”形容味道，不能用来形容远山的样子。", "酸": "语义：“酸”形容味道，远山看上去不会是酸的。", "软": "搭配：“软”多用于物体的质地，不说远山看上去很软。"}, "sentence_index": 6, "correct_answer": "青"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一夜白头，头发全青了。", "explanation": "这里应该用表示白色的词。一夜白头说的是头发变白，青指蓝、绿或黑色，不能用来形容白发。"}, {"text": "秋风一吹，满树的叶子都青得像金子一样。", "explanation": "这里应该用表示黄色的词。秋天的叶子变黄，青指蓝、绿或黑色，不能用来形容金子一样的颜色。"}, {"text": "五星红旗迎风飘扬，旗面青得很鲜艳。", "explanation": "这里应该用表示红色的词。国旗是红色的，青指蓝、绿或黑色，不能这样形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df2ab6c9-3636-4fce-84e3-76b71cc52b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93846, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的手冻得青发。", "corrected_sentence": "他的手冻得发青。", "error_description": "错误在“青”与“发”的顺序。正确形式是“发青”，“发”是动词，“青”作结果补语；“青发”不能成词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df2ab6c9-3636-4fce-84e3-76b71cc52b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93846, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条旧裤子青青得发黑。", "corrected_sentence": "这条旧裤子青得发黑。", "error_description": "错误在“青”的形式。正确形式是“青得”，“青”作形容词加补语；“青青”是重叠形式，不能再接“得”引出补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df2ab6c9-3636-4fce-84e3-76b71cc52b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
