INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93849, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "饮食是我们吃的和喝的东西。", "primary_collocate": null, "pronunciation": "yǐn shí", "ipa": "in˨˩˦ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "医生说，病人的饮食要清淡一点。", "target_word": "饮食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山区的饮食很简单，主要是米饭和蔬菜。", "target_word": "饮食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家酒店的饮食有中餐也有西餐。", "target_word": "饮食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行时要注意饮食，别吃太凉的东西。", "target_word": "饮食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的饮食要少油少盐。", "target_word": "饮食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子需要健康的饮食才能长高。", "target_word": "饮食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的饮食很辣，我吃不惯。", "target_word": "饮食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员的饮食里要有很多肉和蛋。", "target_word": "饮食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在学校，学生的饮食由食堂负责。", "target_word": "饮食", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院给病人准备了特别的饮食。", "target_word": "饮食", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "飲食", "label": "繁体"}, {"form": "饮食结构", "label": "复合"}], "register": "中性", "sense_fingerprint": "人们吃的和喝的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d8f91e-1c52-478c-8897-5222c5cd20d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93849, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "饮食", "is_correct": true, "explanation": "饮食：吃的和喝的东西。"}, {"text": "殷实", "is_correct": false, "explanation": "yīn（第一声）与 yǐn（第三声）声调不同，殷实是家境富裕的意思。"}, {"text": "隐私", "is_correct": false, "explanation": "声母 s 与 sh 不同，声调也不同（sī 第一声，shí 第二声）；隐私指不愿公开的个人事情。"}, {"text": "隐士", "is_correct": false, "explanation": "yǐn 相同，shì（第四声）与 shí（第二声）声调不同；隐士是隐居的人。"}], "explanations": {"饮食": "饮食：吃的和喝的东西。", "殷实": "yīn（第一声）与 yǐn（第三声）声调不同，殷实是家境富裕的意思。", "隐私": "声母 s 与 sh 不同，声调也不同（sī 第一声，shí 第二声）；隐私指不愿公开的个人事情。", "隐士": "yǐn 相同，shì（第四声）与 shí（第二声）声调不同；隐士是隐居的人。"}, "sentence_index": null, "correct_answer": "饮食"}, "level_3": {"options": [{"text": "饮食", "is_correct": true, "explanation": "饮食指吃的和喝的东西，与“病人的……要清淡一点”相符。"}, {"text": "药品", "is_correct": false, "explanation": "语义：药品是药，不是吃的喝的东西，不能说“清淡”。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“清淡”形容食物的口味，不能用来形容体温。"}, {"text": "作息", "is_correct": false, "explanation": "搭配：“清淡”不用于作息，作息只说规律、紊乱等。"}], "explanations": {"饮食": "饮食指吃的和喝的东西，与“病人的……要清淡一点”相符。", "药品": "语义：药品是药，不是吃的喝的东西，不能说“清淡”。", "体温": "搭配：“清淡”形容食物的口味，不能用来形容体温。", "作息": "搭配：“清淡”不用于作息，作息只说规律、紊乱等。"}, "sentence_index": 0, "correct_answer": "饮食"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天太热了，我想喝一下饮食。", "explanation": "这里应该用〈饮料〉。饮食泛指吃的和喝的东西，不能直接说“喝饮食”；要喝东西，应说“喝饮料”。"}, {"text": "我们去饮食吃晚饭吧。", "explanation": "这里应该用〈饭馆〉。饮食是东西，不是地方，不能说“去饮食”。"}, {"text": "我今天只吃了一粒饮食。", "explanation": "这里不能用〈粒〉。饮食是泛指的概念，不用“粒”来计量；吃一顿饭应该用“顿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93849, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饮食", "is_correct": true, "explanation": "饮食指吃的和喝的东西，“很辣，我吃不惯”说的正是吃的东西。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“辣”形容味道，天气不能说“很辣”。"}, {"text": "城市", "is_correct": false, "explanation": "语义：城市不是吃的东西，不能说“很辣”，句子也与“我吃不惯”无关。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐不是吃的喝的东西，不能形容成“很辣”，与“吃不惯”不符。"}], "explanations": {"饮食": "饮食指吃的和喝的东西，“很辣，我吃不惯”说的正是吃的东西。", "天气": "搭配：“辣”形容味道，天气不能说“很辣”。", "城市": "语义：城市不是吃的东西，不能说“很辣”，句子也与“我吃不惯”无关。", "音乐": "语义：音乐不是吃的喝的东西，不能形容成“很辣”，与“吃不惯”不符。"}, "sentence_index": 6, "correct_answer": "饮食"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上用饮食刷牙。", "explanation": "这里应该用〈牙刷〉。饮食是吃的和喝的东西，不能用来刷牙，刷牙要用“牙刷”。"}, {"text": "他很累，就躺在饮食上睡觉。", "explanation": "这里应该用〈床〉。饮食是吃的和喝的东西，不能躺在上面，睡觉要用“床”。"}, {"text": "他洗好了饮食，放回柜子里。", "explanation": "这里应该用〈餐具〉。饮食是吃的和喝的东西，不能用来洗，要洗的是餐具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93849, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他为了健康，选择了一只清淡的饮食。", "corrected_sentence": "他为了健康，选择了一种清淡的饮食。", "error_description": "“饮食”前应该用量词“种”，不能用“只”。“只”一般用于动物或成对、成只的东西，不能用来数饮食。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93849, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很注意饮食们，每天都吃得很健康。", "corrected_sentence": "他很注意饮食，每天都吃得很健康。", "error_description": "“饮食”是泛指吃喝东西的集合名词，不能加复数后缀“们”。正确说法是“很注意饮食”，去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
