INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93851, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "高等是比一般的更高一级。", "primary_collocate": null, "pronunciation": "gāo děng", "ipa": "kɑʊ˥ tɤŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他想在高等学校学习医学。", "target_word": "高等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所高等学校有一百年的历史了。", "target_word": "高等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐正在接受高等教育。", "target_word": "高等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在上高等学校的人越来越多。", "target_word": "高等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高等教育对年轻人很重要。", "target_word": "高等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市有五所高等学校。", "target_word": "高等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他毕业于一所有名的高等学校。", "target_word": "高等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸希望我能接受高等教育。", "target_word": "高等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高等学校的老师大多有博士学位。", "target_word": "高等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在高等学校教了二十年书。", "target_word": "高等", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "高等：比一般的更高一级，如高等学校、高等教育", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21d5d4e3-cb6a-4e49-9798-364dbe498c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93851, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高等", "is_correct": true, "explanation": "高等：比一般更高一级，与“学习医学”的学校层次相符。"}, {"text": "低等", "is_correct": false, "explanation": "语义：“低等”指较低一级，与“学习医学”的高层次学习相抵触，不能指学校。"}, {"text": "陡峭", "is_correct": false, "explanation": "搭配：“陡峭”形容山坡等地势，不能修饰学校。"}, {"text": "透明", "is_correct": false, "explanation": "语义：“透明”形容物体能透光，与学校的层次无关，句子说不通。"}], "explanations": {"高等": "高等：比一般更高一级，与“学习医学”的学校层次相符。", "低等": "语义：“低等”指较低一级，与“学习医学”的高层次学习相抵触，不能指学校。", "陡峭": "搭配：“陡峭”形容山坡等地势，不能修饰学校。", "透明": "语义：“透明”形容物体能透光，与学校的层次无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "高等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭店的装修很高等。", "explanation": "这里应该用〈高级〉，形容档次和质量；高等表示比一般更高一级的学校或教育，不用于形容装修。"}, {"text": "他的解题方法很高等。", "explanation": "这里应该用〈高明〉，形容见解或办法出色；高等表示层次更高，不用于形容方法。"}, {"text": "这件商品的价格很高等。", "explanation": "这里应该用〈高昂〉，形容价格高；高等表示比一般更高一级的学校或教育，不用于形容价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
