INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93852, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "等级、程度较高的。", "primary_collocate": null, "pronunciation": "gāo děng", "ipa": "kɑʊ˥ tɤŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "猴子是比较高等的动物。", "target_word": "高等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人是最高等的动物。", "target_word": "高等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高等动物有复杂的神经系统。", "target_word": "高等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高等植物大多有根、茎和叶。", "target_word": "高等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们大学一年级要学高等数学。", "target_word": "高等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高等数学比中学数学难多了。", "target_word": "高等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他认为人类是比其他动物更高等的物种。", "target_word": "高等", "complexity_tier": "T3", "furigana": "tā rèn wéi rén lèi shì bǐ qí tā dòng wù gèng gāo děng de wù zhǒng", "sentence_source": "generated"}, {"text": "高等动物的大脑很发达。", "target_word": "高等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，高等生物的身体结构更复杂。", "target_word": "高等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪些动物算高等动物呢？", "target_word": "高等", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "高等：等级、程度较高的，如高等动物、高等数学", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21d5d4e3-cb6a-4e49-9798-364dbe498c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93852, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高等", "is_correct": true, "explanation": "高等：等级较高，修饰“动物”指进化程度较高的动物。"}, {"text": "透明", "is_correct": false, "explanation": "语义：“透明”形容物体能透光，不能用来说动物的等级，句子说不通。"}, {"text": "陡峭", "is_correct": false, "explanation": "搭配：“陡峭”形容地势，不能修饰动物。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”形容味道，不能用来形容动物的等级。"}], "explanations": {"高等": "高等：等级较高，修饰“动物”指进化程度较高的动物。", "透明": "语义：“透明”形容物体能透光，不能用来说动物的等级，句子说不通。", "陡峭": "搭配：“陡峭”形容地势，不能修饰动物。", "咸": "语义：“咸”形容味道，不能用来形容动物的等级。"}, "sentence_index": 0, "correct_answer": "高等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的品德很高等。", "explanation": "这里应该用〈高尚〉，形容品德、人格；高等表示等级较高（如动植物），不用于形容品德。"}, {"text": "这门学问很高等，我学不会。", "explanation": "这里应该用〈高深〉，形容学问精深；高等指等级较高，不用来形容学问的深浅。"}, {"text": "他的绘画技艺很高等。", "explanation": "这里应该用〈高超〉，形容技艺达到很高的水平；高等表示等级较高（如动物、植物），不用于形容技艺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93852, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高等", "is_correct": true, "explanation": "高等：等级较高，修饰“物种”指进化程度较高的物种，与“比其他动物更”相呼应。"}, {"text": "方形", "is_correct": false, "explanation": "语义：“方形”形容形状，不能用来比较物种的等级。"}, {"text": "粗糙", "is_correct": false, "explanation": "搭配：“粗糙”形容表面质地，不用来形容物种。"}, {"text": "碎", "is_correct": false, "explanation": "语义：“碎”指破成块，与物种的等级无关，句子说不通。"}], "explanations": {"高等": "高等：等级较高，修饰“物种”指进化程度较高的物种，与“比其他动物更”相呼应。", "方形": "语义：“方形”形容形状，不能用来比较物种的等级。", "粗糙": "搭配：“粗糙”形容表面质地，不用来形容物种。", "碎": "语义：“碎”指破成块，与物种的等级无关，句子说不通。"}, "sentence_index": 6, "correct_answer": "高等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家商店的衣服很高等。", "explanation": "这里应该用〈高档〉，形容商品的质量和档次；高等指等级较高（如动植物），不用来形容商品。"}, {"text": "他的解题思路很高等。", "explanation": "这里应该用〈高明〉，形容见解或办法出色；高等指等级较高，不用于形容思路。"}, {"text": "这款手机是高等产品。", "explanation": "这里应该用〈高端〉，形容档次很高；高等指等级较高（如动植物），不用于形容产品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93852, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只老虎是比较高等得动物。", "corrected_sentence": "这只老虎是比较高等的动物。", "error_description": "错误形式：“比较高等得动物”，修饰名词时应用“的”，“得”用于补语。正确形式为“比较高等的动物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
