INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93853, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一道是和别人一起，在同一时间去做同一件事。", "primary_collocate": null, "pronunciation": "yí dào", "ipa": "i˧˥ tɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "明天早上，我和小王一道去机场。", "target_word": "一道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下班后我们一道回家。", "target_word": "一道", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们几个人一道走进了教室。", "target_word": "一道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师和学生一道打扫教室。", "target_word": "一道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我和同学一道去图书馆看书。", "target_word": "一道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末你有空的话，我们一道去爬山吧。", "target_word": "一道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们一道唱起歌来。", "target_word": "一道", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他和妹妹一道坐火车去上海。", "target_word": "一道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们三个人一道吃了晚饭。", "target_word": "一道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天我和朋友一道看了一场电影。", "target_word": "一道", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词：和别人一起，在同一时间做同一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c06df7cf-85a1-4808-b16a-c416a651824e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93853, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一道", "is_correct": true, "explanation": "正确。“一道”表示和别人一起，符合“我和小王”一起去的句意。"}, {"text": "独自", "is_correct": false, "explanation": "语义：“独自”指一个人去，与“我和小王”矛盾。"}, {"text": "非常", "is_correct": false, "explanation": "语法：“非常”是程度副词，不能直接修饰“去机场”这样的动作。"}, {"text": "偏偏", "is_correct": false, "explanation": "搭配：“偏偏”表示故意或出乎意料，不与“和……去”这类共同行动搭配。"}], "explanations": {"一道": "正确。“一道”表示和别人一起，符合“我和小王”一起去的句意。", "独自": "语义：“独自”指一个人去，与“我和小王”矛盾。", "非常": "语法：“非常”是程度副词，不能直接修饰“去机场”这样的动作。", "偏偏": "搭配：“偏偏”表示故意或出乎意料，不与“和……去”这类共同行动搭配。"}, "sentence_index": 0, "correct_answer": "一道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一个人一道走进了教室。", "explanation": "这里把“一道”用成了“单独、独自”的意思，但“一道”指和别人共同行动。"}, {"text": "我一道吃了晚饭，桌上只有我一个人。", "explanation": "这里把“一道”用成了“单独、独自”的意思，但“一道”需要与别人一起行动。"}, {"text": "他单独一道去图书馆。", "explanation": "这里把“一道”用成了“独自”的意思，但“一道”表示和别人共同行动，与独自做事不相容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df2ab6c9-3636-4fce-84e3-76b71cc52b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93853, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一道", "is_correct": true, "explanation": "正确。“一道唱起歌来”表示孩子们一起唱歌，符合句意。"}, {"text": "白白", "is_correct": false, "explanation": "语义：“白白”表示徒劳或浪费，与“唱起歌来”的描写不符。"}, {"text": "亲自", "is_correct": false, "explanation": "语义：“亲自”强调本人亲身去做，与“孩子们”的集体行为不符。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是程度副词，不能直接修饰“唱起歌来”这样的动作。"}], "explanations": {"一道": "正确。“一道唱起歌来”表示孩子们一起唱歌，符合句意。", "白白": "语义：“白白”表示徒劳或浪费，与“唱起歌来”的描写不符。", "亲自": "语义：“亲自”强调本人亲身去做，与“孩子们”的集体行为不符。", "很": "语法：“很”是程度副词，不能直接修饰“唱起歌来”这样的动作。"}, "sentence_index": 6, "correct_answer": "一道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们一道先后到达了车站。", "explanation": "这里把“一道”用成了“不同时间”的意思，但“一道”指在同一时间共同行动，不能表示先后。"}, {"text": "两个人一道分开走了，互不相干。", "explanation": "这里把“一道”用成了“各自分开”的意思，但“一道”指和别人共同行动。"}, {"text": "他们一道在不同的房间里做作业。", "explanation": "这里把“一道”用成了“分开、各在一处”的意思，但“一道”指和别人共同行动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df2ab6c9-3636-4fce-84e3-76b71cc52b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93853, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末我们一道了去公园散步。", "corrected_sentence": "周末我们一道去公园散步。", "error_description": "“一道”是副词，不能带“了”，应紧接动词，说“一道去公园散步”；“一道了去”多加了“了”，句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df2ab6c9-3636-4fce-84e3-76b71cc52b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93853, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈和我一道的包饺子。", "corrected_sentence": "妈妈和我一道包饺子。", "error_description": "“一道”是副词，只能修饰动词，后面不能加“的”，应说“一道包饺子”；“一道的包饺子”把副词当作定语，错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df2ab6c9-3636-4fce-84e3-76b71cc52b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
