INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93857, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "（上级或有权力的人）发布命令，要求别人去做某事。", "primary_collocate": null, "pronunciation": "xià lìng", "ipa": "ɕja˥˩ liŋ˥˩", "syllable_count": 2, "sentences": [{"text": "总统下令军队马上出发。", "target_word": "下令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝下令全国的人交税。", "target_word": "下令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司令下令大家不能说话。", "target_word": "下令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王下令关上城门。", "target_word": "下令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长下令全队原地休息。", "target_word": "下令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部长下令检查每一家工厂。", "target_word": "下令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首相下令明天开会。", "target_word": "下令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老将军下令开门让客人进来。", "target_word": "下令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "县长下令今晚停电。", "target_word": "下令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总经理下令所有人七点到公司。", "target_word": "下令", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "下了令", "label": "体标"}], "register": "书面", "sense_fingerprint": "发布命令；下令＋人＋做某事（下令出发、下令撤退）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f254cf03-f386-45b9-9358-a04ac5249126') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93857, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下令", "is_correct": true, "explanation": "下令：发布命令，此处指总统命令军队出发。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”不能带“军队马上出发”这样的小句作宾语，句子不通。"}, {"text": "原谅", "is_correct": false, "explanation": "语义：“原谅”的对象是过错，不能用来指派军队行动。"}, {"text": "游玩", "is_correct": false, "explanation": "配价：“游玩”是不及物动词，不能带小句作宾语。"}], "explanations": {"下令": "下令：发布命令，此处指总统命令军队出发。", "唱": "配价：“唱”不能带“军队马上出发”这样的小句作宾语，句子不通。", "原谅": "语义：“原谅”的对象是过错，不能用来指派军队行动。", "游玩": "配价：“游玩”是不及物动词，不能带小句作宾语。"}, "sentence_index": 0, "correct_answer": "下令"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他下令一张海报。", "explanation": "这里应该用〈张贴〉。下令是发出命令，不能带“海报”作宾语，应说“张贴海报”。"}, {"text": "我下令你原谅我。", "explanation": "这里应该用〈请求〉。下令是上对下的强制命令，向别人恳求原谅要用“请求”。"}, {"text": "这块石头下令滚下山了。", "explanation": "这里应该用〈滚落〉。下令的主语须是有权发出命令的人，石头不能下令，只能滚落。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e0e01c-984c-44d7-8f29-d4e18d1a7f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93857, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下令", "is_correct": true, "explanation": "下令：发布命令，此处指首相发出的开会命令。"}, {"text": "游泳", "is_correct": false, "explanation": "配价：“游泳”是不及物动词，不能带“明天开会”作宾语。"}, {"text": "怀念", "is_correct": false, "explanation": "语义：“怀念”表示对过去的感情，与“明天开会”这一安排不符。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”的对象应是场所或物品，“打扫明天开会”说不通。"}], "explanations": {"下令": "下令：发布命令，此处指首相发出的开会命令。", "游泳": "配价：“游泳”是不及物动词，不能带“明天开会”作宾语。", "怀念": "语义：“怀念”表示对过去的感情，与“明天开会”这一安排不符。", "打扫": "语义：“打扫”的对象应是场所或物品，“打扫明天开会”说不通。"}, "sentence_index": 6, "correct_answer": "下令"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学们下令大家一起去看电影。", "explanation": "这里应该用〈提议〉。下令带有上级对下级的强制意味，同学之间商量去看电影应说“提议”。"}, {"text": "我下令了一本书给妹妹。", "explanation": "这里应该用〈送〉。下令是发布命令，不能表示把东西给人，应说“送了一本书给妹妹”。"}, {"text": "我下令明天下雨。", "explanation": "这里应该用〈预报〉。下令的内容须是人能去执行的事，天气不能由人命令，只能预报。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e0e01c-984c-44d7-8f29-d4e18d1a7f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93857, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "国王下令着，让大臣回家。", "corrected_sentence": "国王下了令，让大臣回家。", "error_description": "体标错误：“着”表示持续状态，不能接在“下令”后；命令是一次性发出的，应说“下了令”，不说“下令着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e0e01c-984c-44d7-8f29-d4e18d1a7f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93857, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板下令着大家明天七点到厂里。", "corrected_sentence": "老板下令大家明天七点到厂里。", "error_description": "体标错误：“着”表示持续状态，不能接在“下令”后；命令是一次性发出的，应直接说“老板下令大家……”，不说“下令着大家……”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21e0e01c-984c-44d7-8f29-d4e18d1a7f53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
