INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93859, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "不准是不可以，不让做。", "primary_collocate": null, "pronunciation": "bù zhǔn", "ipa": "pu⁵¹ tʂuən²¹⁴", "syllable_count": 2, "sentences": [{"text": "这里不准抽烟。", "target_word": "不准", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这座桥太旧，汽车不准上去。", "target_word": "不准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上十点以后不准大声说话。", "target_word": "不准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "游泳池里不准跑。", "target_word": "不准", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "开车的时候不准看手机。", "target_word": "不准", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个门口不准停车。", "target_word": "不准", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "考试的时候，不准看别人的卷子。", "target_word": "不准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩子不准一个人过马路。", "target_word": "不准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上课不准玩手机，听到了没有？", "target_word": "不准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园里的花不准随便摘，请大家注意。", "target_word": "不准", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "后接动词，表示规定或场合上不可以做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f5f24a-08cb-4f02-a962-6cffc7a480b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93859, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不准", "is_correct": true, "explanation": "“不准”表示规定或场合上不可以做某事，与“这里”加“抽烟”的语境吻合。"}, {"text": "必须", "is_correct": false, "explanation": "语义：“必须”表示一定要做，与“这里不准抽烟”的禁止意思相反。"}, {"text": "愿意", "is_correct": false, "explanation": "搭配：“愿意”多用于人，表示自己的意愿，不说“这里愿意抽烟”。"}, {"text": "应该", "is_correct": false, "explanation": "语义：“应该”表示道理上应当如此，与“这里”的禁烟规定相悖；“这里应该抽烟”语法上可以说，但意思与禁止正相反。"}], "explanations": {"不准": "“不准”表示规定或场合上不可以做某事，与“这里”加“抽烟”的语境吻合。", "必须": "语义：“必须”表示一定要做，与“这里不准抽烟”的禁止意思相反。", "愿意": "搭配：“愿意”多用于人，表示自己的意愿，不说“这里愿意抽烟”。", "应该": "语义：“应该”表示道理上应当如此，与“这里”的禁烟规定相悖；“这里应该抽烟”语法上可以说，但意思与禁止正相反。"}, "sentence_index": 0, "correct_answer": "不准"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天有事，不准参加比赛。", "explanation": "这里应该用〈不能〉。“不准”表示禁止或规定不允许，因为有事去不了要用“不能”。"}, {"text": "这个字太小了，我不准看清楚。", "explanation": "这里应该用〈看不清楚〉。“不准”表示规定上不允许，字太小看不清是能力问题，要说“看不清楚”。"}, {"text": "我的手机没电了，不准打电话。", "explanation": "这里应该用〈不能〉。“不准”表示禁止，手机没电是客观原因，要用“不能”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '255f5084-988b-4ed0-82f9-f3beca3e3c8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93859, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不准", "is_correct": true, "explanation": "“不准”表示不允许，符合“考试的时候”禁止看别人卷子的语境。"}, {"text": "可以", "is_correct": false, "explanation": "语义：“可以”表示允许，与考试时禁止作弊的常理相反。"}, {"text": "得", "is_correct": false, "explanation": "搭配：“得”表示必要，“考试的时候得看别人的卷子”不合常理，也不能表示禁止。"}, {"text": "要", "is_correct": false, "explanation": "语义：“要”表示想要或将要，句中表示禁止时用“要”意思不对。"}], "explanations": {"不准": "“不准”表示不允许，符合“考试的时候”禁止看别人卷子的语境。", "可以": "语义：“可以”表示允许，与考试时禁止作弊的常理相反。", "得": "搭配：“得”表示必要，“考试的时候得看别人的卷子”不合常理，也不能表示禁止。", "要": "语义：“要”表示想要或将要，句中表示禁止时用“要”意思不对。"}, "sentence_index": 6, "correct_answer": "不准"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道题太难，我不准做出来。", "explanation": "这里应该用〈做不出来〉。“不准”表示禁止，题太难做不出是能力问题，要说“做不出来”。"}, {"text": "我的鞋子坏了，不准出门了。", "explanation": "这里应该用〈不能〉。“不准”表示禁止，鞋子坏了是客观原因，要用“不能”。"}, {"text": "这件衣服太小，不准穿了。", "explanation": "这里应该用〈穿不了〉。“不准”表示禁止，衣服太小是客观条件，要用“穿不了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '255f5084-988b-4ed0-82f9-f3beca3e3c8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93859, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "图书馆里不准过大声说话。", "corrected_sentence": "图书馆里不准大声说话。", "error_description": "错误：“不准”后面多加了“过”。正确：“不准”是情态动词，不能带体标“过”，应说“不准大声说话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '255f5084-988b-4ed0-82f9-f3beca3e3c8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93859, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电梯里不准了吸烟。", "corrected_sentence": "电梯里不准吸烟。", "error_description": "错误：“不准”后面多加了“了”。正确：“不准”是情态动词，本身不带“了”，应说“不准吸烟”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '255f5084-988b-4ed0-82f9-f3beca3e3c8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93860, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "准许", "is_correct": true, "explanation": "“准许”与“不准”是反义词，都指对某事是否允许。"}, {"text": "打扫", "is_correct": false, "explanation": "与“不准”没有反义关系，“打扫”指清理卫生的动作。"}, {"text": "散步", "is_correct": false, "explanation": "与“不准”没有反义关系，“散步”指慢慢走路的活动。"}, {"text": "学习", "is_correct": false, "explanation": "与“不准”没有反义关系，“学习”指获得知识或技能。"}], "correct_answer": "准许", "explanations": {"准许": "“准许”与“不准”是反义词，都指对某事是否允许。", "打扫": "与“不准”没有反义关系，“打扫”指清理卫生的动作。", "散步": "与“不准”没有反义关系，“散步”指慢慢走路的活动。", "学习": "与“不准”没有反义关系，“学习”指获得知识或技能。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '255f5084-988b-4ed0-82f9-f3beca3e3c8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93860, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "准许", "is_correct": true, "explanation": "“准许”与“不准”是反义词，都指对某事是否允许。"}, {"text": "写字", "is_correct": false, "explanation": "与“不准”没有反义关系，“写字”指用笔写出文字。"}, {"text": "吃饭", "is_correct": false, "explanation": "与“不准”没有反义关系，“吃饭”指进食的动作。"}, {"text": "游泳", "is_correct": false, "explanation": "与“不准”没有反义关系，“游泳”指在水中活动的运动。"}], "correct_answer": "准许", "explanations": {"准许": "“准许”与“不准”是反义词，都指对某事是否允许。", "写字": "与“不准”没有反义关系，“写字”指用笔写出文字。", "吃饭": "与“不准”没有反义关系，“吃饭”指进食的动作。", "游泳": "与“不准”没有反义关系，“游泳”指在水中活动的运动。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '255f5084-988b-4ed0-82f9-f3beca3e3c8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93860, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不允许；禁止。", "primary_collocate": null, "pronunciation": "bù zhǔn", "ipa": "pu⁵¹ tʂuən²¹⁴", "syllable_count": 2, "sentences": [{"text": "妈妈不准我玩手机。", "target_word": "不准", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸不准弟弟吃太多糖。", "target_word": "不准", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师不准我们在教室里吃东西。", "target_word": "不准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生不准他喝酒。", "target_word": "不准", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他父母不准他一个人出国。", "target_word": "不准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司不准员工上班时玩游戏。", "target_word": "不准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外面下大雨，奶奶不准孙子出门。", "target_word": "不准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐姐不准我进她的房间。", "target_word": "不准", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老板不准大家提前下班。", "target_word": "不准", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小时候，爷爷不准我晚上看电视。", "target_word": "不准", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "后接某人再接动作，表示某人不允许另一人做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3f5f24a-08cb-4f02-a962-6cffc7a480b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93860, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不准", "is_correct": true, "explanation": "“不准”表示不允许某人做某事，符合家长管束孩子的语境。"}, {"text": "苹果", "is_correct": false, "explanation": "词性：“苹果”是水果名，不能带“我玩手机”，“妈妈苹果我玩手机”不通。"}, {"text": "罚", "is_correct": false, "explanation": "语义：“罚”是惩罚的意思，“罚我玩手机”不通，与禁止的意思不符。"}, {"text": "厨房", "is_correct": false, "explanation": "词性：“厨房”是名词，指做饭的地方，不能带“我玩手机”，“妈妈厨房我玩手机”不通。"}], "explanations": {"不准": "“不准”表示不允许某人做某事，符合家长管束孩子的语境。", "苹果": "词性：“苹果”是水果名，不能带“我玩手机”，“妈妈苹果我玩手机”不通。", "罚": "语义：“罚”是惩罚的意思，“罚我玩手机”不通，与禁止的意思不符。", "厨房": "词性：“厨房”是名词，指做饭的地方，不能带“我玩手机”，“妈妈厨房我玩手机”不通。"}, "sentence_index": 0, "correct_answer": "不准"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一点儿也不渴，所以自己不准喝水。", "explanation": "这里应该用〈不想〉。“不准”表示别人禁止，此处是他自己不渴、不愿意喝，要用“不想”。"}, {"text": "我的手机没电了，不准打电话。", "explanation": "这里应该用〈不能〉。“不准”表示禁止，手机没电是客观原因，要用“不能”。"}, {"text": "妈妈不准我的画。", "explanation": "这里应该用〈不喜欢〉。“不准”要接“某人加动作”的禁止对象，不能直接接“画”这样的事物；对事物表示否定要用“不喜欢”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '255f5084-988b-4ed0-82f9-f3beca3e3c8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93860, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不准", "is_correct": true, "explanation": "“不准”表示不允许，符合下大雨时奶奶禁止孙子出门的语境。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”表示对别人的好意表示谢意，“感谢孙子出门”不通。"}, {"text": "请", "is_correct": false, "explanation": "语义：“请”表示邀请对方做某事，与“外面下大雨”的语境相反。"}, {"text": "夸", "is_correct": false, "explanation": "搭配：“夸”后接的是对人或事的赞美，不能直接带“出门”表示禁止。"}], "explanations": {"不准": "“不准”表示不允许，符合下大雨时奶奶禁止孙子出门的语境。", "感谢": "语义：“感谢”表示对别人的好意表示谢意，“感谢孙子出门”不通。", "请": "语义：“请”表示邀请对方做某事，与“外面下大雨”的语境相反。", "夸": "搭配：“夸”后接的是对人或事的赞美，不能直接带“出门”表示禁止。"}, "sentence_index": 6, "correct_answer": "不准"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我没有钱，不准买这件衣服。", "explanation": "这里应该用〈买不起〉。“不准”表示禁止，没钱是客观原因，要用“买不起”。"}, {"text": "我的车坏了，不准开了。", "explanation": "这里应该用〈不能〉。“不准”表示禁止，车坏了是客观原因，要用“不能”。"}, {"text": "这双鞋太小，不准穿了。", "explanation": "这里应该用〈穿不了〉。“不准”表示禁止，鞋子太小是客观条件，要用“穿不了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '255f5084-988b-4ed0-82f9-f3beca3e3c8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
