INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93860, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师不准了我们迟到。", "corrected_sentence": "老师不准我们迟到。", "error_description": "错误：“不准”后面多加了“了”。正确：“不准”不带“了”，应说“不准我们迟到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '255f5084-988b-4ed0-82f9-f3beca3e3c8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
