INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93862, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "世间；世界上。", "primary_collocate": null, "pronunciation": "shì shàng", "ipa": "ʂɻ̩˥˩ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "世上无难事，只怕有心人。", "target_word": "世上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "世上的钱，你赚不完。", "target_word": "世上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想看看世上所有的海。", "target_word": "世上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "世上的好东西太多了，我买不完。", "target_word": "世上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "世上最大的鸟是什么？", "target_word": "世上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爷爷说，世上的人都要吃饭。", "target_word": "世上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "世上有一种爱，叫作妈妈的爱。", "target_word": "世上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他去过世上很多地方。", "target_word": "世上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "世上只有一个你。", "target_word": "世上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "世上没有水，人就活不了。", "target_word": "世上", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "世上：世间，人世，指人们生活的整个世界", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c06df7cf-85a1-4808-b16a-c416a651824e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93862, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "世上", "is_correct": true, "explanation": "正确答案：世上（shì shàng），指这个世界上。"}, {"text": "史上", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，“史上”意为历史上，与“世上”不同。"}, {"text": "时尚", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声母韵母相同、声调不同，shàng 相同；“时尚”指流行的风尚。"}, {"text": "至上", "is_correct": false, "explanation": "zhì 与 shì 声母不同（zh/sh），声调相同（第四声），“至上”意为最高、至高无上。"}], "explanations": {"世上": "正确答案：世上（shì shàng），指这个世界上。", "史上": "shǐ（第三声）与 shì（第四声）声调不同，“史上”意为历史上，与“世上”不同。", "时尚": "shí（第二声）与 shì（第四声）声母韵母相同、声调不同，shàng 相同；“时尚”指流行的风尚。", "至上": "zhì 与 shì 声母不同（zh/sh），声调相同（第四声），“至上”意为最高、至高无上。"}, "sentence_index": null, "correct_answer": "世上"}, "level_3": {"options": [{"text": "世上", "is_correct": true, "explanation": "“世上”指人世间，与“无难事，只怕有心人”这一泛指哲理的语境相符。"}, {"text": "教室", "is_correct": false, "explanation": "语义：“教室”是具体的上课场所，句中说的是普遍道理，“教室无难事”说不通。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是具体场所，不能作为“无难事，只怕有心人”这一泛指判断的主语。"}, {"text": "操场", "is_correct": false, "explanation": "搭配：“操场”是运动场所，不能与“无难事”这种对事情的泛指判断搭配。"}], "explanations": {"世上": "“世上”指人世间，与“无难事，只怕有心人”这一泛指哲理的语境相符。", "教室": "语义：“教室”是具体的上课场所，句中说的是普遍道理，“教室无难事”说不通。", "厨房": "语义：“厨房”是具体场所，不能作为“无难事，只怕有心人”这一泛指判断的主语。", "操场": "搭配：“操场”是运动场所，不能与“无难事”这种对事情的泛指判断搭配。"}, "sentence_index": 0, "correct_answer": "世上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "杭州被誉为世上天堂。", "explanation": "这里应该用〈人间天堂〉。“人间天堂”是固定说法，比喻风景优美的地方；“世上”不能替代“人间”组成这个词。"}, {"text": "我的自行车就停在世上的门口。", "explanation": "这里应该用〈门边〉之类的方位词。“世上”是泛指人类社会的说法，不能当作具体地点的方位词。"}, {"text": "他夺得了世上，成了这个国家的新主人。", "explanation": "这里应该用〈天下〉。“天下”可指国家的统治权，“世上”不能表示政权，“夺得了世上”不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df2ab6c9-3636-4fce-84e3-76b71cc52b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93862, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "世上", "is_correct": true, "explanation": "“世上”指人世间，“世上有一种爱”指世间存在这样的爱，符合语境。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：“苹果”是水果，不能作“有一种爱”的存在范围，句子说不通。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”不是处所或范围，“声音有一种爱”说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是处所或范围，不能作“有一种爱”的存在范围。"}], "explanations": {"世上": "“世上”指人世间，“世上有一种爱”指世间存在这样的爱，符合语境。", "苹果": "语义：“苹果”是水果，不能作“有一种爱”的存在范围，句子说不通。", "声音": "语义：“声音”不是处所或范围，“声音有一种爱”说不通。", "颜色": "语义：“颜色”不是处所或范围，不能作“有一种爱”的存在范围。"}, "sentence_index": 6, "correct_answer": "世上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我们班的世上最会画画的同学。", "explanation": "这里应该用〈全班〉。“世上”指整个人类世界，不能与“我们班”这样的小范围并列限定，应去掉“世上”，说全班最会画画的同学。"}, {"text": "他在音乐世上很有名。", "explanation": "“世上”不能指某个行业的圈子，说音乐领域的名声要用〈音乐界〉。"}, {"text": "这个国家的世上只有一座大城市。", "explanation": "这里应该用〈国内〉。“世上”指整个人类世界，不能当作一个国家的范围来限定，国家范围要说〈国内〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df2ab6c9-3636-4fce-84e3-76b71cc52b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93862, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想世上找到一个真心朋友。", "corrected_sentence": "我想在世上找到一个真心朋友。", "error_description": "“世上”是表示地点的成分，前面须加介词“在”，说“在世上找到”；漏掉“在”成“想世上找到”，句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df2ab6c9-3636-4fce-84e3-76b71cc52b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93862, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "世上里没有免费的午餐。", "corrected_sentence": "世上没有免费的午餐。", "error_description": "“世上”本身已表示“这个世界上”的范围，后面不能再加方位词“里”，应说“世上没有免费的午餐”；“世上里”属于重复表示处所，错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df2ab6c9-3636-4fce-84e3-76b71cc52b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93863, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93863, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93863, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "干等是什么都不做，只是在那里等。", "primary_collocate": null, "pronunciation": "gān děng", "ipa": "kan˥˥ tɤŋ˨˩", "syllable_count": 2, "sentences": [{"text": "你别干等，去做点别的事吧。", "target_word": "干等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在门口干等了一个小时。", "target_word": "干等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她什么也不做，只是干等着。", "target_word": "干等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要在家里干等，快打电话问问。", "target_word": "干等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我坐在车里干等着，手机也没带。", "target_word": "干等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们别干等了，先吃饭吧。", "target_word": "干等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子在教室外干等妈妈来接。", "target_word": "干等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一个人在雨里干等。", "target_word": "干等", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "与其干等，不如先去看看。", "target_word": "干等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在医院干等了半天，没人理她。", "target_word": "干等", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "干等了", "label": "体标"}, {"form": "干等着", "label": "体标"}], "register": "口语", "sense_fingerprint": "什么也不做，只在原地等待", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ab86027-31e9-470c-a719-029cfab81c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93863, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "干等", "is_correct": true, "explanation": "正确。句中是劝人不要白白等待、去做别的事，符合“干等”的意思。"}, {"text": "存在", "is_correct": false, "explanation": "语义：存在指事物有或在，不能要求别人“别存在”，句子不通。"}, {"text": "知道", "is_correct": false, "explanation": "配价：“知道”是心理状态动词，不能用“你别知道”来要求对方，句中也没有可接的宾语。"}, {"text": "出生", "is_correct": false, "explanation": "语义：出生指婴儿降生，不能要求别人“别出生”，与句意无关。"}], "explanations": {"干等": "正确。句中是劝人不要白白等待、去做别的事，符合“干等”的意思。", "存在": "语义：存在指事物有或在，不能要求别人“别存在”，句子不通。", "知道": "配价：“知道”是心理状态动词，不能用“你别知道”来要求对方，句中也没有可接的宾语。", "出生": "语义：出生指婴儿降生，不能要求别人“别出生”，与句意无关。"}, "sentence_index": 0, "correct_answer": "干等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在车站干等的时候一直在看书。", "explanation": "这里与词义矛盾。〈干等〉指什么也不做地白等，句中却说一直在看书，二者不能同时成立，应换用〈等〉。"}, {"text": "妈妈在厨房干等，很快就做好了晚饭。", "explanation": "这里与词义矛盾。〈干等〉指什么也不做地白等，句中却说妈妈在厨房忙着做饭，二者不能同时成立。"}, {"text": "他飞快地干等了一会儿。", "explanation": "这里与词义矛盾。〈干等〉是什么也不做地白等，不能用“飞快地”修饰，动作快与“什么也不做”冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93863, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "干等", "is_correct": true, "explanation": "正确。孩子在教室外白白地等妈妈来接，符合“干等”的意思。"}, {"text": "挥手", "is_correct": false, "explanation": "语义：挥手是打招呼或告别的动作，与等妈妈来接的情境不符，句子不通。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：结婚与孩子在教室外等妈妈来接没有关系，句子不通。"}, {"text": "驻守", "is_correct": false, "explanation": "语域：驻守是军事或书面用语，用在孩子等妈妈的口语场景中不合语域。"}], "explanations": {"干等": "正确。孩子在教室外白白地等妈妈来接，符合“干等”的意思。", "挥手": "语义：挥手是打招呼或告别的动作，与等妈妈来接的情境不符，句子不通。", "结婚": "语义：结婚与孩子在教室外等妈妈来接没有关系，句子不通。", "驻守": "语域：驻守是军事或书面用语，用在孩子等妈妈的口语场景中不合语域。"}, "sentence_index": 6, "correct_answer": "干等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们一边打扫卫生，一边干等客人。", "explanation": "这里与词义矛盾。〈干等〉是什么也不做地白等，句中却在打扫卫生，二者不能同时成立，应换用〈等〉。"}, {"text": "他在车站干等的时候，顺便把作业写完了。", "explanation": "这里与词义矛盾。〈干等〉指什么也不做地白等，句中却说他写完了作业，二者不能同时成立，应换用〈等〉。"}, {"text": "他一边干等，一边给朋友发消息。", "explanation": "这里与词义矛盾。〈干等〉表示什么也不做，句中却在发消息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93863, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在车站干等了了两个小时。", "corrected_sentence": "他在车站干等了两个小时。", "error_description": "错误形式：“干等了了”；正确形式：“干等了”。同一个动态助词“了”不能重复出现，应只用一个“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93863, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子别在门口很干等了，快进屋吧。", "corrected_sentence": "孩子别在门口干等了，快进屋吧。", "error_description": "错误形式：“很干等”；正确形式：“干等”。程度副词“很”不能直接修饰动词，应删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93864, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93864, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93864, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "白白地等待；没有办法，只能一直等。", "primary_collocate": null, "pronunciation": "gān děng", "ipa": "kan˥˥ tɤŋ˨˩", "syllable_count": 2, "sentences": [{"text": "车坏了，我们只能在路边干等。", "target_word": "干等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友没来，他只能干等了一晚上。", "target_word": "干等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络断了，我们只好干等着。", "target_word": "干等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没人来开门，我只能在外面干等。", "target_word": "干等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机晚点了，大家只能干等。", "target_word": "干等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不想再干等了，没有人会来了。", "target_word": "干等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板一直不回电话，我只能干等着。", "target_word": "干等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪太大了，司机只能在山上干等。", "target_word": "干等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她干等了三天，却没有一点消息。", "target_word": "干等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有钥匙，我们只好在门外干等。", "target_word": "干等", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "干等了", "label": "体标"}, {"form": "干等着", "label": "体标"}], "register": "口语", "sense_fingerprint": "无计可施、白白地等待", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ab86027-31e9-470c-a719-029cfab81c38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93864, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "干等", "is_correct": true, "explanation": "正确。车坏了，只能在路边白白地等，符合“干等”的意思。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”需要考场和试卷，车坏了在路边不能用来描述，句子不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：路边不能游泳，句子说的是车坏了的无奈等待，“游泳”与句意不符。"}, {"text": "结账", "is_correct": false, "explanation": "搭配：“结账”需要餐厅或商店等场所，不说在路边结账。"}], "explanations": {"干等": "正确。车坏了，只能在路边白白地等，符合“干等”的意思。", "考试": "语义：“考试”需要考场和试卷，车坏了在路边不能用来描述，句子不通。", "游泳": "语义：路边不能游泳，句子说的是车坏了的无奈等待，“游泳”与句意不符。", "结账": "搭配：“结账”需要餐厅或商店等场所，不说在路边结账。"}, "sentence_index": 0, "correct_answer": "干等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我有很多办法，所以只能干等着。", "explanation": "这里与词义矛盾。〈干等〉表示无计可施、白白地等，句中说有很多办法，二者不能同用。"}, {"text": "他刚刚想出了一个好办法，却还在原地干等。", "explanation": "这里与词义矛盾。〈干等〉表示没有办法、白白地等，句中说已经想出了好办法，二者不能同时成立。"}, {"text": "旁边就有出租车，我们却只能在路边干等。", "explanation": "这里与词义矛盾。〈干等〉表示没有办法、只能白白地等，句中旁边就有出租车，有办法可用，不该说“只能干等”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93864, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "干等", "is_correct": true, "explanation": "正确。老板不回电话，我只能白白地等着，符合“干等”的意思。"}, {"text": "喝水", "is_correct": false, "explanation": "语义：喝水与老板不回电话的无奈等待无关，句子不通。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：咳嗽是身体反应，不是应对等待的办法，句子不通。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”与老板不回电话、只能等的情境无关，句子不通。"}], "explanations": {"干等": "正确。老板不回电话，我只能白白地等着，符合“干等”的意思。", "喝水": "语义：喝水与老板不回电话的无奈等待无关，句子不通。", "咳嗽": "语义：咳嗽是身体反应，不是应对等待的办法，句子不通。", "结婚": "语义：“结婚”与老板不回电话、只能等的情境无关，句子不通。"}, "sentence_index": 6, "correct_answer": "干等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们有钥匙，却只好在门外干等。", "explanation": "这里与词义矛盾。〈干等〉表示没有办法、只能白等，句中有钥匙，不该用〈干等〉。"}, {"text": "我手里拿着钥匙，只能在门外干等。", "explanation": "这里与词义矛盾。〈干等〉表示没有办法、只能白白地等，句中手里有钥匙，完全可以开门，二者不能同时成立。"}, {"text": "他果断地行动起来，却还在门外干等。", "explanation": "这里与词义矛盾。〈干等〉表示没有办法、只能白白地等，句中说他果断行动，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93864, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车站没车了，我们只好干等了了一个小时。", "corrected_sentence": "车站没车了，我们只好干等了一个小时。", "error_description": "错误形式：“干等了了”；正确形式：“干等了”。同一个动态助词“了”不能重复出现，应只用一个“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93864, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "没有钥匙，我们别在门外很干等了，去找人帮忙吧。", "corrected_sentence": "没有钥匙，我们别在门外干等了，去找人帮忙吧。", "error_description": "错误形式：“很干等”；正确形式：“干等”。程度副词“很”不能直接修饰动词，应删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea627613-dcc9-44e9-9b24-e92f501fd4bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93865, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df2ab6c9-3636-4fce-84e3-76b71cc52b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93865, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df2ab6c9-3636-4fce-84e3-76b71cc52b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93865, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "人均是把总数分给每一个人，每人得到的数。", "primary_collocate": null, "pronunciation": "rén jūn", "ipa": "ɻən˧˥ tɕyn˥", "syllable_count": 2, "sentences": [{"text": "这笔钱分下来，人均五百元。", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "全班一共买了六十本书，人均两本。", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次活动的费用，人均一百块。", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们公司去年发的奖金，人均三千元。", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小区的停车位太少，人均不到一个。", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们六个人，人均两千元。", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水果一共二十斤，人均四斤。", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭馆的消费，人均八十元左右。", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块地一共十亩，人均才一亩多。", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "班里的零食，人均能分到三包。", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容词：把总数分给每个人，每人得到的数量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c06df7cf-85a1-4808-b16a-c416a651824e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93865, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "人均", "is_correct": true, "explanation": "正确答案。人均：把总数分给每个人，每人得到的数量。"}, {"text": "忍俊", "is_correct": false, "explanation": "rěn jùn 与 rén jūn 声母韵母相同，两个字声调都不同；“忍俊”指忍住笑（如“忍俊不禁”）。"}, {"text": "民军", "is_correct": false, "explanation": "mín 与 rén 声母不同（m 与 r），声调相同（第二声）；意思是人民的军队。"}, {"text": "人居", "is_correct": false, "explanation": "rén 相同，jū 与 jūn 的韵尾不同（没有 n），声调相同（第一声）；意思是人类居住。"}], "explanations": {"人均": "正确答案。人均：把总数分给每个人，每人得到的数量。", "忍俊": "rěn jùn 与 rén jūn 声母韵母相同，两个字声调都不同；“忍俊”指忍住笑（如“忍俊不禁”）。", "民军": "mín 与 rén 声母不同（m 与 r），声调相同（第二声）；意思是人民的军队。", "人居": "rén 相同，jū 与 jūn 的韵尾不同（没有 n），声调相同（第一声）；意思是人类居住。"}, "sentence_index": null, "correct_answer": "人均"}, "level_3": {"options": [{"text": "人均", "is_correct": true, "explanation": "正确。此处人均修饰“五百元”，表示每人分得的数额，与“分下来”的语境一致。"}, {"text": "篇均", "is_correct": false, "explanation": "语义：“篇均”按篇数平均，钱款不以“篇”计，句中说不通。"}, {"text": "件均", "is_correct": false, "explanation": "量词：“件”用于计量物品，不能用来计量钱款，句中说不通。"}, {"text": "页均", "is_correct": false, "explanation": "量词：“页”用于计量纸张，钱款不能按“页”平均，句中说不通。"}], "explanations": {"人均": "正确。此处人均修饰“五百元”，表示每人分得的数额，与“分下来”的语境一致。", "篇均": "语义：“篇均”按篇数平均，钱款不以“篇”计，句中说不通。", "件均": "量词：“件”用于计量物品，不能用来计量钱款，句中说不通。", "页均": "量词：“页”用于计量纸张，钱款不能按“页”平均，句中说不通。"}, "sentence_index": 0, "correct_answer": "人均"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个地区的年降雨量人均一千毫米。", "explanation": "这里应该用〈平均〉。“人均”只按人口计算，降雨量不能按人均，要说“平均一千毫米”。"}, {"text": "这台机器的人均寿命是十年。", "explanation": "这里应该用〈平均〉。“人均”只按人口计算，机器的寿命不能按人均，要说“平均寿命”。"}, {"text": "这个学校的班级人均规模是三十人。", "explanation": "这里应该用〈平均〉。“人均”只按人口计算，班级规模按班级算，不能说人均。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df2ab6c9-3636-4fce-84e3-76b71cc52b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93865, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人均", "is_correct": true, "explanation": "正确。此处人均表示平均到每人的数量，与“一共二十斤”的总量相对应。"}, {"text": "艘均", "is_correct": false, "explanation": "量词：“艘”用于船只，水果不能用“艘”计量，句中说不通。"}, {"text": "台均", "is_correct": false, "explanation": "搭配：“台”多用于机器、设备，不能用于水果，不能说台均。"}, {"text": "页均", "is_correct": false, "explanation": "量词：“页”用于计量纸张，水果不能按“页”平均，句中说不通。"}], "explanations": {"人均": "正确。此处人均表示平均到每人的数量，与“一共二十斤”的总量相对应。", "艘均": "量词：“艘”用于船只，水果不能用“艘”计量，句中说不通。", "台均": "搭配：“台”多用于机器、设备，不能用于水果，不能说台均。", "页均": "量词：“页”用于计量纸张，水果不能按“页”平均，句中说不通。"}, "sentence_index": 6, "correct_answer": "人均"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这箱零食只给了我一个人，人均能分到三包。", "explanation": "这里应该用〈独得〉。“人均”要求平均到两人以上，只给一个人时要说“全部归我”，不能用“人均”。"}, {"text": "这些苹果的人均重量是二百克。", "explanation": "这里应该用〈平均〉。“人均”只按人口计算，苹果的重量不能按人均，要说“平均重量”。"}, {"text": "这座山的人均海拔很高。", "explanation": "这里应该用〈平均〉。“人均”只按人口计算，山的海拔不能按人均。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df2ab6c9-3636-4fce-84e3-76b71cc52b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93865, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这笔补贴分下来，人均了五百元。", "corrected_sentence": "这笔补贴分下来，人均五百元。", "error_description": "错误在“人均”之后多了“了”。“人均”是修饰语，不能带“了”，正确形式是“人均五百元”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df2ab6c9-3636-4fce-84e3-76b71cc52b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93865, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次团建的费用，很人均两百元。", "corrected_sentence": "这次团建的费用，人均两百元。", "error_description": "错误在“人均”前多了“很”。“人均”是非程度形容词，不能受程度副词“很”修饰，正确形式是“人均两百元”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df2ab6c9-3636-4fce-84e3-76b71cc52b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93866, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df2ab6c9-3636-4fce-84e3-76b71cc52b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
