INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93866, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "平均到每个人的；按人口平均计算的。", "primary_collocate": null, "pronunciation": "rén jūn", "ipa": "ɻən˧˥ tɕyn˥", "syllable_count": 2, "sentences": [{"text": "这个国家的人均收入越来越高。", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北京的人均住房面积是多少？", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家的人均寿命已经超过七十岁了。", "target_word": "人均", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市人均耕地很少。", "target_word": "人均", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "人均用水量每年都在下降。", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们国家的人均消费水平不高。", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的人均收入比去年多了两千元。", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人均绿地面积大的城市，空气一般比较好。", "target_word": "人均", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸说，今年人均消费增加了。", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个地区人均粮食产量很高。", "target_word": "人均", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容词：修饰名词，按人口平均计算的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c06df7cf-85a1-4808-b16a-c416a651824e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93866, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "人均", "is_correct": true, "explanation": "正确答案。人均：按人口平均计算的。"}, {"text": "忍俊", "is_correct": false, "explanation": "rěn jùn 与 rén jūn 声母韵母相同，两个字声调都不同；“忍俊”指忍住笑（如“忍俊不禁”）。"}, {"text": "民军", "is_correct": false, "explanation": "mín 与 rén 声母不同（m 与 r），声调相同（第二声）；意思是人民的军队。"}, {"text": "人居", "is_correct": false, "explanation": "rén 相同，jū 与 jūn 的韵尾不同（没有 n），声调相同（第一声）；意思是人类居住。"}], "explanations": {"人均": "正确答案。人均：按人口平均计算的。", "忍俊": "rěn jùn 与 rén jūn 声母韵母相同，两个字声调都不同；“忍俊”指忍住笑（如“忍俊不禁”）。", "民军": "mín 与 rén 声母不同（m 与 r），声调相同（第二声）；意思是人民的军队。", "人居": "rén 相同，jū 与 jūn 的韵尾不同（没有 n），声调相同（第一声）；意思是人类居住。"}, "sentence_index": null, "correct_answer": "人均"}, "level_3": {"options": [{"text": "人均", "is_correct": true, "explanation": "正确。此处人均修饰“收入”，表示按人口平均计算的收入。"}, {"text": "台均", "is_correct": false, "explanation": "搭配：“台”是机器、设备的量词，不能用来修饰“收入”。"}, {"text": "件均", "is_correct": false, "explanation": "搭配：“件”用于计量物品，不能用于说明一个国家的收入。"}, {"text": "页均", "is_correct": false, "explanation": "量词：“页”用于计量纸张，不能用来说明一个国家的收入。"}], "explanations": {"人均": "正确。此处人均修饰“收入”，表示按人口平均计算的收入。", "台均": "搭配：“台”是机器、设备的量词，不能用来修饰“收入”。", "件均": "搭配：“件”用于计量物品，不能用于说明一个国家的收入。", "页均": "量词：“页”用于计量纸张，不能用来说明一个国家的收入。"}, "sentence_index": 0, "correct_answer": "人均"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个城市的人均温度很高。", "explanation": "这里应该用〈平均〉。“人均”只按人口计算，温度不能按人均，要说“平均温度”。"}, {"text": "这台电脑的人均内存很大。", "explanation": "这里应该用〈平均〉。“人均”只按人口计算，单台电脑的内存不能按人均。"}, {"text": "这个城市的人均人口很少。", "explanation": "这里应该用〈总数〉。“人均”是平均数，不能修饰“人口”这种总数，要说“这个城市的人口很少”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df2ab6c9-3636-4fce-84e3-76b71cc52b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93866, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人均", "is_correct": true, "explanation": "正确。此处人均修饰“收入”，表示平均到每人的收入。"}, {"text": "篇均", "is_correct": false, "explanation": "语义：“篇均”按篇数平均，收入不以“篇”计，句中说不通。"}, {"text": "页均", "is_correct": false, "explanation": "量词：“页”用于计量纸张，不能用来计量收入，句中说不通。"}, {"text": "班均", "is_correct": false, "explanation": "语义：“班均”指按班级平均，句中是地区的收入，不是班级的。"}], "explanations": {"人均": "正确。此处人均修饰“收入”，表示平均到每人的收入。", "篇均": "语义：“篇均”按篇数平均，收入不以“篇”计，句中说不通。", "页均": "量词：“页”用于计量纸张，不能用来计量收入，句中说不通。", "班均": "语义：“班均”指按班级平均，句中是地区的收入，不是班级的。"}, "sentence_index": 6, "correct_answer": "人均"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的人均速度是每小时六十公里。", "explanation": "这里应该用〈平均〉。“人均”只按人口计算，车速不能按人均，要说“平均速度”。"}, {"text": "这条河的人均长度很长。", "explanation": "这里应该用〈平均〉。“人均”只按人口计算，河的长度不能按人均。"}, {"text": "这块地的人均亩产很高。", "explanation": "这里应该用〈每亩〉。“人均”只按人口计算，亩产是按土地算的，不能用人均。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df2ab6c9-3636-4fce-84e3-76b71cc52b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93866, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市的人均了用电量逐年下降。", "corrected_sentence": "这个城市的人均用电量逐年下降。", "error_description": "错误在“人均”之后多了“了”。“人均”修饰“用电量”，中间不能加“了”，正确形式是“人均用电量”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df2ab6c9-3636-4fce-84e3-76b71cc52b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93866, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个省的很人均粮食产量逐年增加。", "corrected_sentence": "这个省的人均粮食产量逐年增加。", "error_description": "错误在“人均”前多了“很”。“人均”是非程度形容词，不能受程度副词“很”修饰，正确形式是“人均粮食产量”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df2ab6c9-3636-4fce-84e3-76b71cc52b74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93867, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93867, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93867, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "以便是为了让后面的事更容易做到。", "primary_collocate": null, "pronunciation": "yǐ biàn", "ipa": "i˨˩ pjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我早点出门，以便赶上第一班地铁。", "target_word": "以便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请留下电话，以便我们联系你。", "target_word": "以便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把书放在桌上，以便明天找到。", "target_word": "以便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们提前订票，以便假期出去玩。", "target_word": "以便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天写日记，以便记住重要的事。", "target_word": "以便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把名字写清楚，以便老师认识大家。", "target_word": "以便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买了一张地图，以便找到那家饭店。", "target_word": "以便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早点睡觉，以便明天有精神。", "target_word": "以便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司多开了一个窗口，以便客人少排队。", "target_word": "以便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把家里的灯打开，以便孩子回来时看得见。", "target_word": "以便", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "前一动作是为了让后面的事更容易做到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1ebf27a-bc60-422b-bfea-fa9b711a051c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93867, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "以免", "is_correct": false, "explanation": "语义：「以免」表示避免某种不好的结果，与「赶上第一班地铁」的目的相反，句意说不通。"}, {"text": "以便", "is_correct": true, "explanation": "以便：表示为了使后面的事情更容易做到，此处引出「赶上第一班地铁」这一目的。"}, {"text": "但是", "is_correct": false, "explanation": "语义：「但是」表示转折，而「早点出门」与「赶上地铁」之间没有转折关系。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：「虽然」表示让步，需与「但是」「却」等相配，句中没有对应的转折词。"}], "explanations": {"以免": "语义：「以免」表示避免某种不好的结果，与「赶上第一班地铁」的目的相反，句意说不通。", "以便": "以便：表示为了使后面的事情更容易做到，此处引出「赶上第一班地铁」这一目的。", "但是": "语义：「但是」表示转折，而「早点出门」与「赶上地铁」之间没有转折关系。", "虽然": "搭配：「虽然」表示让步，需与「但是」「却」等相配，句中没有对应的转折词。"}, "sentence_index": 0, "correct_answer": "以便"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我早点出门，以便赶不上第一班地铁。", "explanation": "这里应该用〈以免〉。以便表示为了使后面的事更容易做到，要表示避免「赶不上」这种结果，应用〈以免〉。"}, {"text": "他昨天没睡好，以便今天很累。", "explanation": "这里应该用〈所以〉。以便只能引出目的，不能引出已经发生的结果，此处应用〈所以〉。"}, {"text": "你快点走，以便要迟到了。", "explanation": "这里应该用〈否则〉。以便表示目的，不能引出不好的后果；「不快点就会迟到」应用〈否则〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93867, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "因为", "is_correct": false, "explanation": "语义：「因为」表示原因，「找到那家饭店」不能作为「买地图」的原因，句意不通。"}, {"text": "以便", "is_correct": true, "explanation": "以便：表示为了使后面的事情更容易做到，此处引出「找到那家饭店」这一目的。"}, {"text": "只要", "is_correct": false, "explanation": "搭配：「只要」表示充分条件，后面需与「就」相配，句中没有「就」，且语义不通。"}, {"text": "不然", "is_correct": false, "explanation": "语义：「不然」表示否定假设的后果，与「买了一张地图」之后的「找到饭店」不相符。"}], "explanations": {"因为": "语义：「因为」表示原因，「找到那家饭店」不能作为「买地图」的原因，句意不通。", "以便": "以便：表示为了使后面的事情更容易做到，此处引出「找到那家饭店」这一目的。", "只要": "搭配：「只要」表示充分条件，后面需与「就」相配，句中没有「就」，且语义不通。", "不然": "语义：「不然」表示否定假设的后果，与「买了一张地图」之后的「找到饭店」不相符。"}, "sentence_index": 6, "correct_answer": "以便"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "比赛推迟了，以便下雨。", "explanation": "这里应该用〈因为〉。以便表示目的，不能引出原因；「比赛推迟」的原因是「下雨」，应用〈因为〉。"}, {"text": "他很聪明，以便学习不太努力。", "explanation": "这里应该用〈但是〉。以便表示目的，不能表示转折；「很聪明」与「学习不太努力」是转折关系，应用〈但是〉。"}, {"text": "我们还是去了公园，以便天气不好。", "explanation": "这里应该用〈尽管〉。以便表示目的，不能表示让步；「天气不好」是让步关系，应用〈尽管〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93867, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他提前半小时到站，以便为了买到车票。", "corrected_sentence": "他提前半小时到站，以便买到车票。", "error_description": "错误形式：「以便为了买到车票」。正确形式：「以便买到车票」。「以便」已经表示目的，再加「为了」是重复的目的标记，应去掉「为了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93867, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把钥匙放在门口以便，回家时拿到。", "corrected_sentence": "我们把钥匙放在门口，以便回家时拿到。", "error_description": "错误形式：「门口以便，回家时拿到」。正确形式：「门口，以便回家时拿到」。「以便」必须紧接主句之后、引出目的小句，不能单独停在主句末尾。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93869, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "免职", "is_correct": true, "explanation": "解除职务，与“任命”（委派工作）的含义相反。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌指发出乐音，与“任命”无关。"}, {"text": "翻译", "is_correct": false, "explanation": "翻译指转换语言，与“任命”无反义关系。"}, {"text": "生长", "is_correct": false, "explanation": "生长指生物发育变大，与“任命”无反义关系。"}], "correct_answer": "免职", "explanations": {"免职": "解除职务，与“任命”（委派工作）的含义相反。", "唱歌": "唱歌指发出乐音，与“任命”无关。", "翻译": "翻译指转换语言，与“任命”无反义关系。", "生长": "生长指生物发育变大，与“任命”无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93869, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "罢免", "is_correct": true, "explanation": "撤销职务，与“任命”（委派工作）的含义相反。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳指在水中运动，与“任命”无关。"}, {"text": "观察", "is_correct": false, "explanation": "观察指仔细看，与“任命”无反义关系。"}, {"text": "写作", "is_correct": false, "explanation": "写作指写文章，与“任命”无反义关系。"}], "correct_answer": "罢免", "explanations": {"罢免": "撤销职务，与“任命”（委派工作）的含义相反。", "游泳": "游泳指在水中运动，与“任命”无关。", "观察": "观察指仔细看，与“任命”无反义关系。", "写作": "写作指写文章，与“任命”无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93869, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "任命是上面的人选一个人，让他去做某个工作。", "primary_collocate": null, "pronunciation": "rèn mìng", "ipa": "ɻən˥˩ miŋ˥˩", "syllable_count": 2, "sentences": [{"text": "老板任命小王当组长。", "target_word": "任命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "领导任命我负责这次活动。", "target_word": "任命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长任命了一个新老师管图书馆。", "target_word": "任命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司任命他负责北京分部的工作。", "target_word": "任命", "complexity_tier": "T3", "furigana": "gōng sī rèn mìng tā fù zé Běi jīng fēn bù de gōng zuò", "sentence_source": "generated"}, {"text": "上级任命他去管那个小工厂。", "target_word": "任命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师任命小明当班长。", "target_word": "任命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厂长今天任命了两个新组长。", "target_word": "任命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总经理任命她负责客人的接待。", "target_word": "任命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长任命最年轻的人当副队长。", "target_word": "任命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主任任命我去管仓库。", "target_word": "任命", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "任命了", "label": "体标"}, {"form": "任命过", "label": "体标"}], "register": "书面", "sense_fingerprint": "上级选定一个人，让他去做某项工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ac5386f-a5c3-4a5f-b7d7-6ad2731789e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93869, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "任命", "is_correct": true, "explanation": "上级选定人选、让其做工作，与“老板……小王当组长”相符。"}, {"text": "选举", "is_correct": false, "explanation": "搭配：“选举”需要多人投票，老板一人决定时不说选举。"}, {"text": "辞退", "is_correct": false, "explanation": "语义：辞退是解雇员工，与“老板任命小王当组长”的委派相反。"}, {"text": "撤销", "is_correct": false, "explanation": "语义：撤销指取消已有职务，与“任命小王当组长”的委派相反。"}], "explanations": {"任命": "上级选定人选、让其做工作，与“老板……小王当组长”相符。", "选举": "搭配：“选举”需要多人投票，老板一人决定时不说选举。", "辞退": "语义：辞退是解雇员工，与“老板任命小王当组长”的委派相反。", "撤销": "语义：撤销指取消已有职务，与“任命小王当组长”的委派相反。"}, "sentence_index": 0, "correct_answer": "任命"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "同事们任命小王当组长。", "explanation": "这里应该用〈推举〉。任命须由有权限的上级作出，同事之间只能推举。"}, {"text": "他任命了北京分部的工作。", "explanation": "这里应该用〈接管〉。任命的对象是人或职务，接手一项工作要用接管。"}, {"text": "公司任命了三名员工去北京学习。", "explanation": "这里应该用〈选拔〉。任命针对职务，挑选人员去学习要用选拔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93869, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "任命", "is_correct": true, "explanation": "厂长委派新组长去做工作，与“今天……了两个新组长”相符。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：“种植”的对象是植物，不能说“种植组长”。"}, {"text": "阅读", "is_correct": false, "explanation": "搭配：“阅读”的对象是书报文章，不能说“阅读组长”。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指烹饪食物，与委派组长无关。"}], "explanations": {"任命": "厂长委派新组长去做工作，与“今天……了两个新组长”相符。", "种植": "搭配：“种植”的对象是植物，不能说“种植组长”。", "阅读": "搭配：“阅读”的对象是书报文章，不能说“阅读组长”。", "煮": "语义：“煮”指烹饪食物，与委派组长无关。"}, "sentence_index": 6, "correct_answer": "任命"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我任命自己去管仓库。", "explanation": "这里应该用〈自荐〉。任命须由上级作出，自己不能给自己任命。"}, {"text": "学校任命了一位专家来做讲座。", "explanation": "这里应该用〈邀请〉。任命针对职务，请专家来做讲座只用邀请。"}, {"text": "主任任命了新的仓库管理规定。", "explanation": "这里应该用〈制定〉。任命的对象是人或职务，规定要用制定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93869, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "总经理任命小李海外业务。", "corrected_sentence": "总经理任命小李负责海外业务。", "error_description": "错误：“任命小李”后缺少动词。应补上“负责”或“管”，如“任命小李负责海外业务”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93869, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明年，学校将任命了新的图书馆负责人。", "corrected_sentence": "明年，学校将任命新的图书馆负责人。", "error_description": "错误：“将”表示将来，不能与“了”同用。应说“将任命新的图书馆负责人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
