INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93870, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "委派某人担任某项职务。", "primary_collocate": null, "pronunciation": "rèn mìng", "ipa": "ɻən˥˩ miŋ˥˩", "syllable_count": 2, "sentences": [{"text": "公司任命他为新经理。", "target_word": "任命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长任命李老师担任班主任。", "target_word": "任命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长昨天任命了一位新秘书。", "target_word": "任命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府任命她为教育局局长。", "target_word": "任命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "董事会决定任命王先生为总裁。", "target_word": "任命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上个月，总统任命了三位新部长。", "target_word": "任命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校还没有任命新的校长。", "target_word": "任命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理任命小张负责这个部门。", "target_word": "任命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板已经把他任命为总经理了。", "target_word": "任命", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上级任命我当组长。", "target_word": "任命", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "任命了", "label": "体标"}, {"form": "任命过", "label": "体标"}], "register": "书面", "sense_fingerprint": "正式委派某人担任某个职务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ac5386f-a5c3-4a5f-b7d7-6ad2731789e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93870, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "任命", "is_correct": true, "explanation": "上级正式委派职务，与“他为新经理”的语境相符。"}, {"text": "解雇", "is_correct": false, "explanation": "语义：解雇指辞退员工，与“公司……他为新经理”的委派相反。"}, {"text": "拒绝", "is_correct": false, "explanation": "搭配：“拒绝”的对象是请求、要求，不能用于委派某人为经理。"}, {"text": "撤销", "is_correct": false, "explanation": "语义：撤销指取消已有职务，与“委派他为新经理”的意思相反。"}], "explanations": {"任命": "上级正式委派职务，与“他为新经理”的语境相符。", "解雇": "语义：解雇指辞退员工，与“公司……他为新经理”的委派相反。", "拒绝": "搭配：“拒绝”的对象是请求、要求，不能用于委派某人为经理。", "撤销": "语义：撤销指取消已有职务，与“委派他为新经理”的意思相反。"}, "sentence_index": 0, "correct_answer": "任命"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生们任命小王当班长。", "explanation": "这里应该用〈选举〉。任命是上级委派职务，学生推举班长要用选举。"}, {"text": "公司任命了一百名新员工。", "explanation": "这里应该用〈招聘〉。任命只用于委派职务，大批录用普通员工要用招聘。"}, {"text": "公司任命他去北京出差。", "explanation": "这里应该用〈派〉。任命针对职务，临时出差只用派。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93870, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "任命", "is_correct": true, "explanation": "上级委派校长，与“还没有”后接“新的校长”相符。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：“种植”的对象是植物，不能说“种植校长”。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是机器、物品，不能用于委派校长。"}, {"text": "阅读", "is_correct": false, "explanation": "搭配：“阅读”的对象是书报文章，不能说“阅读校长”。"}], "explanations": {"任命": "上级委派校长，与“还没有”后接“新的校长”相符。", "种植": "搭配：“种植”的对象是植物，不能说“种植校长”。", "修理": "搭配：“修理”的对象是机器、物品，不能用于委派校长。", "阅读": "搭配：“阅读”的对象是书报文章，不能说“阅读校长”。"}, "sentence_index": 6, "correct_answer": "任命"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他任命自己当经理。", "explanation": "这里应该用〈自荐〉。任命必须由上级作出，自己不能任命自己。"}, {"text": "学校任命了新的规定。", "explanation": "这里应该用〈制定〉。任命的对象是人或职务，规定要用制定。"}, {"text": "学校任命他来做讲座。", "explanation": "这里应该用〈邀请〉。任命针对职务，请人来做讲座只用邀请。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93870, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "董事会任命她的为财务总监。", "corrected_sentence": "董事会任命她为财务总监。", "error_description": "错误：“她”后多出“的”。“任命＋人＋为＋职务”中，“人”后应直接接“为”，即“任命她为财务总监”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
