INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93871, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "保守是不愿意改变，喜欢照着老样子做。", "primary_collocate": null, "pronunciation": "bǎo shǒu", "ipa": "pɑʊ̯²¹⁴ ʂoʊ̯²¹⁴", "syllable_count": 2, "sentences": [{"text": "爷爷的想法很保守。", "target_word": "保守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对新东西总是很保守。", "target_word": "保守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司做法太保守，不敢试新办法。", "target_word": "保守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她穿衣服比较保守，不喜欢太新潮的。", "target_word": "保守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老一辈人的观念比较保守。", "target_word": "保守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很保守，从来不愿换工作。", "target_word": "保守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的想法别这么保守，试试新方法吧。", "target_word": "保守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保守的人不喜欢变化。", "target_word": "保守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家的家教很保守，晚上不让女儿出门。", "target_word": "保守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小镇的人很保守，不太欢迎外人。", "target_word": "保守", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "保守派", "label": "复合词"}, {"form": "保守主义", "label": "复合词"}], "register": "中性", "sense_fingerprint": "人的想法或习惯不愿变、爱照老样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4215d43d-f30b-4b99-bb09-a9960ea2a2a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93871, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "保守", "is_correct": true, "explanation": "正确答案。读音 bǎo shǒu，指不愿改变、爱照老样子做。"}, {"text": "饱受", "is_correct": false, "explanation": "shòu（第四声）与 shǒu（第三声）声调不同，意思是充分地承受。"}, {"text": "老手", "is_correct": false, "explanation": "lǎo 与 bǎo 的声母不同（l 与 b），意思是经验丰富的人。"}, {"text": "好手", "is_correct": false, "explanation": "hǎo 与 bǎo 的声母不同（h 与 b），意思是技艺高明的人。"}], "explanations": {"保守": "正确答案。读音 bǎo shǒu，指不愿改变、爱照老样子做。", "饱受": "shòu（第四声）与 shǒu（第三声）声调不同，意思是充分地承受。", "老手": "lǎo 与 bǎo 的声母不同（l 与 b），意思是经验丰富的人。", "好手": "hǎo 与 bǎo 的声母不同（h 与 b），意思是技艺高明的人。"}, "sentence_index": null, "correct_answer": "保守"}, "level_3": {"options": [{"text": "保守", "is_correct": true, "explanation": "正确。“爷爷的想法很保守”说的是老人不愿改变想法。"}, {"text": "调皮", "is_correct": false, "explanation": "语义：“调皮”形容淘气的孩子，不能说“爷爷的想法很调皮”。"}, {"text": "高大", "is_correct": false, "explanation": "语义：“高大”形容体形，用来说想法不合适。"}, {"text": "苗条", "is_correct": false, "explanation": "语义：“苗条”形容身材，不能说“想法很苗条”。"}], "explanations": {"保守": "正确。“爷爷的想法很保守”说的是老人不愿改变想法。", "调皮": "语义：“调皮”形容淘气的孩子，不能说“爷爷的想法很调皮”。", "高大": "语义：“高大”形容体形，用来说想法不合适。", "苗条": "语义：“苗条”形容身材，不能说“想法很苗条”。"}, "sentence_index": 0, "correct_answer": "保守"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个软件很保守，每天都有新功能。", "explanation": "这里应该用〈更新〉。“保守”指人不愿改变，软件应说“更新”。"}, {"text": "这种病很保守，医生让她多休息。", "explanation": "这里应该用〈轻〉。“保守”形容人的态度，病的程度应说“轻”。"}, {"text": "这块石头很保守，不会变形。", "explanation": "这里应该用〈坚固〉。“保守”形容人的态度，石头应说“坚固”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93871, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保守", "is_correct": true, "explanation": "正确。“你的想法别这么保守”是劝对方改变想法。"}, {"text": "热情", "is_correct": false, "explanation": "语义：“别这么热情，试试新方法”的语气不通，与劝人改变的语境不合。"}, {"text": "整齐", "is_correct": false, "explanation": "语义：“想法很整齐”说不通，与“试试新方法”的语境不合。"}, {"text": "健康", "is_correct": false, "explanation": "语义：“别这么健康”与“试试新方法”的劝导语境相悖，健康是正面评价，不能用来劝人改变。"}], "explanations": {"保守": "正确。“你的想法别这么保守”是劝对方改变想法。", "热情": "语义：“别这么热情，试试新方法”的语气不通，与劝人改变的语境不合。", "整齐": "语义：“想法很整齐”说不通，与“试试新方法”的语境不合。", "健康": "语义：“别这么健康”与“试试新方法”的劝导语境相悖，健康是正面评价，不能用来劝人改变。"}, "sentence_index": 6, "correct_answer": "保守"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河很保守，水流得很慢。", "explanation": "这里应该用〈平缓〉。“保守”形容人的想法或做法，河水应说“平缓”。"}, {"text": "今天的天气很保守，一直很冷。", "explanation": "这里应该用〈寒冷〉。“保守”形容人不愿改变，天气不能说“保守”。"}, {"text": "这杯饮料很保守，喝起来不太甜。", "explanation": "这里应该用〈淡〉。“保守”形容人的态度，饮料的口味只能说“淡”之类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93871, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我父亲对新事物一向保守很。", "corrected_sentence": "我父亲对新事物一向保守得很。", "error_description": "程度补语要用“得”连接，应说“保守得很”，不能说“保守很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93871, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是个很保守人。", "corrected_sentence": "他是个很保守的人。", "error_description": "形容词“保守”修饰名词时要加“的”，应说“很保守的人”，不能说“很保守人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93872, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "开放", "is_correct": true, "explanation": "开放：与“保守”互为反义，指不固守旧观念，愿意接受新事物。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：“清楚”指明白、不模糊，与“保守”不构成反义关系。"}, {"text": "高兴", "is_correct": false, "explanation": "无关：“高兴”表示愉快的情绪，与“保守”不是反义词。"}, {"text": "便宜", "is_correct": false, "explanation": "无关：“便宜”指价格低，与“保守”在任何义项上都不是反义关系。"}], "correct_answer": "开放", "explanations": {"开放": "开放：与“保守”互为反义，指不固守旧观念，愿意接受新事物。", "清楚": "无关：“清楚”指明白、不模糊，与“保守”不构成反义关系。", "高兴": "无关：“高兴”表示愉快的情绪，与“保守”不是反义词。", "便宜": "无关：“便宜”指价格低，与“保守”在任何义项上都不是反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93872, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "开放", "is_correct": true, "explanation": "开放：与“保守”互为反义，指不固守旧观念，愿意接受新事物。"}, {"text": "快速", "is_correct": false, "explanation": "无关：“快速”指速度快，与“保守”不构成反义关系。"}, {"text": "冷淡", "is_correct": false, "explanation": "无关：“冷淡”指态度不热情，与“保守”在此义项上不是反义词。"}, {"text": "明亮", "is_correct": false, "explanation": "无关：“明亮”指光线充足、清楚，与“保守”没有反义关系。"}], "correct_answer": "开放", "explanations": {"开放": "开放：与“保守”互为反义，指不固守旧观念，愿意接受新事物。", "快速": "无关：“快速”指速度快，与“保守”不构成反义关系。", "冷淡": "无关：“冷淡”指态度不热情，与“保守”在此义项上不是反义词。", "明亮": "无关：“明亮”指光线充足、清楚，与“保守”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93872, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不愿改变、固守旧有观念或做法的；不求新。", "primary_collocate": null, "pronunciation": "bǎo shǒu", "ipa": "pɑʊ̯²¹⁴ ʂoʊ̯²¹⁴", "syllable_count": 2, "sentences": [{"text": "我爸爸是个保守的人，不爱尝试新事物。", "target_word": "保守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的计划太保守，没有新意。", "target_word": "保守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的投资方式很保守。", "target_word": "保守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的教法有点保守，还是老样子。", "target_word": "保守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对新技术的态度比较保守。", "target_word": "保守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别太保守了，大胆试一试。", "target_word": "保守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老先生思想保守，不接受新观念。", "target_word": "保守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小城的风气比较保守。", "target_word": "保守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他保守得连手机都不用。", "target_word": "保守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理的做法很保守，只照老办法做。", "target_word": "保守", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "保守派", "label": "复合词"}, {"form": "保守主义", "label": "复合词"}], "register": "中性", "sense_fingerprint": "思想、做法固守旧样、不求创新", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4215d43d-f30b-4b99-bb09-a9960ea2a2a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93872, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保守", "is_correct": true, "explanation": "保守：不愿改变旧观念和做法，与“不爱尝试新事物”相符。"}, {"text": "开放", "is_correct": false, "explanation": "语义：“开放”指愿意接受新事物，与后半句“不爱尝试新事物”矛盾。"}, {"text": "激进", "is_correct": false, "explanation": "语义：“激进”指急于求新、主张变革，与“不爱尝试新事物”相反。"}, {"text": "时髦", "is_correct": false, "explanation": "语义：“时髦”指紧跟潮流，与后半句“不爱尝试新事物”矛盾。"}], "explanations": {"保守": "保守：不愿改变旧观念和做法，与“不爱尝试新事物”相符。", "开放": "语义：“开放”指愿意接受新事物，与后半句“不爱尝试新事物”矛盾。", "激进": "语义：“激进”指急于求新、主张变革，与“不爱尝试新事物”相反。", "时髦": "语义：“时髦”指紧跟潮流，与后半句“不爱尝试新事物”矛盾。"}, "sentence_index": 0, "correct_answer": "保守"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这套设备很保守，早该换新的了。", "explanation": "这里应该用〈陈旧〉。保守形容人的思想或做法不肯改变，不用来形容设备；设备老旧要说陈旧。"}, {"text": "这道题很保守，大家很快就做完了。", "explanation": "这里应该用〈简单〉。保守形容人的想法或做法，不用来形容题目的难易；题目容易要说简单。"}, {"text": "这台空调的温度保守在二十度。", "explanation": "这里应该用〈保持〉。保守指守住秘密或保守的态度，不用于描述温度；维持某种状态要用保持。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93872, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保守", "is_correct": true, "explanation": "保守：思想守旧、不接受新事物，与“不接受新观念”一致。"}, {"text": "开明", "is_correct": false, "explanation": "语义：“开明”指思想开放、能接受新事物，与“不接受新观念”矛盾。"}, {"text": "前卫", "is_correct": false, "explanation": "语义：“前卫”指思想超前、紧跟新潮，与“不接受新观念”相反。"}, {"text": "辛辣", "is_correct": false, "explanation": "搭配：“辛辣”多形容味道或言辞，不说“思想辛辣”。"}], "explanations": {"保守": "保守：思想守旧、不接受新事物，与“不接受新观念”一致。", "开明": "语义：“开明”指思想开放、能接受新事物，与“不接受新观念”矛盾。", "前卫": "语义：“前卫”指思想超前、紧跟新潮，与“不接受新观念”相反。", "辛辣": "搭配：“辛辣”多形容味道或言辞，不说“思想辛辣”。"}, "sentence_index": 6, "correct_answer": "保守"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的笑容很保守，大家都喜欢。", "explanation": "这里应该用〈热情〉。保守指思想或做法守旧，不用来形容笑容或待人的态度；表示热情要用热情。"}, {"text": "这栋楼很保守，需要重新修缮。", "explanation": "这里应该用〈老旧〉。保守说的是思想或做法，不用来形容建筑；楼房破旧要说老旧。"}, {"text": "这杯咖啡很保守，一点也不甜。", "explanation": "这里应该用〈苦〉。保守形容人的思想或做法守旧，不用来形容味道；咖啡不甜要说苦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93872, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个老人是个保守地人，不爱出门。", "corrected_sentence": "这个老人是个保守的人，不爱出门。", "error_description": "“保守”修饰名词“人”时要用结构助词“的”，写成“保守地人”是错误的；“地”用于动词或形容词前作状语，此处应为“保守的人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93872, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他保守很，从来不用手机。", "corrected_sentence": "他保守得很，从来不用手机。", "error_description": "程度补语要用“得”连接，应说“保守得很”，不能说“保守很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
