INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93873, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "备是先把东西准备好。", "primary_collocate": null, "pronunciation": "bèi", "ipa": "pei˥˩", "syllable_count": 1, "sentences": [{"text": "出远门要先备足钱。", "target_word": "备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶备了很多年货。", "target_word": "备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天要冷了，妈妈给我备了厚衣服。", "target_word": "备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先备好饭，再去接孩子。", "target_word": "备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他备了一份小礼物送给老师。", "target_word": "备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里总是备着感冒药。", "target_word": "备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上来客人，我得去备菜。", "target_word": "备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她早就备下了过冬的米和面。", "target_word": "备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行前，我们备好了地图。", "target_word": "备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你备一些零钱，坐车用。", "target_word": "备", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "备了", "label": "体标"}, {"form": "备着", "label": "体标"}, {"form": "准备", "label": "复合"}], "register": "口语", "sense_fingerprint": "先把东西准备好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4215d43d-f30b-4b99-bb09-a9960ea2a2a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93873, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "备", "is_correct": true, "explanation": "备：事先把东西准备好，读 bèi（第四声）。"}, {"text": "北", "is_correct": false, "explanation": "běi（第三声）与 bèi（第四声）声调不同，意思是北方。"}, {"text": "杯", "is_correct": false, "explanation": "bēi（第一声）与 bèi（第四声）声调不同，意思是杯子。"}, {"text": "配", "is_correct": false, "explanation": "pèi 与 bèi 声母不同（p 与 b），意思是配合。"}, {"text": "碑", "is_correct": false, "explanation": "bēi（第一声）与 bèi（第四声）声调不同，意思是石碑。"}], "explanations": {"备": "备：事先把东西准备好，读 bèi（第四声）。", "北": "běi（第三声）与 bèi（第四声）声调不同，意思是北方。", "杯": "bēi（第一声）与 bèi（第四声）声调不同，意思是杯子。", "配": "pèi 与 bèi 声母不同（p 与 b），意思是配合。", "碑": "bēi（第一声）与 bèi（第四声）声调不同，意思是石碑。"}, "sentence_index": null, "correct_answer": "备"}, "level_3": {"options": [{"text": "备", "is_correct": true, "explanation": "备：事先准备，「要先备足钱」指提前准备足够的钱。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指饮食或消耗，“吃足钱”与“提前准备钱”的意思不符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：「唱」不能接「钱」，「唱足钱」不成立。"}, {"text": "睡", "is_correct": false, "explanation": "语义：「睡」指睡眠，与“提前准备钱”的意思无关。"}], "explanations": {"备": "备：事先准备，「要先备足钱」指提前准备足够的钱。", "吃": "语义：“吃”指饮食或消耗，“吃足钱”与“提前准备钱”的意思不符。", "唱": "搭配：「唱」不能接「钱」，「唱足钱」不成立。", "睡": "语义：「睡」指睡眠，与“提前准备钱”的意思无关。"}, "sentence_index": 0, "correct_answer": "备"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我先备你回家，再去超市。", "explanation": "这里应该用〈送〉。备指预备物品，不能用来指送人回家。"}, {"text": "我先备脸，再去接孩子。", "explanation": "这里应该用〈洗〉。备指预备物品，不指清洁身体。"}, {"text": "我先备狗，再去接孩子。", "explanation": "这里应该用〈喂〉。备指预备，不指喂养动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93873, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "备", "is_correct": true, "explanation": "备：事先把东西准备好，读 bèi（第四声）。"}, {"text": "悲", "is_correct": false, "explanation": "bēi（第一声）与 bèi（第四声）声调不同，意思是悲伤。"}, {"text": "佩", "is_correct": false, "explanation": "pèi 与 bèi 声母不同（p 与 b），意思是佩服。"}, {"text": "败", "is_correct": false, "explanation": "bài 与 bèi 韵母不同（ai 与 ei），意思是失败。"}, {"text": "拜", "is_correct": false, "explanation": "bài 与 bèi 韵母不同（ai 与 ei），意思是拜访。"}], "explanations": {"备": "备：事先把东西准备好，读 bèi（第四声）。", "悲": "bēi（第一声）与 bèi（第四声）声调不同，意思是悲伤。", "佩": "pèi 与 bèi 声母不同（p 与 b），意思是佩服。", "败": "bài 与 bèi 韵母不同（ai 与 ei），意思是失败。", "拜": "bài 与 bèi 韵母不同（ai 与 ei），意思是拜访。"}, "sentence_index": null, "correct_answer": "备"}, "level_3": {"options": [{"text": "备", "is_correct": true, "explanation": "备：事先准备，「我得去备菜」指去预备饭菜。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：「穿」不能接「菜」作宾语，「穿菜」不成立。"}, {"text": "写", "is_correct": false, "explanation": "搭配：「写」不能接「菜」，「写菜」不成立。"}, {"text": "念", "is_correct": false, "explanation": "语义：「念」指朗读，与“预备菜”的意思不符。"}], "explanations": {"备": "备：事先准备，「我得去备菜」指去预备饭菜。", "穿": "搭配：「穿」不能接「菜」作宾语，「穿菜」不成立。", "写": "搭配：「写」不能接「菜」，「写菜」不成立。", "念": "语义：「念」指朗读，与“预备菜”的意思不符。"}, "sentence_index": 6, "correct_answer": "备"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他向朋友备钱，过几天还。", "explanation": "这里应该用〈借〉。备指事先准备，不指借入。"}, {"text": "他把画备在墙上。", "explanation": "这里应该用〈挂〉。备表示事先准备，不表示悬挂。"}, {"text": "他对着蜡烛备了一口气。", "explanation": "这里应该用〈吹〉。备指预备，不指吹动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93873, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "出门前，我备先好了衣服。", "corrected_sentence": "出门前，我先备好了衣服。", "error_description": "状语位置错误：副词“先”应放在动词前，说“先备好”，不能说“备先”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93873, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末有客人来，我还备没好菜。", "corrected_sentence": "周末有客人来，我还没备好菜。", "error_description": "否定词位置错误：“没”应放在动词前，说“还没备好菜”，不能说“备没好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
