INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93874, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "准备；预备。", "primary_collocate": null, "pronunciation": "bèi", "ipa": "pei˥˩", "syllable_count": 1, "sentences": [{"text": "妈妈备了一桌好菜。", "target_word": "备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前，我备好了雨伞。", "target_word": "备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人快到了，快去备茶。", "target_word": "备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在包里备着一些药。", "target_word": "备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末要去爬山，你先备点水吧。", "target_word": "备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷给孙子备了新年礼物。", "target_word": "备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们早就备好了车。", "target_word": "备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们备下酒菜等朋友来。", "target_word": "备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你备三个杯子。", "target_word": "备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在桌上备着笔和纸。", "target_word": "备", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "备了", "label": "体标"}, {"form": "备着", "label": "体标"}, {"form": "准备", "label": "复合"}], "register": "口语", "sense_fingerprint": "事先预备好东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4215d43d-f30b-4b99-bb09-a9960ea2a2a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93874, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "备", "is_correct": true, "explanation": "备：准备、预备，读 bèi（第四声）。"}, {"text": "北", "is_correct": false, "explanation": "běi（第三声）与 bèi（第四声）声调不同，意思是北方。"}, {"text": "配", "is_correct": false, "explanation": "pèi 与 bèi 声母不同（p 与 b），意思是配合。"}, {"text": "杯", "is_correct": false, "explanation": "bēi（第一声）与 bèi（第四声）声调不同，意思是杯子。"}, {"text": "悲", "is_correct": false, "explanation": "bēi（第一声）与 bèi（第四声）声调不同，意思是悲伤。"}], "explanations": {"备": "备：准备、预备，读 bèi（第四声）。", "北": "běi（第三声）与 bèi（第四声）声调不同，意思是北方。", "配": "pèi 与 bèi 声母不同（p 与 b），意思是配合。", "杯": "bēi（第一声）与 bèi（第四声）声调不同，意思是杯子。", "悲": "bēi（第一声）与 bèi（第四声）声调不同，意思是悲伤。"}, "sentence_index": null, "correct_answer": "备"}, "level_3": {"options": [{"text": "备", "is_correct": true, "explanation": "备：事先准备，「妈妈备了一桌好菜」指妈妈预备好了饭菜。"}, {"text": "洗", "is_correct": false, "explanation": "语义：洗是清洗，与“准备一桌好菜”的意思不符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：「唱」不能接「菜」作宾语，「唱了一桌好菜」不成立。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：「穿」只能接衣物，不能接「菜」，「穿了一桌好菜」不成立。"}], "explanations": {"备": "备：事先准备，「妈妈备了一桌好菜」指妈妈预备好了饭菜。", "洗": "语义：洗是清洗，与“准备一桌好菜”的意思不符。", "唱": "搭配：「唱」不能接「菜」作宾语，「唱了一桌好菜」不成立。", "穿": "搭配：「穿」只能接衣物，不能接「菜」，「穿了一桌好菜」不成立。"}, "sentence_index": 0, "correct_answer": "备"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他提前备了三位朋友，等他们来吃饭。", "explanation": "这里应该用〈招待〉。备指预备物品，不能预备人。"}, {"text": "他把药备到桌子上，怕忘了吃。", "explanation": "这里应该用〈放〉。备是事先准备，不表示放置。"}, {"text": "他把垃圾备进了箱子里。", "explanation": "这里应该用〈扔〉。备指预备，不表示投掷或扔进去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93874, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "备", "is_correct": true, "explanation": "备：准备、预备，读 bèi（第四声）。"}, {"text": "佩", "is_correct": false, "explanation": "pèi 与 bèi 声母不同（p 与 b），意思是佩服。"}, {"text": "碑", "is_correct": false, "explanation": "bēi（第一声）与 bèi（第四声）声调不同，意思是石碑。"}, {"text": "败", "is_correct": false, "explanation": "bài 与 bèi 韵母不同（ai 与 ei），意思是失败。"}, {"text": "拜", "is_correct": false, "explanation": "bài 与 bèi 韵母不同（ai 与 ei），意思是拜访。"}], "explanations": {"备": "备：准备、预备，读 bèi（第四声）。", "佩": "pèi 与 bèi 声母不同（p 与 b），意思是佩服。", "碑": "bēi（第一声）与 bèi（第四声）声调不同，意思是石碑。", "败": "bài 与 bèi 韵母不同（ai 与 ei），意思是失败。", "拜": "bài 与 bèi 韵母不同（ai 与 ei），意思是拜访。"}, "sentence_index": null, "correct_answer": "备"}, "level_3": {"options": [{"text": "备", "is_correct": true, "explanation": "备：事先准备，「我们早就备好了车」指车已经准备妥当。"}, {"text": "写", "is_correct": false, "explanation": "搭配：「写」不能与「车」搭配，「写好了车」不成立。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」指饮食，不能用于车，与句子的意思不符。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：「喝」不能接「车」作宾语，「喝好了车」不成立。"}], "explanations": {"备": "备：事先准备，「我们早就备好了车」指车已经准备妥当。", "写": "搭配：「写」不能与「车」搭配，「写好了车」不成立。", "吃": "语义：「吃」指饮食，不能用于车，与句子的意思不符。", "喝": "搭配：「喝」不能接「车」作宾语，「喝好了车」不成立。"}, "sentence_index": 6, "correct_answer": "备"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师下课后，把桌子备干净了。", "explanation": "这里应该用〈收拾〉。备指预备，不表示整理，「备干净」不成立。"}, {"text": "老师用布备黑板。", "explanation": "这里应该用〈擦〉。备指预备，不指擦拭。"}, {"text": "老师在黑板上备字，学生们都看不清。", "explanation": "这里应该用〈写〉。备指预备，不表示书写。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93874, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我先备成了早饭。", "corrected_sentence": "我先备好了早饭。", "error_description": "补语用错：备的结果补语应为“好”，“备成”不能表示预备，应说“备好了早饭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93874, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "客人来之前，我已经备着好了茶。", "corrected_sentence": "客人来之前，我已经备好了茶。", "error_description": "体标错误：“着”不能插在结果补语“好”之前，应说“备好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
