INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93875, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "传奇是特别神奇又让人难忘的故事。", "primary_collocate": null, "pronunciation": "chuán qí", "ipa": "ʈʂʰwan˧˥ tɕʰi˧˥", "syllable_count": 2, "sentences": [{"text": "爷爷给我们讲了一段海上的传奇。", "target_word": "传奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人的一生就是一段传奇。", "target_word": "传奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个传奇我听过很多次，一直忘不了。", "target_word": "传奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老房子里有一个美丽的传奇。", "target_word": "传奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把自己的传奇写成了一本书。", "target_word": "传奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的人都知道那位英雄的传奇。", "target_word": "传奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的传奇让很多孩子相信梦想。", "target_word": "传奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小城有一个让人难忘的传奇。", "target_word": "传奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上，奶奶总是讲着古老的传奇。", "target_word": "传奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个关于龙的传奇，孩子们百听不厌。", "target_word": "传奇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段传奇", "label": "量词"}, {"form": "传奇故事", "label": "复合"}, {"form": "传奇人物", "label": "复合"}], "register": "中性", "sense_fingerprint": "神奇而难忘的故事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '838411ca-cf0b-4532-ae63-837208e58bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93875, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "传奇", "is_correct": true, "explanation": "正确：“一段海上的传奇”指海上神奇而难忘的故事，与句意吻合。"}, {"text": "货物", "is_correct": false, "explanation": "搭配：“讲”不能与“货物”搭配，“讲一段海上的货物”说不通。"}, {"text": "航线", "is_correct": false, "explanation": "语义：“航线”指船只的路线，“讲一段海上的航线”句意不通。"}, {"text": "潮水", "is_correct": false, "explanation": "语义：“潮水”指海水的涨落，不能用“讲”来说，句意不通。"}], "explanations": {"传奇": "正确：“一段海上的传奇”指海上神奇而难忘的故事，与句意吻合。", "货物": "搭配：“讲”不能与“货物”搭配，“讲一段海上的货物”说不通。", "航线": "语义：“航线”指船只的路线，“讲一段海上的航线”句意不通。", "潮水": "语义：“潮水”指海水的涨落，不能用“讲”来说，句意不通。"}, "sentence_index": 0, "correct_answer": "传奇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月的水电传奇是三百元。", "explanation": "这里的“传奇”被当成了账单，传奇是故事，不指费用，应说“账单”。"}, {"text": "这个病人的传奇很严重，需要马上住院。", "explanation": "这里的“传奇”被当成了病情，传奇是故事，不能用来说病的轻重，应说“病情”。"}, {"text": "我家到学校的传奇只要十分钟，很近。", "explanation": "这里的“传奇”被当成了路程，传奇是神奇的故事，不指距离，应说“路程”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93875, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "传奇", "is_correct": true, "explanation": "正确：“她的传奇”指她神奇而感人的经历故事，能让孩子们相信梦想，与句意吻合。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是外形特征，不能让很多孩子相信梦想，句意不通。"}, {"text": "发型", "is_correct": false, "explanation": "语义：“发型”指头发的样式，“她的发型让很多孩子相信梦想”说不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指价钱，不能让孩子们相信梦想，句意不通。"}], "explanations": {"传奇": "正确：“她的传奇”指她神奇而感人的经历故事，能让孩子们相信梦想，与句意吻合。", "身高": "体貌：“身高”是外形特征，不能让很多孩子相信梦想，句意不通。", "发型": "语义：“发型”指头发的样式，“她的发型让很多孩子相信梦想”说不通。", "价格": "语义：“价格”指价钱，不能让孩子们相信梦想，句意不通。"}, "sentence_index": 6, "correct_answer": "传奇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在海边捡到一个贝壳，觉得很漂亮，拿回家当传奇。", "explanation": "传奇是故事，不是能拿在手里的物品，不能“当传奇”。"}, {"text": "这次比赛的传奇是第三名，我很高兴。", "explanation": "这里的“传奇”被当成了名次，传奇是故事，不能用来说比赛的名次，应说“名次”。"}, {"text": "他的传奇很大声，隔壁的邻居都听见了。", "explanation": "这里的“传奇”被当成了声音，传奇是故事，不能用“大声”形容，应说“声音”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93875, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷讲了一条很长的传奇。", "corrected_sentence": "爷爷讲了一段很长的传奇。", "error_description": "量词错误：“传奇”应用“段”，不能用“条”（“条”多用于细长的东西）。正确说法是“讲了一段很长的传奇”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93875, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他写了一张动人的传奇。", "corrected_sentence": "他写了一段动人的传奇。", "error_description": "量词错误：“传奇”应用“段”，不能用“张”（“张”用于平面的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
