INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93876, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "情节离奇、带有传说色彩的故事。", "primary_collocate": null, "pronunciation": "chuán qí", "ipa": "ʈʂʰwan˧˥ tɕʰi˧˥", "syllable_count": 2, "sentences": [{"text": "这是一个关于山神的传奇，情节很离奇。", "target_word": "传奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里的传奇带着浓浓的神话色彩。", "target_word": "传奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里流传着一个关于白蛇的传奇。", "target_word": "传奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影讲了一个关于狐仙的传奇。", "target_word": "传奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢读各地的民间传奇。", "target_word": "传奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，湖底住着龙，这是当地的传奇。", "target_word": "传奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个传奇一开始很平常，后来越来越神。", "target_word": "传奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写的传奇里有仙人，也有会说话的鱼。", "target_word": "传奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说把真实的人物写成了带神话色彩的传奇。", "target_word": "传奇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导游给我们讲了这座塔的传奇。", "target_word": "传奇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个传奇", "label": "量词"}, {"form": "民间传奇", "label": "复合"}, {"form": "传奇故事", "label": "复合"}], "register": "中性", "sense_fingerprint": "情节离奇、带传说色彩的故事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '838411ca-cf0b-4532-ae63-837208e58bb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93876, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "传奇", "is_correct": true, "explanation": "正确：“一个关于山神的传奇”指情节离奇的传说故事，与“情节很离奇”吻合。"}, {"text": "报告", "is_correct": false, "explanation": "语义：“报告”是公文或陈述，“情节很离奇”不能形容报告，句意不通。"}, {"text": "菜谱", "is_correct": false, "explanation": "语义：“菜谱”指做菜的说明，不是故事，“情节很离奇”说不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”不能用来指关于山神的故事，“情节”也不能修饰价格。"}], "explanations": {"传奇": "正确：“一个关于山神的传奇”指情节离奇的传说故事，与“情节很离奇”吻合。", "报告": "语义：“报告”是公文或陈述，“情节很离奇”不能形容报告，句意不通。", "菜谱": "语义：“菜谱”指做菜的说明，不是故事，“情节很离奇”说不通。", "价格": "搭配：“价格”不能用来指关于山神的故事，“情节”也不能修饰价格。"}, "sentence_index": 0, "correct_answer": "传奇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的传奇很冷，我们多穿了一件衣服。", "explanation": "这里的“传奇”被当成了天气，传奇指离奇的故事，不指冷热，应说“天气”。"}, {"text": "孩子们喜欢猜传奇，常常猜得很快。", "explanation": "这里的“传奇”被当成了谜语，传奇是故事，不能用“猜”，应说“谜语”。"}, {"text": "这次考试他的传奇考得很好，全班第一。", "explanation": "这里的“传奇”被当成了成绩，传奇是故事，不能用来说考试的分数，应说“成绩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93876, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "传奇", "is_correct": true, "explanation": "正确：“这个传奇”指一个情节神奇、越讲越神的故事，与句意吻合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”指冷热阴晴，不是故事，“这个天气越来越神”说不通。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指身体的温度，不能用来说故事的情节变化。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“作业”不能用“越来越神”来形容，搭配不当。"}], "explanations": {"传奇": "正确：“这个传奇”指一个情节神奇、越讲越神的故事，与句意吻合。", "天气": "语义：“天气”指冷热阴晴，不是故事，“这个天气越来越神”说不通。", "体温": "语义：“体温”指身体的温度，不能用来说故事的情节变化。", "作业": "搭配：“作业”不能用“越来越神”来形容，搭配不当。"}, "sentence_index": 6, "correct_answer": "传奇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他感冒了，传奇很严重，需要去医院看看。", "explanation": "这里的“传奇”被当成了病情，传奇是故事，不能用来说病的轻重，应说“病情”。"}, {"text": "妈妈做的传奇很好吃，我们吃了两碗。", "explanation": "传奇是故事，不是食物，不能说“做”和“吃”，应说“饭菜”。"}, {"text": "这座塔的传奇有三十米高。", "explanation": "传奇指神奇的故事，不能用来说高度，这里的“传奇”用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93876, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我小时候常听奶奶讲一杯狐仙的传奇。", "corrected_sentence": "我小时候常听奶奶讲一段狐仙的传奇。", "error_description": "量词错误：“传奇”应用“段”，不能用“杯”（“杯”用于盛在杯子里的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93876, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人讲了一台山里的传奇。", "corrected_sentence": "老人讲了一段山里的传奇。", "error_description": "量词错误：“传奇”应用“段”，不能用“台”（“台”用于机器）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0ec27d6-0ac2-4ff6-a964-83fdf83abe93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
