INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93881, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "与犯法、犯罪有关的。", "primary_collocate": null, "pronunciation": "xíng shì", "ipa": "ɕiŋ˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这是一起刑事案件。", "target_word": "刑事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察正在调查那起刑事案件。", "target_word": "刑事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他犯了罪，要负刑事责任。", "target_word": "刑事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刑事警察今天抓到了小偷。", "target_word": "刑事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王律师专门办刑事案子。", "target_word": "刑事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是刑事律师，经常去法院。", "target_word": "刑事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "偷了很多钱，这是刑事犯罪。", "target_word": "刑事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子做错事，一般不负刑事责任。", "target_word": "刑事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个刑事案子，警察查了三个月。", "target_word": "刑事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家银行发生了刑事案件。", "target_word": "刑事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "刑事案件", "label": "复合"}, {"form": "刑事责任", "label": "复合"}], "register": "书面", "sense_fingerprint": "与犯法、犯罪有关的（多修饰案件、责任等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ac5386f-a5c3-4a5f-b7d7-6ad2731789e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93881, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刑事", "is_correct": true, "explanation": "与犯罪有关，修饰“案件”，符合语境。"}, {"text": "美丽", "is_correct": false, "explanation": "语义：美丽形容外貌或景色，不能修饰案件。"}, {"text": "幸福", "is_correct": false, "explanation": "语义：幸福形容心情或生活状态，不说幸福案件。"}, {"text": "清淡", "is_correct": false, "explanation": "搭配：清淡多形容口味、颜色，不修饰案件。"}], "explanations": {"刑事": "与犯罪有关，修饰“案件”，符合语境。", "美丽": "语义：美丽形容外貌或景色，不能修饰案件。", "幸福": "语义：幸福形容心情或生活状态，不说幸福案件。", "清淡": "搭配：清淡多形容口味、颜色，不修饰案件。"}, "sentence_index": 0, "correct_answer": "刑事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们为了分房子，打了一场刑事官司。", "explanation": "这里应该用〈民事〉。分房子的争议属于民事官司，不涉及犯罪。"}, {"text": "他们签了一份刑事合同。", "explanation": "这里应该用〈经济〉。经济合同属于民事或经济关系，不属于刑事。"}, {"text": "违章停车，他要负刑事责任。", "explanation": "这里应该用〈行政〉。违章停车属于行政违法，只负行政责任。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93881, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刑事", "is_correct": true, "explanation": "与犯罪有关，符合“偷了很多钱，这是……犯罪”的语境。"}, {"text": "民事", "is_correct": false, "explanation": "语义：民事不涉及犯罪，“民事犯罪”不成立。"}, {"text": "美丽", "is_correct": false, "explanation": "搭配：美丽形容外貌或景色，不能修饰犯罪。"}, {"text": "甜美", "is_correct": false, "explanation": "搭配：甜美形容面容或声音，不修饰犯罪。"}], "explanations": {"刑事": "与犯罪有关，符合“偷了很多钱，这是……犯罪”的语境。", "民事": "语义：民事不涉及犯罪，“民事犯罪”不成立。", "美丽": "搭配：美丽形容外貌或景色，不能修饰犯罪。", "甜美": "搭配：甜美形容面容或声音，不修饰犯罪。"}, "sentence_index": 6, "correct_answer": "刑事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他因为插队，受到了刑事处罚。", "explanation": "这里应该用〈治安〉。插队不构成犯罪，不能说刑事处罚。"}, {"text": "他因为上课迟到，受到了刑事处分。", "explanation": "这里应该用〈纪律〉。迟到属纪律问题，刑事只用于犯罪。"}, {"text": "他因为超速，被刑事警察罚了款。", "explanation": "这里应该用〈交通〉。超速属交通违法，应由交通警察处理，不归刑事警察。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93881, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他因为伤人被追究很刑事责任。", "corrected_sentence": "他因为伤人被追究刑事责任。", "error_description": "“刑事”作定语修饰“责任”，前面不能加程度副词“很”，应写作“追究刑事责任”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93881, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "当地警方正在侦办一起很刑事案件。", "corrected_sentence": "当地警方正在侦办一起刑事案件。", "error_description": "错误：“刑事”是区别词，不能受程度副词“很”修饰。去掉“很”，说“一起刑事案件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
