INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93882, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "与犯罪及其处罚有关的。", "primary_collocate": null, "pronunciation": "xíng shì", "ipa": "ɕiŋ˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他的行为已经构成刑事犯罪。", "target_word": "刑事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位法官一直审理刑事案件。", "target_word": "刑事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刑事处罚比行政处罚更严格。", "target_word": "刑事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院对他作出了刑事判决。", "target_word": "刑事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打架伤人可能要承担刑事责任。", "target_word": "刑事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刑事诉讼要按照法律程序进行。", "target_word": "刑事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学的是刑事法律。", "target_word": "刑事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公安局对他采取了刑事拘留。", "target_word": "刑事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的老板受到了刑事处罚。", "target_word": "刑事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民事纠纷和刑事案件要分开处理。", "target_word": "刑事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "刑事处罚", "label": "复合"}, {"form": "刑事诉讼", "label": "复合"}], "register": "书面", "sense_fingerprint": "与犯罪及其法律处罚有关的（法律用语）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ac5386f-a5c3-4a5f-b7d7-6ad2731789e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93882, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "刑事", "is_correct": true, "explanation": "与犯罪及其处罚有关，符合“构成……犯罪”的语境。"}, {"text": "民事", "is_correct": false, "explanation": "语义：民事不构成犯罪，“民事犯罪”不成立。"}, {"text": "幸福", "is_correct": false, "explanation": "语义：幸福形容心情或生活状态，不能修饰犯罪。"}, {"text": "美丽", "is_correct": false, "explanation": "搭配：美丽形容外貌或景色，不修饰犯罪。"}], "explanations": {"刑事": "与犯罪及其处罚有关，符合“构成……犯罪”的语境。", "民事": "语义：民事不构成犯罪，“民事犯罪”不成立。", "幸福": "语义：幸福形容心情或生活状态，不能修饰犯罪。", "美丽": "搭配：美丽形容外貌或景色，不修饰犯罪。"}, "sentence_index": 0, "correct_answer": "刑事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "行政机关对他作出了刑事处罚。", "explanation": "这里应该用〈行政〉。行政机关只能作行政处罚，刑事处罚必须由法院判决。"}, {"text": "法院对这起合同纠纷作出了刑事判决。", "explanation": "这里应该用〈民事〉。合同纠纷属民事案件，不能作刑事判决。"}, {"text": "学校对他作出了刑事处分。", "explanation": "这里应该用〈纪律〉。学校只能作纪律处分，不能作刑事处分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93882, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刑事", "is_correct": true, "explanation": "与犯罪有关，修饰“法律”，符合“他学的是……法律”的语境。"}, {"text": "幸福", "is_correct": false, "explanation": "语义：幸福形容感受，不能修饰法律。"}, {"text": "甜美", "is_correct": false, "explanation": "搭配：甜美形容面容或声音，不搭配法律。"}, {"text": "清淡", "is_correct": false, "explanation": "搭配：清淡多形容口味，不搭配法律。"}], "explanations": {"刑事": "与犯罪有关，修饰“法律”，符合“他学的是……法律”的语境。", "幸福": "语义：幸福形容感受，不能修饰法律。", "甜美": "搭配：甜美形容面容或声音，不搭配法律。", "清淡": "搭配：清淡多形容口味，不搭配法律。"}, "sentence_index": 6, "correct_answer": "刑事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他因为乱扔垃圾，受到了刑事处罚。", "explanation": "这里应该用〈行政〉。乱扔垃圾不构成犯罪，只能受行政处罚。"}, {"text": "邻居借钱不还，他去法院打了一场刑事官司。", "explanation": "这里应该用〈民事〉。借钱不还属于民事纠纷，应打民事官司。"}, {"text": "他闯红灯，被刑事警察开了罚单。", "explanation": "这里应该用〈交通〉。闯红灯属交通违法，应由交通警察处理，不归刑事警察。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93882, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "法官决定对他作出很刑事处罚。", "corrected_sentence": "法官决定对他作出刑事处罚。", "error_description": "错误：“刑事”是区别词，不能受程度副词“很”修饰。去掉“很”，说“作出刑事处罚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93882, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "法院将依法对他追究很刑事责任。", "corrected_sentence": "法院将依法对他追究刑事责任。", "error_description": "错误：“刑事”是区别词，不能受程度副词“很”修饰。应去掉“很”，直接作定语说“刑事责任”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
