INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93883, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "初中是小学以后上的学校，要上三年。", "primary_collocate": null, "pronunciation": "chū zhōng", "ipa": "ʈʂʰu˥ ʈʂʊŋ˥", "syllable_count": 2, "sentences": [{"text": "他十二岁上了初中。", "target_word": "初中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所初中离我家很近。", "target_word": "初中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "初中毕业后，她去了高中。", "target_word": "初中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和他在初中认识。", "target_word": "初中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐在初中教语文。", "target_word": "初中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "初中的课，我觉得有点难。", "target_word": "初中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的初中在一座小城里。", "target_word": "初中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从初中起就喜欢踢球。", "target_word": "初中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹还在读初中，明年上高中。", "target_word": "初中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给初中的老师写了一封信。", "target_word": "初中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "所", "label": "量词"}, {"form": "初中生", "label": "复合"}], "register": "中性", "sense_fingerprint": "小学以后上的学校，要上三年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4215d43d-f30b-4b99-bb09-a9960ea2a2a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93883, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "初中", "is_correct": true, "explanation": "正确答案。读音 chū zhōng，指小学之后的学校阶段。"}, {"text": "出众", "is_correct": false, "explanation": "zhòng（第四声）与 zhōng（第一声）声调不同，意思是“超出众人”。"}, {"text": "书中", "is_correct": false, "explanation": "shū 与 chū 的声母不同（sh 与 ch），意思是“书里”。"}, {"text": "出征", "is_correct": false, "explanation": "zhēng 与 zhōng 的韵母不同（eng 与 ong），意思是“出发去作战”。"}], "explanations": {"初中": "正确答案。读音 chū zhōng，指小学之后的学校阶段。", "出众": "zhòng（第四声）与 zhōng（第一声）声调不同，意思是“超出众人”。", "书中": "shū 与 chū 的声母不同（sh 与 ch），意思是“书里”。", "出征": "zhēng 与 zhōng 的韵母不同（eng 与 ong），意思是“出发去作战”。"}, "sentence_index": null, "correct_answer": "初中"}, "level_3": {"options": [{"text": "初中", "is_correct": true, "explanation": "正确。“初中”指小学之后的学校阶段，十二岁正读这一阶段。"}, {"text": "高中", "is_correct": false, "explanation": "语义：高中在初中之后，十二岁的孩子还读不到高中。"}, {"text": "幼儿园", "is_correct": false, "explanation": "语义：十二岁已过幼儿园年龄，与“上了”后面接的阶段不符。"}, {"text": "公司", "is_correct": false, "explanation": "语义：十二岁不会“上了公司”，“上”后接的是学校阶段。"}], "explanations": {"初中": "正确。“初中”指小学之后的学校阶段，十二岁正读这一阶段。", "高中": "语义：高中在初中之后，十二岁的孩子还读不到高中。", "幼儿园": "语义：十二岁已过幼儿园年龄，与“上了”后面接的阶段不符。", "公司": "语义：十二岁不会“上了公司”，“上”后接的是学校阶段。"}, "sentence_index": 0, "correct_answer": "初中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上喝一杯初中。", "explanation": "这里应该用〈牛奶〉。“初中”是学校，不能喝；早上喝的是牛奶。"}, {"text": "我们学校有一只初中。", "explanation": "这里应该用〈所〉。“初中”指学校，量词用“所”，“只”用于动物。"}, {"text": "他高考后上了初中。", "explanation": "这里应该用〈大学〉。高考在高中之后，考后升入的是大学；“初中”是更早的阶段，不能放在高考之后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93883, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "初中", "is_correct": true, "explanation": "正确。“我的初中”指自己读过的初级中学，“在一座小城里”说明学校的位置。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是一种病，不能“在”城里。"}, {"text": "晚饭", "is_correct": false, "explanation": "语义：“晚饭”是食物，不能用“在一座小城里”来说它的位置。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不能用“在一座小城里”来描述。"}], "explanations": {"初中": "正确。“我的初中”指自己读过的初级中学，“在一座小城里”说明学校的位置。", "感冒": "语义：“感冒”是一种病，不能“在”城里。", "晚饭": "语义：“晚饭”是食物，不能用“在一座小城里”来说它的位置。", "身材": "体貌：“身材”指人的体形，不能用“在一座小城里”来描述。"}, "sentence_index": 6, "correct_answer": "初中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去年当了初中。", "explanation": "这里应该用〈初中老师〉。“当”后接职业，“初中”是学校阶段，不能直接接在“当”后面。"}, {"text": "我把初中放进了书包里。", "explanation": "这里应该用〈课本〉。“初中”是学校，不能放进书包；放进书包的是课本。"}, {"text": "我的初中比我高一头。", "explanation": "这里应该用〈初中生〉。“初中”指学校阶段，不指人，说人的身高要用“初中生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93883, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妹妹今年考上了一只初中。", "corrected_sentence": "我妹妹今年考上了一所初中。", "error_description": "“初中”是学校，量词应用“所”，不能用“只”。正确是“一所初中”，错误是“一只初中”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93883, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我姐姐一所初中当老师。", "corrected_sentence": "我姐姐在一所初中当老师。", "error_description": "介词缺失：“在”表示处所，省去后“一所初中”无法作地点，应说“在一所初中当老师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
