INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93887, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "动机是一个人做某件事时心里的想法或原因。", "primary_collocate": null, "pronunciation": "dòng jī", "ipa": "tʊŋ˥˩ tɕi˥", "syllable_count": 2, "sentences": [{"text": "他这样做的动机是什么？", "target_word": "动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不明白她为什么帮我，她的动机不清楚。", "target_word": "动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察在调查这个案子的动机。", "target_word": "动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学中文的动机很简单，就是喜欢中国菜。", "target_word": "动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板想知道你来这家公司工作的动机。", "target_word": "动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他表面上很热心，其实动机不好。", "target_word": "动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做这件事没有别的动机，只是想帮忙。", "target_word": "动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的动机是好的，但是方法不对。", "target_word": "动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的动机很明显，就是想要钱。", "target_word": "动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面试时会问你选这份工作的动机。", "target_word": "动机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "動機", "label": "繁体"}, {"form": "一种动机", "label": "量词"}, {"form": "学习动机", "label": "复合"}], "register": "中性", "sense_fingerprint": "一个人做事时心里真正的想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d8f91e-1c52-478c-8897-5222c5cd20d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93887, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "动机", "is_correct": true, "explanation": "正确答案。动机指一个人做某件事时心里的想法。"}, {"text": "冬季", "is_correct": false, "explanation": "冬季读 dōng jì：dōng 为第一声，与 dòng（第四声）不同，jì（第四声）与 jī（第一声）也不同；意思是冬天的季节。"}, {"text": "痛击", "is_correct": false, "explanation": "声母 t 与 d 不同（tòng 与 dòng），意思是用力打击。"}, {"text": "斗鸡", "is_correct": false, "explanation": "第一音节韵母 ou 与 ong 不同（dòu 与 dòng），意思是让鸡相斗。"}], "explanations": {"动机": "正确答案。动机指一个人做某件事时心里的想法。", "冬季": "冬季读 dōng jì：dōng 为第一声，与 dòng（第四声）不同，jì（第四声）与 jī（第一声）也不同；意思是冬天的季节。", "痛击": "声母 t 与 d 不同（tòng 与 dòng），意思是用力打击。", "斗鸡": "第一音节韵母 ou 与 ong 不同（dòu 与 dòng），意思是让鸡相斗。"}, "sentence_index": null, "correct_answer": "动机"}, "level_3": {"options": [{"text": "动机", "is_correct": true, "explanation": "正确答案。句子问的是他这样做的内在原因，正是动机。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”是事物的属性，做事没有颜色，句子不通。"}, {"text": "外貌", "is_correct": false, "explanation": "体貌：“外貌”指人的长相，不能指做事的缘由。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”用于商品或服务，不能说做事的价格。"}], "explanations": {"动机": "正确答案。句子问的是他这样做的内在原因，正是动机。", "颜色": "语义：“颜色”是事物的属性，做事没有颜色，句子不通。", "外貌": "体貌：“外貌”指人的长相，不能指做事的缘由。", "价格": "搭配：“价格”用于商品或服务，不能说做事的价格。"}, "sentence_index": 0, "correct_answer": "动机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他迟到的动机是路上堵车。", "explanation": "这里应该用〈原因〉。动机指人做事时心里的想法，路上堵车是客观原因，要用“原因”。"}, {"text": "他请假的动机是身体不舒服。", "explanation": "这里应该用〈理由〉。“动机”指人心里想做某事的内在想法，请假时说明原因要用“理由”；身体不舒服是理由，不是动机。"}, {"text": "他把动机送给了朋友。", "explanation": "此句把“动机”当作可以送人的实物来用，属于误用。“动机”指人做事时的内在想法，是抽象的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93887, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "动机", "is_correct": true, "explanation": "正确答案。动机指人做事时心里的内在想法。"}, {"text": "洞悉", "is_correct": false, "explanation": "洞悉读 dòng xī：第二音节声母 x 与 j 不同（xī 与 jī），意思是清楚地了解。"}, {"text": "冻结", "is_correct": false, "explanation": "冻结读 dòng jié：第二音节是 jié（第二声，韵母 ie），与 jī 不同；意思是结冰或停止变动。"}, {"text": "动静", "is_correct": false, "explanation": "动静读 dòng jìng：第二音节韵母 ing 与 i 不同，声调也不同；意思是声音或情况。"}], "explanations": {"动机": "正确答案。动机指人做事时心里的内在想法。", "洞悉": "洞悉读 dòng xī：第二音节声母 x 与 j 不同（xī 与 jī），意思是清楚地了解。", "冻结": "冻结读 dòng jié：第二音节是 jié（第二声，韵母 ie），与 jī 不同；意思是结冰或停止变动。", "动静": "动静读 dòng jìng：第二音节韵母 ing 与 i 不同，声调也不同；意思是声音或情况。"}, "sentence_index": null, "correct_answer": "动机"}, "level_3": {"options": [{"text": "动机", "is_correct": true, "explanation": "正确答案。句子说的是没有别的内在想法，只有“动机”能填入。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指气味或滋味，做事不能有别的味道。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”指人或事物存在的时间，不能说做事没有别的年龄。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”指身体的重量，与做事的原因无关。"}], "explanations": {"动机": "正确答案。句子说的是没有别的内在想法，只有“动机”能填入。", "味道": "语义：“味道”指气味或滋味，做事不能有别的味道。", "年龄": "搭配：“年龄”指人或事物存在的时间，不能说做事没有别的年龄。", "体重": "体貌：“体重”指身体的重量，与做事的原因无关。"}, "sentence_index": 6, "correct_answer": "动机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座桥的动机很强，车辆通过很安全。", "explanation": "这里应该用〈结构〉。动机是人做事时的内在想法，桥没有想法，说桥牢固要用“结构”。"}, {"text": "他一直在动机里学习。", "explanation": "动机是抽象的想法，不是可以待在里面的地方，这里把它当作场所用，属于误用。"}, {"text": "他的动机比弟弟高两厘米。", "explanation": "动机是抽象的，没有高矮，也不能用厘米计量，这里的用法不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93887, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一只很强的动机，想要早点升职。", "corrected_sentence": "他有一种很强的动机，想要早点升职。", "error_description": "量词错误：“动机”应搭配量词“种”，不能用“只”（“只”用于动物或单个的小东西）。正确说法是“一种很强的动机”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93887, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用很强的学习动机，每天都按时复习。", "corrected_sentence": "他有很强的学习动机，每天都按时复习。", "error_description": "动词错误：“用”不能表示拥有动机，这里应说“有”，如“他有很强的学习动机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
