INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93888, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "推动人去做某件事的内在原因或目的。", "primary_collocate": null, "pronunciation": "dòng jī", "ipa": "tʊŋ˥˩ tɕi˥", "syllable_count": 2, "sentences": [{"text": "学习的动机越强，进步就越快。", "target_word": "动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想了解学生学习英语的动机。", "target_word": "动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "赚钱不是他工作的唯一动机。", "target_word": "动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子没有动机，再好的老师也没用。", "target_word": "动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的奖励能激发员工的工作动机。", "target_word": "动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "是什么动机让你开始跑步的？", "target_word": "动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有很强的成功动机，每天都最早到公司。", "target_word": "动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "缺少动机的人，很难坚持做一件事。", "target_word": "动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人来这里的动机不一样，有人为钱，有人为爱好。", "target_word": "动机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想让父母高兴，这是他努力学习的动机。", "target_word": "动机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "動機", "label": "繁体"}, {"form": "一种动机", "label": "量词"}, {"form": "学习动机", "label": "复合"}], "register": "中性", "sense_fingerprint": "推动人去行动的内在原因", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2d8f91e-1c52-478c-8897-5222c5cd20d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93888, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "动机", "is_correct": true, "explanation": "正确答案。动机指推动人去做事的内在原因或目的。"}, {"text": "冬季", "is_correct": false, "explanation": "冬季读 dōng jì：dōng 为第一声，与 dòng（第四声）不同，jì 与 jī 声调也不同；意思是冬天的季节。"}, {"text": "痛击", "is_correct": false, "explanation": "声母 t 与 d 不同（tòng 与 dòng），意思是用力打击。"}, {"text": "斗鸡", "is_correct": false, "explanation": "第一音节韵母 ou 与 ong 不同（dòu 与 dòng），意思是让鸡相斗。"}], "explanations": {"动机": "正确答案。动机指推动人去做事的内在原因或目的。", "冬季": "冬季读 dōng jì：dōng 为第一声，与 dòng（第四声）不同，jì 与 jī 声调也不同；意思是冬天的季节。", "痛击": "声母 t 与 d 不同（tòng 与 dòng），意思是用力打击。", "斗鸡": "第一音节韵母 ou 与 ong 不同（dòu 与 dòng），意思是让鸡相斗。"}, "sentence_index": null, "correct_answer": "动机"}, "level_3": {"options": [{"text": "动机", "is_correct": true, "explanation": "正确答案。句子说的是推动学习的内在原因，正是动机。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“速度”通常说快慢，不能说“速度越强”。"}, {"text": "音量", "is_correct": false, "explanation": "语义：“音量”指声音的大小，学习没有音量。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的高矮，与学习的程度无关。"}], "explanations": {"动机": "正确答案。句子说的是推动学习的内在原因，正是动机。", "速度": "搭配：“速度”通常说快慢，不能说“速度越强”。", "音量": "语义：“音量”指声音的大小，学习没有音量。", "身高": "体貌：“身高”指人的高矮，与学习的程度无关。"}, "sentence_index": 0, "correct_answer": "动机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的动机很开朗，大家都喜欢和他聊天。", "explanation": "这里应该用〈性格〉。“动机”指推动人做事的原因或目的，不能用来形容开朗的性格。"}, {"text": "这个方法的动机很强，很多人都能学会。", "explanation": "这里应该用〈效果〉。“动机”只用于人，方法没有内在想法，说方法好不好要用“效果”。"}, {"text": "他的动机又重了五公斤。", "explanation": "动机是抽象的想法，没有重量，不能用“重”和公斤来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93888, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "动机", "is_correct": true, "explanation": "正确答案。动机指推动人去做事的内在原因或目的。"}, {"text": "投机", "is_correct": false, "explanation": "投机读 tóu jī：tóu 的声母、韵母和声调都与 dòng 不同；意思是利用机会谋取私利。"}, {"text": "动词", "is_correct": false, "explanation": "动词读 dòng cí：第二音节 cí 与 jī 的声母、声调都不同；意思是表示动作的词。"}, {"text": "冻结", "is_correct": false, "explanation": "冻结读 dòng jié：第二音节是 jié（第二声，韵母 ie），与 jī 不同；意思是结冰或停止变动。"}], "explanations": {"动机": "正确答案。动机指推动人去做事的内在原因或目的。", "投机": "投机读 tóu jī：tóu 的声母、韵母和声调都与 dòng 不同；意思是利用机会谋取私利。", "动词": "动词读 dòng cí：第二音节 cí 与 jī 的声母、声调都不同；意思是表示动作的词。", "冻结": "冻结读 dòng jié：第二音节是 jié（第二声，韵母 ie），与 jī 不同；意思是结冰或停止变动。"}, "sentence_index": null, "correct_answer": "动机"}, "level_3": {"options": [{"text": "动机", "is_correct": true, "explanation": "正确答案。句子说的是他很强的内在想法，正是动机。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指性情，不能说“成功脾气”。"}, {"text": "长相", "is_correct": false, "explanation": "体貌：“长相”指外貌，成功不能用长相来说。"}, {"text": "重量", "is_correct": false, "explanation": "语义：“重量”指物体的轻重，人的成功没有重量。"}], "explanations": {"动机": "正确答案。句子说的是他很强的内在想法，正是动机。", "脾气": "语义：“脾气”指性情，不能说“成功脾气”。", "长相": "体貌：“长相”指外貌，成功不能用长相来说。", "重量": "语义：“重量”指物体的轻重，人的成功没有重量。"}, "sentence_index": 6, "correct_answer": "动机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次事故的动机是路面湿滑。", "explanation": "这里应该用〈原因〉。动机是人做事时的内在想法，路面湿滑是客观原因。"}, {"text": "他一口气把动机喝光了。", "explanation": "动机是抽象的想法，不能被喝掉，“喝光”只能用于饮料等东西。"}, {"text": "他躲在动机后面，不肯出来。", "explanation": "动机是心里的想法，不是可以躲藏的场所，这里把它当作了地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid