INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93888, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他心里有一只很强的学习动机。", "corrected_sentence": "他心里有一种很强的学习动机。", "error_description": "量词错误：“动机”应搭配量词“种”，不能用“只”（“只”用于动物或单个的小东西）。正确说法是“一种很强的学习动机”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93888, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对学习有一种很强动机。", "corrected_sentence": "他对学习有一种很强的动机。", "error_description": "定语遗漏：“很强”修饰名词“动机”时要加“的”，应说“一种很强的动机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
