INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93891, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "包围是从四面八方把一个地方围住。", "primary_collocate": null, "pronunciation": "bāo wéi", "ipa": "pɑʊ⁵⁵ weɪ³⁵", "syllable_count": 2, "sentences": [{"text": "军队从四面八方包围了这座城。", "target_word": "包围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察包围了银行，小偷出不来。", "target_word": "包围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家从东西南北包围了广场。", "target_word": "包围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察包围了整个院子，不让人出入。", "target_word": "包围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人包围了山上的村子。", "target_word": "包围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们悄悄包围了小山洞。", "target_word": "包围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵从各个方向包围了机场。", "target_word": "包围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警车包围了那栋楼。", "target_word": "包围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消防队员从四面八方包围了着火的仓库。", "target_word": "包围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵从四面包围了这个小岛。", "target_word": "包围", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "包围了", "label": "体标"}, {"form": "包围着", "label": "体标"}], "register": "中性", "sense_fingerprint": "从各个方向把一个地方围住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'add8433b-3ae1-4b98-b82a-1589f89692b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93891, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "包围", "is_correct": true, "explanation": "“包围”指从各个方向把城围住，与“从四面八方”的语境一致。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”的对象是食物，不能用于城市。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能以城市为宾语。"}, {"text": "煎", "is_correct": false, "explanation": "语义：“煎”是烹饪方式，与“城”无法搭配。"}], "explanations": {"包围": "“包围”指从各个方向把城围住，与“从四面八方”的语境一致。", "烤": "语义：“烤”的对象是食物，不能用于城市。", "唱": "搭配：“唱”不能以城市为宾语。", "煎": "语义：“煎”是烹饪方式，与“城”无法搭配。"}, "sentence_index": 0, "correct_answer": "包围"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师包围了他的错误。", "explanation": "这里应该用〈包容〉。包围指从四周围住，宽容地对待别人的错误要说“包容”。"}, {"text": "这家公司包围了三个部门。", "explanation": "这里应该用〈包括〉。说某个组织下辖哪些部门要用“包括”，包围不能这样用。"}, {"text": "医生包围了他的腿。", "explanation": "这里应该用〈包扎〉。给腿缠绷带要说“包扎”，包围是把人或地方围住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03ca8cc9-def1-468f-84ca-354c45e0488b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93891, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "包围", "is_correct": true, "explanation": "“包围”指从各个方向把机场围住，与句意一致。"}, {"text": "织", "is_correct": false, "explanation": "语义：“织”指编织布料或网，不能用于机场。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”的对象是可以擦拭的表面，机场不能被擦。"}, {"text": "编", "is_correct": false, "explanation": "搭配：“编”需要以布、绳等为对象，不能说“编机场”。"}], "explanations": {"包围": "“包围”指从各个方向把机场围住，与句意一致。", "织": "语义：“织”指编织布料或网，不能用于机场。", "擦": "语义：“擦”的对象是可以擦拭的表面，机场不能被擦。", "编": "搭配：“编”需要以布、绳等为对象，不能说“编机场”。"}, "sentence_index": 6, "correct_answer": "包围"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些家务我都包围了。", "explanation": "这里应该用〈包办〉。包围指从四面把人或地方围住，承担全部事务要说“包办”，不能用包围。"}, {"text": "这篇文章包围了很多观点。", "explanation": "这里应该用〈包含〉。文章里收录观点要说“包含”，包围不能指内容的收录。"}, {"text": "这盒点心包围得很精致。", "explanation": "这里应该用〈包装〉。给点心做外包装要说“包装”，包围是围住，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03ca8cc9-def1-468f-84ca-354c45e0488b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93891, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "消防员把那片森林包围下来了。", "corrected_sentence": "消防员把那片森林包围起来了。", "error_description": "错误在补语：“包围”后的趋向补语应用“起来”，不能用“下来”，应说“包围起来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03ca8cc9-def1-468f-84ca-354c45e0488b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93891, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "敌人从三面包围着了那个村庄。", "corrected_sentence": "敌人从三面包围了那个村庄。", "error_description": "错误在体标：“包围着”表示持续，后面不能再接“了”；表示完成只用“包围了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03ca8cc9-def1-468f-84ca-354c45e0488b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93893, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "实名", "is_correct": true, "explanation": "反义：“实名”指使用真实姓名，与“匿名”正好相反。"}, {"text": "热烈", "is_correct": false, "explanation": "“热烈”形容情绪高涨，与“匿名”的意思无关。"}, {"text": "和蔼", "is_correct": false, "explanation": "“和蔼”形容态度亲切，与“匿名”没有反义或近义关系。"}, {"text": "迅速", "is_correct": false, "explanation": "“迅速”形容速度，与“匿名”没有反义或近义关系。"}], "correct_answer": "实名", "explanations": {"实名": "反义：“实名”指使用真实姓名，与“匿名”正好相反。", "热烈": "“热烈”形容情绪高涨，与“匿名”的意思无关。", "和蔼": "“和蔼”形容态度亲切，与“匿名”没有反义或近义关系。", "迅速": "“迅速”形容速度，与“匿名”没有反义或近义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93893, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "实名", "is_correct": true, "explanation": "反义：“实名”指使用真实姓名，与“匿名”正好相反。"}, {"text": "热情", "is_correct": false, "explanation": "“热情”形容待人的态度，与“匿名”没有反义或近义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线或颜色，与“匿名”的意思无关。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容明白、分明，与“匿名”没有反义或近义关系。"}], "correct_answer": "实名", "explanations": {"实名": "反义：“实名”指使用真实姓名，与“匿名”正好相反。", "热情": "“热情”形容待人的态度，与“匿名”没有反义或近义关系。", "明亮": "“明亮”形容光线或颜色，与“匿名”的意思无关。", "清楚": "“清楚”形容明白、分明，与“匿名”没有反义或近义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93893, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "匿名是不写自己的名字，别人不知道你是谁。", "primary_collocate": null, "pronunciation": "nì míng", "ipa": "ni⁵¹ miŋ³⁵", "syllable_count": 2, "sentences": [{"text": "她在网上匿名留言，没人知道她是谁。", "target_word": "匿名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以匿名回答，不用写名字。", "target_word": "匿名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他匿名给我发了一条短信。", "target_word": "匿名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个账号是匿名的，我不知道主人是谁。", "target_word": "匿名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "匿名的话，大家更敢说真话。", "target_word": "匿名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想匿名问老师一个问题。", "target_word": "匿名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢匿名批评别人。", "target_word": "匿名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个匿名电话让妈妈很担心。", "target_word": "匿名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生可以匿名评价老师。", "target_word": "匿名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为什么你要匿名送我这份礼物？", "target_word": "匿名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "匿名信", "label": "复合"}, {"form": "匿名者", "label": "复合"}], "register": "中性", "sense_fingerprint": "匿名：不写名字，别人不知道你是谁", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2b1155c-50b9-4349-992a-4c2e6592e873') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93893, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "匿名", "is_correct": true, "explanation": "正确：“匿名留言”指不留真实姓名地留言，与“没人知道她是谁”一致。"}, {"text": "实名", "is_correct": false, "explanation": "语义：“实名”表示用真实姓名，与“没人知道她是谁”矛盾。"}, {"text": "具名", "is_correct": false, "explanation": "语义：“具名”指署上姓名，同样会让人知道她是谁，与句意矛盾。"}, {"text": "亲笔", "is_correct": false, "explanation": "搭配：“亲笔”指手写，与“在网上”留言的方式不合。"}], "explanations": {"匿名": "正确：“匿名留言”指不留真实姓名地留言，与“没人知道她是谁”一致。", "实名": "语义：“实名”表示用真实姓名，与“没人知道她是谁”矛盾。", "具名": "语义：“具名”指署上姓名，同样会让人知道她是谁，与句意矛盾。", "亲笔": "搭配：“亲笔”指手写，与“在网上”留言的方式不合。"}, "sentence_index": 0, "correct_answer": "匿名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是一个匿名村庄，地图上找不到。", "explanation": "这里应该用〈无名〉。“无名村庄”指没有名字、不见于地图的村子；“匿名”只用于不署名的人或作品，村庄不能匿名。"}, {"text": "这位歌手在演唱会上公开了身份，却仍然是匿名的。", "explanation": "这里应该用〈实名〉。歌手已公开身份，属于“实名”的情况，不能说“匿名”。"}, {"text": "他的邮件末尾签着全名，这封邮件却是匿名的。", "explanation": "这里应该用〈署名〉。邮件末尾签着全名，属于“署名”，寄件人已公开身份，不能说这封邮件是匿名的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93893, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "匿名", "is_correct": true, "explanation": "正确：“不喜欢匿名批评”指不署名地批评，与句意一致。"}, {"text": "隆重", "is_correct": false, "explanation": "搭配：“隆重”形容仪式、场面，不修饰“批评”。"}, {"text": "沉默", "is_correct": false, "explanation": "语义：“沉默”指不出声，与“批评”需要说出来的意思矛盾。"}, {"text": "盛大", "is_correct": false, "explanation": "搭配：“盛大”形容活动、场面，不用来修饰“批评”。"}], "explanations": {"匿名": "正确：“不喜欢匿名批评”指不署名地批评，与句意一致。", "隆重": "搭配：“隆重”形容仪式、场面，不修饰“批评”。", "沉默": "语义：“沉默”指不出声，与“批评”需要说出来的意思矛盾。", "盛大": "搭配：“盛大”形容活动、场面，不用来修饰“批评”。"}, "sentence_index": 6, "correct_answer": "匿名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "收快递时要在单子上匿名。", "explanation": "这里应该用〈签名〉。签收单要求本人写下名字，“匿名”表示不写名字，与此相反。"}, {"text": "这本留言册上要匿名，大家才能知道是谁来过。", "explanation": "这里应该用〈留名〉。留言册要求写下名字，“匿名”表示不留名字，与要求相反。"}, {"text": "进入考场前，考生要出示匿名证件。", "explanation": "这里应该用〈实名〉。考场要求出示实名证件，“匿名”表示不写真实身份，不能说“匿名证件”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93893, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在论坛上很匿名提了一个建议。", "corrected_sentence": "他在论坛上匿名提了一个建议。", "error_description": "错误：“很匿名提”；正确：“匿名提”。“匿名”表示不署名，是非程度性的属性，不能用程度副词“很”修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93893, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他匿名的发了一条消息。", "corrected_sentence": "他匿名地发了一条消息。", "error_description": "错误：“匿名的发”；正确：“匿名地发”。修饰动词的状语要用“地”，“的”用于修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93894, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "实名", "is_correct": true, "explanation": "反义：“实名”指使用真实姓名，与“匿名”正好相反。"}, {"text": "热烈", "is_correct": false, "explanation": "“热烈”形容情绪高涨，与“匿名”的意思无关。"}, {"text": "和蔼", "is_correct": false, "explanation": "“和蔼”形容态度亲切，与“匿名”没有反义或近义关系。"}, {"text": "迅速", "is_correct": false, "explanation": "“迅速”形容速度，与“匿名”没有反义或近义关系。"}], "correct_answer": "实名", "explanations": {"实名": "反义：“实名”指使用真实姓名，与“匿名”正好相反。", "热烈": "“热烈”形容情绪高涨，与“匿名”的意思无关。", "和蔼": "“和蔼”形容态度亲切，与“匿名”没有反义或近义关系。", "迅速": "“迅速”形容速度，与“匿名”没有反义或近义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93894, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "实名", "is_correct": true, "explanation": "反义：“实名”指使用真实姓名，与“匿名”正好相反。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容明白、分明，与“匿名”没有反义或近义关系。"}, {"text": "勤劳", "is_correct": false, "explanation": "“勤劳”形容做事用心、不怕辛苦，与“匿名”没有反义或近义关系。"}, {"text": "陈旧", "is_correct": false, "explanation": "“陈旧”形容过时、不新鲜，与“匿名”没有反义或近义关系。"}], "correct_answer": "实名", "explanations": {"实名": "反义：“实名”指使用真实姓名，与“匿名”正好相反。", "清楚": "“清楚”形容明白、分明，与“匿名”没有反义或近义关系。", "勤劳": "“勤劳”形容做事用心、不怕辛苦，与“匿名”没有反义或近义关系。", "陈旧": "“陈旧”形容过时、不新鲜，与“匿名”没有反义或近义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93894, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不具名；不署真实姓名。", "primary_collocate": null, "pronunciation": "nì míng", "ipa": "ni⁵¹ miŋ³⁵", "syllable_count": 2, "sentences": [{"text": "他收到一封匿名信。", "target_word": "匿名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次投票是匿名的。", "target_word": "匿名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人匿名给学校捐了一笔钱。", "target_word": "匿名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上可以匿名发表意见。", "target_word": "匿名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你匿名填写这份问卷。", "target_word": "匿名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不想露面，所以匿名参加了比赛。", "target_word": "匿名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这个调查是匿名的，不用写名字。", "target_word": "匿名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位匿名的好心人帮了我们很多。", "target_word": "匿名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用匿名的方式给报社写了一封信。", "target_word": "匿名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司设了匿名意见箱。", "target_word": "匿名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "匿名信", "label": "复合"}, {"form": "匿名者", "label": "复合"}], "register": "中性", "sense_fingerprint": "匿名：不署真实姓名", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2b1155c-50b9-4349-992a-4c2e6592e873') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93894, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "匿名", "is_correct": true, "explanation": "正确：“匿名信”指不写寄信人姓名的信。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不修饰“信”，不说“清脆信”。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的智力，信件不能是聪明的。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的身材，不用来形容信。"}], "explanations": {"匿名": "正确：“匿名信”指不写寄信人姓名的信。", "清脆": "搭配：“清脆”形容声音，不修饰“信”，不说“清脆信”。", "聪明": "语义：“聪明”形容人的智力，信件不能是聪明的。", "高大": "体貌：“高大”形容人或物的身材，不用来形容信。"}, "sentence_index": 0, "correct_answer": "匿名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "收银员请客人在收据上匿名。", "explanation": "这里应该用〈签名〉。收据要求本人写下名字，“匿名”是不写名字，与此相反。"}, {"text": "这是一座匿名的小山，很少有人知道。", "explanation": "这里应该用〈无名〉。“无名小山”指没有名字的小山；“匿名”只用于不署名的人或作品，山不能匿名。"}, {"text": "这幅画右下角签着他的名字，却被标为匿名作品。", "explanation": "这里应该用〈署名〉。画上已签着他的名字，即属于“署名”，不能标为“匿名作品”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93894, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "匿名", "is_correct": true, "explanation": "正确：“匿名的调查”指不用写名字的调查，与“不用写名字”一致。"}, {"text": "具名", "is_correct": false, "explanation": "语义：“具名”指署上姓名，与“不用写名字”矛盾。"}, {"text": "记名", "is_correct": false, "explanation": "语义：“记名”指记下姓名，与“不用写名字”矛盾。"}, {"text": "高深", "is_correct": false, "explanation": "搭配：“高深”形容学问、道理，不用来形容调查。"}], "explanations": {"匿名": "正确：“匿名的调查”指不用写名字的调查，与“不用写名字”一致。", "具名": "语义：“具名”指署上姓名，与“不用写名字”矛盾。", "记名": "语义：“记名”指记下姓名，与“不用写名字”矛盾。", "高深": "搭配：“高深”形容学问、道理，不用来形容调查。"}, "sentence_index": 6, "correct_answer": "匿名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份申请表的匿名栏要求写上真实姓名。", "explanation": "这里应该用〈署名〉。表格的署名栏要求写真实姓名，“匿名”表示不写姓名，两者矛盾。"}, {"text": "这份合同要求双方匿名，才能生效。", "explanation": "这里应该用〈具名〉。合同要求双方具名，“匿名”表示不具名，与要求相反。"}, {"text": "公司的会议记录上写着每位发言人和记录人的全名，这份记录却是匿名的。", "explanation": "这里应该用〈署名〉。记录上已写明发言人和记录人的全名，属于“署名”，不能说这份记录是匿名的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93894, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次调查是很匿名的，大家可以放心回答。", "corrected_sentence": "这次调查是匿名的，大家可以放心回答。", "error_description": "错误：“很匿名”；正确：“匿名的”。“匿名”表示不署名，是非程度性的属性，不能用程度副词“很”修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93894, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他匿名的寄来了一封信。", "corrected_sentence": "他匿名地寄来了一封信。", "error_description": "错误：“匿名的寄来”；正确：“匿名地寄来”。修饰动词的状语要用“地”，“的”用于修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
