INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93896, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "不得不；只能。", "primary_collocate": null, "pronunciation": "zhǐ hǎo", "ipa": "ʈʂɻ̩˨˩˦ xɑʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "钱不够，我只好不买那件衣服了。", "target_word": "只好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电梯坏了，他只好爬楼梯上去。", "target_word": "只好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友不在家，我只好把东西放在门口。", "target_word": "只好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨太大了，比赛只好改到下周。", "target_word": "只好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没带伞，只好等雨小一点再走。", "target_word": "只好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病了，只好请假在家休息。", "target_word": "只好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没人帮忙，我们只好自己动手做。", "target_word": "只好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图看不懂，我只好问路边的人。", "target_word": "只好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药店都关了，妈妈只好给他喝热水。", "target_word": "只好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有大桌子，大家只好坐在地上吃饭。", "target_word": "只好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "不得不；只能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43035244-64f2-4d65-bc07-110cd48c7371') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93896, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "只好", "is_correct": true, "explanation": "正确：“只好”表示不得不，因为钱不够所以只能不买，与句意相合。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：“偏偏”表示故意与预期相反，与“钱不够”导致的不买不合。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”不能修饰否定动作“不买”，它是程度副词，修饰的是形容词。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然出现，与“钱不够”造成的必然结果不合。"}], "explanations": {"只好": "正确：“只好”表示不得不，因为钱不够所以只能不买，与句意相合。", "偏偏": "语义：“偏偏”表示故意与预期相反，与“钱不够”导致的不买不合。", "非常": "搭配：“非常”不能修饰否定动作“不买”，它是程度副词，修饰的是形容词。", "忽然": "语义：“忽然”表示突然出现，与“钱不够”造成的必然结果不合。"}, "sentence_index": 0, "correct_answer": "只好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次旅行很顺利，我们只好多玩了两天。", "explanation": "这里应该用〈索性〉。“只好”表示迫于无奈，旅行顺利而多玩两天应用“索性”表示顺势而为。"}, {"text": "我们是为了健身才去跑步的，只好开心地跑了一圈。", "explanation": "这里应该用〈特意〉。“只好”表示迫于无奈，为了健身而跑步是主动选择，应用“特意”表示专门如此。"}, {"text": "我家离超市很近，只好每天走路去买菜。", "explanation": "这里应该用〈就〉。“只好”表示迫于无奈，离超市近是步行的便利，应用“就”表示自然如此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c08b9c-b1af-4e17-92b2-5465fba6be22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93896, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "只好", "is_correct": true, "explanation": "正确：“只好”表示没人帮忙，别无选择，只能自己动手，与句意相合。"}, {"text": "特意", "is_correct": false, "explanation": "语义：“特意”表示专门去做，与“没人帮忙”的被迫情况相反。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”是程度副词，不能直接修饰“动手做”这样的动作。"}, {"text": "千万", "is_correct": false, "explanation": "语法：“千万”用于劝告或命令，常与“要/别”连用，不能用于叙述已有的情况。"}], "explanations": {"只好": "正确：“只好”表示没人帮忙，别无选择，只能自己动手，与句意相合。", "特意": "语义：“特意”表示专门去做，与“没人帮忙”的被迫情况相反。", "很": "搭配：“很”是程度副词，不能直接修饰“动手做”这样的动作。", "千万": "语法：“千万”用于劝告或命令，常与“要/别”连用，不能用于叙述已有的情况。"}, "sentence_index": 6, "correct_answer": "只好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家很喜欢这种吃饭方式，只好坐在地上吃饭。", "explanation": "这里应该用〈乐于〉。“只好”表示迫于条件而勉强，大家很喜欢时应用“乐于”表示主动。"}, {"text": "桌子很大，我只好请大家一起坐过来。", "explanation": "这里应该用〈正好〉。“只好”表示迫于无奈，桌子够大正是能坐下的条件，应用“正好”表示恰当。"}, {"text": "他很喜欢爬山，只好每个周末都去爬山。", "explanation": "这里应该用〈总是〉。“只好”表示迫于无奈，喜欢爬山而每周去爬属于自愿，应用“总是”表示一贯如此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c08b9c-b1af-4e17-92b2-5465fba6be22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93896, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车坏了，他只好要走路去上班。", "corrected_sentence": "车坏了，他只好走路去上班。", "error_description": "错误在“只好要”。“只好”已表示不得不，后面不能再加“要”；应删去“要”，正确为“车坏了，他只好走路去上班”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c08b9c-b1af-4e17-92b2-5465fba6be22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93896, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "修车厂没开门，他只好着自己修车。", "corrected_sentence": "修车厂没开门，他只好自己修车。", "error_description": "错误在“只好着”。“着”表示状态的持续，不能紧跟副词“只好”；正确为“修车厂没开门，他只好自己修车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67c08b9c-b1af-4e17-92b2-5465fba6be22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
