INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93897, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "各界是社会上各个不同的行业和各种各样的人。", "primary_collocate": null, "pronunciation": "gè jiè", "ipa": "kɤ˥˩ tɕjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "各界朋友都来参加这次活动。", "target_word": "各界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来自各界的专家一起讨论城市的发展。", "target_word": "各界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人得到了各界的关照。", "target_word": "各界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震后，各界都送来了衣服和食物。", "target_word": "各界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上说，各界对新办法看法不同。", "target_word": "各界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来参加开业典礼的有各界朋友。", "target_word": "各界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各界的关心让他很感动。", "target_word": "各界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们邀请了各界的代表来学校。", "target_word": "各界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛得到了各界的支持。", "target_word": "各界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各界都很关注这件事。", "target_word": "各界", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "各界人士", "label": "复合"}, {"form": "社会各界", "label": "复合"}], "register": "书面", "sense_fingerprint": "社会上各个行业和各种各样的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1ebf27a-bc60-422b-bfea-fa9b711a051c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93897, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大厅", "is_correct": false, "explanation": "语义：「大厅」是地点名词，不能指人，「大厅朋友」句意不通。"}, {"text": "各界", "is_correct": true, "explanation": "各界：社会上各个行业和各种各样的人，修饰「朋友」恰当，指来自各界的朋友。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：「厨房」是处所名词，不能指人，「厨房朋友」句意不通。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：「窗户」不能与「朋友」搭配作定语，句意不通。"}], "explanations": {"大厅": "语义：「大厅」是地点名词，不能指人，「大厅朋友」句意不通。", "各界": "各界：社会上各个行业和各种各样的人，修饰「朋友」恰当，指来自各界的朋友。", "厨房": "语义：「厨房」是处所名词，不能指人，「厨房朋友」句意不通。", "窗户": "搭配：「窗户」不能与「朋友」搭配作定语，句意不通。"}, "sentence_index": 0, "correct_answer": "各界"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种花在各界都能看到。", "explanation": "这里应该用〈各地〉。各界指社会上各行业和各种人群，不用于指地区，此处应用〈各地〉。"}, {"text": "超市里有各界水果。", "explanation": "这里应该用〈各类〉。各界只指行业和人群，不能用于修饰水果等事物，此处应用〈各类〉。"}, {"text": "教室里各界角落都很干净。", "explanation": "这里应该用〈各个〉。各界指不同行业和人群，不能用来修饰「角落」这类处所，此处应用〈各个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93897, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食堂", "is_correct": false, "explanation": "语义：「食堂」是处所名词，不能发出「关心」，句意不通。"}, {"text": "各界", "is_correct": true, "explanation": "各界：社会上各个行业和各种各样的人，作定语修饰「关心」，表示来自各界的关心。"}, {"text": "教室", "is_correct": false, "explanation": "语义：「教室」是处所名词，不能发出「关心」，句意不通。"}, {"text": "地毯", "is_correct": false, "explanation": "搭配：「关心」的定语应是人，「地毯」无法与「的关心」搭配，句意不通。"}], "explanations": {"食堂": "语义：「食堂」是处所名词，不能发出「关心」，句意不通。", "各界": "各界：社会上各个行业和各种各样的人，作定语修饰「关心」，表示来自各界的关心。", "教室": "语义：「教室」是处所名词，不能发出「关心」，句意不通。", "地毯": "搭配：「关心」的定语应是人，「地毯」无法与「的关心」搭配，句意不通。"}, "sentence_index": 6, "correct_answer": "各界"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "各界元首都出席了这次峰会。", "explanation": "这里应该用〈各国〉。各界指社会上各行业和各种人群，不能用来修饰「元首」这类国家层面的人员，此处应用〈各国〉。"}, {"text": "各界政府都发布了这项通知。", "explanation": "这里应该用〈各级〉。各界指社会上各行业和各种人群，不能修饰「政府」这类机构，此处应用〈各级〉。"}, {"text": "这本书的各界章节都很有意思。", "explanation": "这里应该用〈各个〉。各界指社会上各行业和各种人群，不能修饰「章节」，此处应用〈各个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93897, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很多人从各界来到了这个城市。", "corrected_sentence": "很多人从各地来到了这个城市。", "error_description": "错误形式：「从各界来到」。正确形式：「从各地来到」。「各界」指社会上各行业和各种人群，不表示地方，表示来自不同地方应用「各地」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93897, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "暑假我们去了各界旅行。", "corrected_sentence": "暑假我们去了各地旅行。", "error_description": "错误形式：「去了各界旅行」。正确形式：「去了各地旅行」。「各界」指社会上各行业和各种人群，不能表示旅行的地点，应用「各地」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba92b63e-3c3d-4369-9e27-8e73b2d48dd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
