INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93899, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "命名是给一个新东西起一个名字。", "primary_collocate": null, "pronunciation": "mìng míng", "ipa": "miŋ⁵¹ miŋ³⁵", "syllable_count": 2, "sentences": [{"text": "新手机还没有命名。", "target_word": "命名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种新茶怎么命名好呢？", "target_word": "命名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们给新机器命名为“小飞”。", "target_word": "命名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们给小组命名。", "target_word": "命名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "命名这件事，我们想了一个星期。", "target_word": "命名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢给自己画的画命名。", "target_word": "命名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司用颜色给新车命名。", "target_word": "命名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个新词的命名很有意思。", "target_word": "命名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把新养的鱼命名为“小金”。", "target_word": "命名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们正在给新来的小狗命名。", "target_word": "命名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "命名了", "label": "体标"}, {"form": "命名过", "label": "体标"}], "register": "中性", "sense_fingerprint": "命名：给新东西起一个名字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2b1155c-50b9-4349-992a-4c2e6592e873') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93899, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "命名", "is_correct": true, "explanation": "正确答案：命名（mìng míng），给新东西起一个名字。"}, {"text": "明明", "is_correct": false, "explanation": "首音节 míng（第二声）与 mìng（第四声）声调不同，意思是“显然”。"}, {"text": "姓名", "is_correct": false, "explanation": "首音节 xìng 与 mìng 声母不同（x 与 m），声调相同，意思是“一个人的姓和名字”。"}, {"text": "病名", "is_correct": false, "explanation": "首音节 bìng 与 mìng 声母不同（b 与 m），意思是“疾病的名称”。"}], "explanations": {"命名": "正确答案：命名（mìng míng），给新东西起一个名字。", "明明": "首音节 míng（第二声）与 mìng（第四声）声调不同，意思是“显然”。", "姓名": "首音节 xìng 与 mìng 声母不同（x 与 m），声调相同，意思是“一个人的姓和名字”。", "病名": "首音节 bìng 与 mìng 声母不同（b 与 m），意思是“疾病的名称”。"}, "sentence_index": null, "correct_answer": "命名"}, "level_3": {"options": [{"text": "命名", "is_correct": true, "explanation": "正确：“命名”指给新手机起名字，与“还没有”搭配。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”是转换语言，手机不能被翻译。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：“种植”的对象是植物，不能用于手机。"}, {"text": "讲解", "is_correct": false, "explanation": "语义：“讲解”是讲明道理，手机不是讲解的对象。"}], "explanations": {"命名": "正确：“命名”指给新手机起名字，与“还没有”搭配。", "翻译": "语义：“翻译”是转换语言，手机不能被翻译。", "种植": "搭配：“种植”的对象是植物，不能用于手机。", "讲解": "语义：“讲解”是讲明道理，手机不是讲解的对象。"}, "sentence_index": 0, "correct_answer": "命名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天命名八个小时。", "explanation": "这里应该用〈睡〉。命名表示给一个新东西起名字，不能表示睡觉的时长。"}, {"text": "她一箭命名了靶心。", "explanation": "这里应该用〈命中〉。命名表示给一个新东西起名字，不能表示箭射中目标。"}, {"text": "老师命名我们分组。", "explanation": "这里应该用〈安排〉。命名只表示起名字，不表示分配或安排分组。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93899, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "命名", "is_correct": true, "explanation": "正确：“命名”指给新车起名字，与“公司用颜色”的语境相符。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”是修复损坏，与用颜色给新车搭配不通。"}, {"text": "清洗", "is_correct": false, "explanation": "搭配：“清洗”的对象是脏物，不能说“用颜色清洗新车”。"}, {"text": "检测", "is_correct": false, "explanation": "语义：“检测”是检验性能，与“用颜色”的做法不相符。"}], "explanations": {"命名": "正确：“命名”指给新车起名字，与“公司用颜色”的语境相符。", "修理": "语义：“修理”是修复损坏，与用颜色给新车搭配不通。", "清洗": "搭配：“清洗”的对象是脏物，不能说“用颜色清洗新车”。", "检测": "语义：“检测”是检验性能，与“用颜色”的做法不相符。"}, "sentence_index": 6, "correct_answer": "命名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我命名了他的名字。", "explanation": "这里应该用〈忘记〉。命名表示给一个新东西起名字，不能表示忘掉某个名字。"}, {"text": "他命名了三公里。", "explanation": "这里应该用〈跑〉。命名表示给一个新东西起名字，不能表示跑步的距离。"}, {"text": "他命名了手。", "explanation": "这里应该用〈举〉。命名表示给一个新东西起名字，不能表示举起的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93899, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们一起给这只新养的兔子了命名吧。", "corrected_sentence": "我们一起给这只新养的兔子命名吧。", "error_description": "错误：“了”放在动词“命名”前；正确：“命名吧”。“了”是动词后的完成标记，不能放在动词之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93899, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们已经给这只小猫命名着。", "corrected_sentence": "他们已经给这只小猫命名了。", "error_description": "错误：“命名着”；正确：“命名了”。“已经”表示动作已完成，“着”表示动作持续，两者冲突。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
