INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93900, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "给人或事物起名字。", "primary_collocate": null, "pronunciation": "mìng míng", "ipa": "miŋ⁵¹ miŋ³⁵", "syllable_count": 2, "sentences": [{"text": "这座桥是用他的名字命名的。", "target_word": "命名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家把新发现的星星命名为“希望”。", "target_word": "命名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母还没有给孩子命名。", "target_word": "命名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街以一位老师的名字命名。", "target_word": "命名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你给这只小猫命名吧。", "target_word": "命名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花是谁命名的？", "target_word": "命名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要给新产品命名。", "target_word": "命名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校用她的名字命名了图书馆。", "target_word": "命名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给自己的店命名为“小林面馆”。", "target_word": "命名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家把这条河命名为“长安河”。", "target_word": "命名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "命名了", "label": "体标"}, {"form": "命名过", "label": "体标"}], "register": "中性", "sense_fingerprint": "命名：给人或事物起名字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2b1155c-50b9-4349-992a-4c2e6592e873') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93900, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "命名", "is_correct": true, "explanation": "正确答案：命名（mìng míng），给人或事物起名字。"}, {"text": "明明", "is_correct": false, "explanation": "首音节 míng（第二声）与 mìng（第四声）声调不同，意思是“显然”。"}, {"text": "姓名", "is_correct": false, "explanation": "首音节 xìng 与 mìng 声母不同（x 与 m），声调相同，意思是“一个人的姓和名字”。"}, {"text": "病名", "is_correct": false, "explanation": "首音节 bìng 与 mìng 声母不同（b 与 m），意思是“疾病的名称”。"}], "explanations": {"命名": "正确答案：命名（mìng míng），给人或事物起名字。", "明明": "首音节 míng（第二声）与 mìng（第四声）声调不同，意思是“显然”。", "姓名": "首音节 xìng 与 mìng 声母不同（x 与 m），声调相同，意思是“一个人的姓和名字”。", "病名": "首音节 bìng 与 mìng 声母不同（b 与 m），意思是“疾病的名称”。"}, "sentence_index": null, "correct_answer": "命名"}, "level_3": {"options": [{"text": "命名", "is_correct": true, "explanation": "正确：“命名”指给这座桥起名字，与“用他的名字”相符。"}, {"text": "设计", "is_correct": false, "explanation": "语义：“设计”是规划图样，不能说“用他的名字设计”。"}, {"text": "修建", "is_correct": false, "explanation": "搭配：“修建”的对象是工程，不能把“名字”当作修建的方式。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“参观”是去看，与“用他的名字”做事不相通。"}], "explanations": {"命名": "正确：“命名”指给这座桥起名字，与“用他的名字”相符。", "设计": "语义：“设计”是规划图样，不能说“用他的名字设计”。", "修建": "搭配：“修建”的对象是工程，不能把“名字”当作修建的方式。", "参观": "语义：“参观”是去看，与“用他的名字”做事不相通。"}, "sentence_index": 0, "correct_answer": "命名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察命名大家离开现场。", "explanation": "这里应该用〈命令〉。命名指给人或事物起名字，不能表示发出命令让人离开。"}, {"text": "他一箭命名了靶心。", "explanation": "这里应该用〈命中〉。命名指给人或事物起名字，不能表示箭射中目标。"}, {"text": "老师命名我当班长。", "explanation": "这里应该用〈指定〉。命名只是起名字，不表示指定或任命职务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93900, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "命名", "is_correct": true, "explanation": "正确：“命名”指给新产品起名字，与“公司要给新产品”相符。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是烹饪，用于食物，不能用于新产品。"}, {"text": "熨", "is_correct": false, "explanation": "语义：“熨”是用熨斗烫平衣物，与新产品不相配。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：“种植”的对象是植物或作物，不能用于新产品。"}], "explanations": {"命名": "正确：“命名”指给新产品起名字，与“公司要给新产品”相符。", "煮": "语义：“煮”是烹饪，用于食物，不能用于新产品。", "熨": "语义：“熨”是用熨斗烫平衣物，与新产品不相配。", "种植": "搭配：“种植”的对象是植物或作物，不能用于新产品。"}, "sentence_index": 6, "correct_answer": "命名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上命名了三公里。", "explanation": "这里应该用〈跑〉。命名指给人或事物起名字，不能表示跑步的距离。"}, {"text": "他命名得很开心。", "explanation": "这里应该用〈笑〉。命名表示给人或事物起名字，不能表示笑的动作。"}, {"text": "大家命名他的字写得好。", "explanation": "这里应该用〈称赞〉。命名只表示起名字，不能用来评价字写得好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93900, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校把这栋楼命名了“校长楼”。", "corrected_sentence": "学校把这栋楼命名为“校长楼”。", "error_description": "错误：“命名了”；正确：“命名为”。“命名”后引出新名字要用“为”，不能用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93900, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个社区打算给新公园命名过。", "corrected_sentence": "这个社区打算给新公园命名。", "error_description": "错误：“命名过”；正确：“命名”。“打算”表示将来，不能与表示已经经历的“过”搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cd41965-6d0e-48c7-b7d3-b95226648123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93901, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "获得", "is_correct": true, "explanation": "获得与丧失是反义词，指得到原来没有的东西，与丧失相对。"}, {"text": "购买", "is_correct": false, "explanation": "购买是付钱取得商品，与丧失没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步是走路休闲，与丧失没有反义关系。"}, {"text": "演奏", "is_correct": false, "explanation": "演奏是表演乐器或乐曲，与丧失没有反义关系。"}], "correct_answer": "获得", "explanations": {"获得": "获得与丧失是反义词，指得到原来没有的东西，与丧失相对。", "购买": "购买是付钱取得商品，与丧失没有反义关系。", "散步": "散步是走路休闲，与丧失没有反义关系。", "演奏": "演奏是表演乐器或乐曲，与丧失没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd8808a2-9929-4d67-a12a-bad858840518') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
