INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93903, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "地质是地底下石头和泥土的样子。", "primary_collocate": null, "pronunciation": "dì zhì", "ipa": "ti˥˩ ʈʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "这一带的地质有很多硬石头，不容易挖。", "target_word": "地质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方的地质不好，不能盖高楼。", "target_word": "地质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人先检查地质，再开始修路。", "target_word": "地质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的地质很特别，到处是红色的石头。", "target_word": "地质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为地质松软，房子不能建在河边。", "target_word": "地质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的地质很稳定，很少地震。", "target_word": "地质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修桥以前，要先了解这里的地质。", "target_word": "地质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那里的地质是沙子，水很容易流走。", "target_word": "地质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们看了河边的地质。", "target_word": "地质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地质不同，山上长的树也不一样。", "target_word": "地质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "某地地下石头和泥土的状况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21d5d4e3-cb6a-4e49-9798-364dbe498c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93903, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "地质", "is_correct": true, "explanation": "正确：地质（dì zhì）指地下石头和泥土的状况。"}, {"text": "地址", "is_correct": false, "explanation": "地址（dì zhǐ）与地质（dì zhì）第二音节声调不同（第三声），意思是住址或位置。"}, {"text": "地震", "is_correct": false, "explanation": "地震（dì zhèn）与地质（dì zhì）韵母不同（en 与 i），意思是地面的震动。"}, {"text": "抵制", "is_correct": false, "explanation": "抵制（dǐ zhì）与地质（dì zhì）第一音节声调不同（第三声），意思是抵挡、拒绝，不是地质的近义词。"}, {"text": "地支", "is_correct": false, "explanation": "地支（dì zhī）与地质（dì zhì）第二音节声调不同（第一声），意思是天干地支中的地支。"}], "explanations": {"地质": "正确：地质（dì zhì）指地下石头和泥土的状况。", "地址": "地址（dì zhǐ）与地质（dì zhì）第二音节声调不同（第三声），意思是住址或位置。", "地震": "地震（dì zhèn）与地质（dì zhì）韵母不同（en 与 i），意思是地面的震动。", "抵制": "抵制（dǐ zhì）与地质（dì zhì）第一音节声调不同（第三声），意思是抵挡、拒绝，不是地质的近义词。", "地支": "地支（dì zhī）与地质（dì zhì）第二音节声调不同（第一声），意思是天干地支中的地支。"}, "sentence_index": null, "correct_answer": "地质"}, "level_3": {"options": [{"text": "地质", "is_correct": true, "explanation": "正确：“地质”指地下石头和泥土的状况，可以说“这一带的地质”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”指大气的冷热、晴雨，不是地下石头的状况。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”是表面的色彩，与“有很多硬石头”不相符。"}, {"text": "湿度", "is_correct": false, "explanation": "搭配：“湿度”说空气或土壤的含水量，不能与“有很多硬石头”搭配。"}], "explanations": {"地质": "正确：“地质”指地下石头和泥土的状况，可以说“这一带的地质”。", "天气": "语义：“天气”指大气的冷热、晴雨，不是地下石头的状况。", "颜色": "语义：“颜色”是表面的色彩，与“有很多硬石头”不相符。", "湿度": "搭配：“湿度”说空气或土壤的含水量，不能与“有很多硬石头”搭配。"}, "sentence_index": 0, "correct_answer": "地质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座山的地质很陡，我们爬了一天。", "explanation": "这里应该用〈地形〉。“地质”指地下石头和泥土的状况，不能用“很陡”形容地面的起伏。"}, {"text": "我们看了地质，才找到路。", "explanation": "这里应该用〈地图〉。“地质”指地下石头和泥土的状况，不能用来看路线。"}, {"text": "今天的地质很热。", "explanation": "这里应该用〈天气〉。“地质”指地下情况，不能用来说冷热等天气状况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93903, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地质", "is_correct": true, "explanation": "正确：“地质”指地下石头和泥土的状况，可以被“了解”。"}, {"text": "笑声", "is_correct": false, "explanation": "搭配：“了解”的对象是情况或事物，“笑声”不能这样被了解。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”是装书本的袋子，不是地方的情况，不能被“了解”。"}, {"text": "歌声", "is_correct": false, "explanation": "搭配：“歌声”是声音，不能与“了解这里的”搭配。"}], "explanations": {"地质": "正确：“地质”指地下石头和泥土的状况，可以被“了解”。", "笑声": "搭配：“了解”的对象是情况或事物，“笑声”不能这样被了解。", "书包": "语义：“书包”是装书本的袋子，不是地方的情况，不能被“了解”。", "歌声": "搭配：“歌声”是声音，不能与“了解这里的”搭配。"}, "sentence_index": 6, "correct_answer": "地质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块地质卖了很多钱。", "explanation": "这里应该用〈土地〉。“地质”指地下石头和泥土的状况，不指可以买卖的土地。"}, {"text": "这座山的地质很高，我们爬了一天。", "explanation": "这里应该用〈海拔〉。“地质”指地下情况，不能用来描述山的高度。"}, {"text": "这块地质很平，适合铺路。", "explanation": "这里应该用〈地面〉。“地质”指地下的石头和泥土，不指地表的平整程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93903, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片山区的地质很聪明，挖起来很费力。", "corrected_sentence": "这片山区的地质很坚硬，挖起来很费力。", "error_description": "搭配错误：“地质很聪明”。“聪明”只能形容人或动物，不能形容地下石头和泥土的状况；应改为“地质很坚硬”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93903, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里是一块很复杂的地质。", "corrected_sentence": "这里是一种很复杂的地质。", "error_description": "量词“块”误用于“地质”。“地质”可以用“种”计量，用“块”不自然；应为“一种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
