INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93904, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "地球的物质组成、结构及其发展变化情况。", "primary_collocate": null, "pronunciation": "dì zhì", "ipa": "ti˥˩ ʈʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "他在大学里学习地质。", "target_word": "地质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地质研究可以帮我们了解地球的历史。", "target_word": "地质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位专家一直做地质工作。", "target_word": "地质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对地质很感兴趣，常去山里找石头。", "target_word": "地质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了中国的地质。", "target_word": "地质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地质专业需要常常在野外工作。", "target_word": "地质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的爸爸是研究地质的老师。", "target_word": "地质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学了地质，我才知道山是怎么来的。", "target_word": "地质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地质变化很慢，要用几百万年。", "target_word": "地质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次展览讲的是地质和生命的关系。", "target_word": "地质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "地质学", "label": "复合词"}], "register": "中性", "sense_fingerprint": "地球的物质组成、结构与变化，也指相关学科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21d5d4e3-cb6a-4e49-9798-364dbe498c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93904, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "地质", "is_correct": true, "explanation": "正确：地质（dì zhì）指地球的物质组成、结构及其变化，也指相关学科。"}, {"text": "地址", "is_correct": false, "explanation": "地址（dì zhǐ）与地质（dì zhì）第二音节声调不同（第三声），意思是住址或位置。"}, {"text": "地震", "is_correct": false, "explanation": "地震（dì zhèn）与地质（dì zhì）韵母不同（en 与 i），意思是地面的震动。"}, {"text": "抵制", "is_correct": false, "explanation": "抵制（dǐ zhì）与地质（dì zhì）第一音节声调不同（第三声），意思是抵挡、拒绝，不是地质的近义词。"}, {"text": "地支", "is_correct": false, "explanation": "地支（dì zhī）与地质（dì zhì）第二音节声调不同（第一声），意思是天干地支中的地支。"}], "explanations": {"地质": "正确：地质（dì zhì）指地球的物质组成、结构及其变化，也指相关学科。", "地址": "地址（dì zhǐ）与地质（dì zhì）第二音节声调不同（第三声），意思是住址或位置。", "地震": "地震（dì zhèn）与地质（dì zhì）韵母不同（en 与 i），意思是地面的震动。", "抵制": "抵制（dǐ zhì）与地质（dì zhì）第一音节声调不同（第三声），意思是抵挡、拒绝，不是地质的近义词。", "地支": "地支（dì zhī）与地质（dì zhì）第二音节声调不同（第一声），意思是天干地支中的地支。"}, "sentence_index": null, "correct_answer": "地质"}, "level_3": {"options": [{"text": "地质", "is_correct": true, "explanation": "正确：“地质”作学科名称，可以说“学习地质”。"}, {"text": "地址", "is_correct": false, "explanation": "搭配：“学习”的对象是知识、学科，不能接“地址”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指人的重量，不是可以学习的学科。"}, {"text": "车票", "is_correct": false, "explanation": "语义：“车票”是票据，不是可以学习的内容。"}], "explanations": {"地质": "正确：“地质”作学科名称，可以说“学习地质”。", "地址": "搭配：“学习”的对象是知识、学科，不能接“地址”。", "体重": "语义：“体重”指人的重量，不是可以学习的学科。", "车票": "语义：“车票”是票据，不是可以学习的内容。"}, "sentence_index": 0, "correct_answer": "地质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地质的面积很大，有七大洲。", "explanation": "这里应该用〈地球〉。“地质”作学科时指研究领域，不能说它有面积和大洲。"}, {"text": "他在大学里创造了地质。", "explanation": "这里应该用〈研究〉。“地质”作学科时是“研究”的对象，不能说“创造”。"}, {"text": "他是一位优秀的地质。", "explanation": "这里应该用〈地质学家〉。“地质”作学科时不能指人，指从事地质研究的人要用“地质学家”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93904, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地质", "is_correct": true, "explanation": "正确：“地质”作学科名称，可以说“研究地质”。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：“午饭”是一顿饭，不是可以研究的学问，不能接“研究……的老师”。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：“钥匙”是开门的工具，不是学科。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”是遮雨的用品，不是学科。"}], "explanations": {"地质": "正确：“地质”作学科名称，可以说“研究地质”。", "午饭": "语义：“午饭”是一顿饭，不是可以研究的学问，不能接“研究……的老师”。", "钥匙": "语义：“钥匙”是开门的工具，不是学科。", "雨伞": "语义：“雨伞”是遮雨的用品，不是学科。"}, "sentence_index": 6, "correct_answer": "地质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的地质很好，我们去公园玩吧。", "explanation": "这里应该用〈天气〉。“地质”指地球的组成和结构，不能说今天适不适合出去玩。"}, {"text": "他把地质送给了朋友。", "explanation": "这里应该用〈书〉。“地质”作学科时不是可以送出去的物品。"}, {"text": "这次展览的地质很贵。", "explanation": "这里应该用〈门票〉。“地质”不能用来说价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93904, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地质是一块很有意思的学科。", "corrected_sentence": "地质是一门很有意思的学科。", "error_description": "量词“块”误用于学科。学科用“门”计量，“块”用于块状物；应为“一门很有意思的学科”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93904, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他学了过地质。", "corrected_sentence": "他学过地质。", "error_description": "“学”后的体态助词“了”与“过”不能同时使用，二者只能选一个。表示曾经学过，应删去“了”，说“学过地质”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
