INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93905, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大厅是房子里面又大又宽的一间屋子，通常在门口。", "primary_collocate": null, "pronunciation": "dà tīng", "ipa": "ta˥˩ tʰiŋ˥", "syllable_count": 2, "sentences": [{"text": "我家一进门就是大厅，鞋放在左边。", "target_word": "大厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人来了，妈妈请他们先坐在大厅里。", "target_word": "大厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的老房子有一个很宽的大厅。", "target_word": "大厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在大厅里跑来跑去，很开心。", "target_word": "大厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大厅的桌子上放着一盆花。", "target_word": "大厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家的大厅里有沙发和电视。", "target_word": "大厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，他在大厅里放好了伞。", "target_word": "大厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚饭后，一家人在大厅里聊天。", "target_word": "大厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大厅的门开着，我听见里面有人说话。", "target_word": "大厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房子的大厅朝南，很亮。", "target_word": "大厅", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "住宅里靠近门口、又大又宽的那间屋子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d0ac1ee-96ca-4bdf-89c5-eda7614b9f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93905, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "阳台", "is_correct": false, "explanation": "语义：阳台在房屋外侧，不会一进门就是，与“鞋放在左边”的室内场景不符"}, {"text": "大厅", "is_correct": true, "explanation": "大厅是住宅里靠近门口的大房间，“我家一进门就是大厅”符合语境"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是室外场所，进门就是花园与室内放鞋的语境冲突"}, {"text": "地下室", "is_correct": false, "explanation": "搭配：“一进门就是”接的是门口所见的房间，地下室要下楼梯才能到，不能说一进门就是"}], "explanations": {"阳台": "语义：阳台在房屋外侧，不会一进门就是，与“鞋放在左边”的室内场景不符", "大厅": "大厅是住宅里靠近门口的大房间，“我家一进门就是大厅”符合语境", "花园": "语义：花园是室外场所，进门就是花园与室内放鞋的语境冲突", "地下室": "搭配：“一进门就是”接的是门口所见的房间，地下室要下楼梯才能到，不能说一进门就是"}, "sentence_index": 0, "correct_answer": "大厅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在大厅里洗澡。", "explanation": "这里应该用〈浴室〉。大厅是进门附近的大房间，不用来洗澡，洗澡要在浴室"}, {"text": "我家有一台大厅。", "explanation": "这里量词应该用〈个〉。“台”用于机器、电器，大厅不能用“台”来计量"}, {"text": "妈妈在大厅里做饭。", "explanation": "这里应该用〈厨房〉。大厅在进门处，是客人进出的空间，不用来做饭，做饭要在厨房"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93905, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠少雨，下雨时不会在沙漠里放伞，与“下雨了”的语境不符"}, {"text": "游泳池", "is_correct": false, "explanation": "语义：游泳池装着水，在里面放好伞的说法与语境冲突"}, {"text": "大厅", "is_correct": true, "explanation": "大厅是屋内靠门的房间，下雨时在大厅里放伞符合语境"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：冰箱用来存放食物，“放好了伞”与冰箱的功能不搭配"}], "explanations": {"沙漠": "语义：沙漠少雨，下雨时不会在沙漠里放伞，与“下雨了”的语境不符", "游泳池": "语义：游泳池装着水，在里面放好伞的说法与语境冲突", "大厅": "大厅是屋内靠门的房间，下雨时在大厅里放伞符合语境", "冰箱": "搭配：冰箱用来存放食物，“放好了伞”与冰箱的功能不搭配"}, "sentence_index": 6, "correct_answer": "大厅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在大厅里晒被子。", "explanation": "这里应该用〈阳台〉。晒被子要在户外有阳光的地方，大厅是屋内靠门的空间，不用来晒被子"}, {"text": "我们把车停在大厅里。", "explanation": "这里应该用〈车库〉。大厅是屋内靠门的大房间，不用来停车，停车要去车库"}, {"text": "这个房子有一辆大厅。", "explanation": "这里量词应该用〈个〉。“辆”用于车，大厅不能用“辆”来计量"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93905, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷被大厅收拾干净了。", "corrected_sentence": "爷爷把大厅收拾干净了。", "error_description": "错误：“被”字句的施事不能是“大厅”（大厅不能收拾人），应改用“把”字句。正确为“爷爷把大厅收拾干净了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93905, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末全家人大厅里吃水果。", "corrected_sentence": "周末全家人在大厅里吃水果。", "error_description": "错误：“大厅里”前漏掉了介词“在”。正确为“全家人在大厅里吃水果”，表示动作的地点要用“在”引出。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
