INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93906, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93906, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "建筑物中供人通行或集会的宽大房间。", "primary_collocate": null, "pronunciation": "dà tīng", "ipa": "ta˥˩ tʰiŋ˥", "syllable_count": 2, "sentences": [{"text": "酒店的大厅里有很多等人的客人。", "target_word": "大厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在医院大厅等你，别走远。", "target_word": "大厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车站的大厅很大，人也特别多。", "target_word": "大厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议前，大家先在大厅里签到。", "target_word": "大厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大厅的墙上挂着一幅很大的画。", "target_word": "大厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行大厅里有人帮你填表。", "target_word": "大厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走进大厅，问前台小姐房间在哪儿。", "target_word": "大厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大厅的灯太亮了，我有点睁不开眼。", "target_word": "大厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影开始前，观众都在大厅里排队。", "target_word": "大厅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年晚会在公司大厅举行，很热闹。", "target_word": "大厅", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "公共建筑里供人通行、等候或集会的宽敞大房间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d0ac1ee-96ca-4bdf-89c5-eda7614b9f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93906, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，不是客人成群等人的场所，与“等人的客人”的语境不符"}, {"text": "大厅", "is_correct": true, "explanation": "大厅是供人通行或集会的宽大房间，“酒店的大厅里有很多等人的客人”语境吻合"}, {"text": "卧室", "is_correct": false, "explanation": "语义：卧室是私人房间，不会聚集很多等人的客人"}, {"text": "厕所", "is_correct": false, "explanation": "语义：厕所是如厕的地方，不是宾客成群等候的场所，与酒店大厅的语境不符"}], "explanations": {"厨房": "语义：厨房是做饭的地方，不是客人成群等人的场所，与“等人的客人”的语境不符", "大厅": "大厅是供人通行或集会的宽大房间，“酒店的大厅里有很多等人的客人”语境吻合", "卧室": "语义：卧室是私人房间，不会聚集很多等人的客人", "厕所": "语义：厕所是如厕的地方，不是宾客成群等候的场所，与酒店大厅的语境不符"}, "sentence_index": 0, "correct_answer": "大厅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大厅一共有二十层。", "explanation": "这里应该用〈大楼〉。大厅只是建筑里的一个房间，不说有几层；整栋建筑才用大楼"}, {"text": "他在大厅里刷牙。", "explanation": "这里应该用〈洗手间〉。大厅是供人通行或集会的公共房间，不用来刷牙，刷牙要去洗手间"}, {"text": "他在酒店看到一条大厅。", "explanation": "这里量词应该用〈个〉。大厅是房间，不能用“条”（条用于细长的东西）来计量"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93906, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花园", "is_correct": false, "explanation": "语义：花园在室外，与“前台小姐”所在的室内接待处不符"}, {"text": "教室", "is_correct": false, "explanation": "搭配：“问前台小姐房间在哪儿”的场所应是酒店一类的接待处，教室里没有前台，不能搭配"}, {"text": "大厅", "is_correct": true, "explanation": "大厅是供人通行的公共房间，“走进大厅，问前台小姐房间在哪儿”语境吻合"}, {"text": "书房", "is_correct": false, "explanation": "语义：书房是私人房间，不会有前台小姐，与询问房间位置的语境冲突"}], "explanations": {"花园": "语义：花园在室外，与“前台小姐”所在的室内接待处不符", "教室": "搭配：“问前台小姐房间在哪儿”的场所应是酒店一类的接待处，教室里没有前台，不能搭配", "大厅": "大厅是供人通行的公共房间，“走进大厅，问前台小姐房间在哪儿”语境吻合", "书房": "语义：书房是私人房间，不会有前台小姐，与询问房间位置的语境冲突"}, "sentence_index": 6, "correct_answer": "大厅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "客人住进了大厅，很舒服。", "explanation": "这里应该用〈房间〉。大厅是供人通行或集会的公共场所，不用来住宿，住宿要用房间"}, {"text": "孩子们在大厅里游泳。", "explanation": "这里应该用〈游泳池〉。大厅没有水，不能用来游泳，游泳要去游泳池"}, {"text": "他找到了一扇大厅。", "explanation": "这里量词应该用〈个〉。“扇”用于门窗，大厅不能用“扇”来计量"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93906, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我大厅里等你。", "corrected_sentence": "我在大厅里等你。", "error_description": "错误：“大厅里”前漏掉了介词“在”。正确为“我在大厅里等你”：“等”后面表示地点要用“在”引出，不能直接说“大厅里等”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93906, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们大厅打扫干净了。", "corrected_sentence": "工人们把大厅打扫干净了。", "error_description": "错误：“把”字句中漏掉了“把”字。正确为“工人们把大厅打扫干净了”：处置“大厅”要在动词前用“把”引出，不能直接说“工人们大厅打扫干净了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d88268-0315-4ff5-866c-ff177b82d621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93907, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93907, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93907, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大奖是很大的奖励，只有最棒的人才能得到。", "primary_collocate": null, "pronunciation": "dà jiǎng", "ipa": "ta˥˩ tɕjaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "只有最棒的人才能拿到大奖。", "target_word": "大奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个大奖很难得，每年只给一个人。", "target_word": "大奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他努力工作，希望有一天能得大奖。", "target_word": "大奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛很难，不是每个人都能得大奖。", "target_word": "大奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大奖只给最好的学生，我还差一点。", "target_word": "大奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她跳舞跳得特别好，终于赢得了大奖。", "target_word": "大奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "得大奖的人要上台讲几句话。", "target_word": "大奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，得大奖不容易，要多练习。", "target_word": "大奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小城的大奖，他拿过两次。", "target_word": "大奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们班的画拿了大奖，大家都很高兴。", "target_word": "大奖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "大獎", "label": "繁体"}], "register": "中性", "sense_fingerprint": "只有最棒的人才能得到的很大的奖励", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9121c34-cc79-4eb7-895a-10bbd4da9bea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93907, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大江", "is_correct": false, "explanation": "大江（dàjiāng）与大奖（dàjiǎng）只有第二个音节声调不同，意思是大江。"}, {"text": "大奖", "is_correct": true, "explanation": "正确：大奖，很大的奖励，只有最棒的人才能得到。"}, {"text": "大将", "is_correct": false, "explanation": "大将（dàjiàng）与大奖只有第二个音节声调不同，意思是高级将领。"}, {"text": "大脚", "is_correct": false, "explanation": "大脚（dàjiǎo）与大奖只有韵母不同（-ǎo 与 -ǎng），意思是大的脚。"}], "explanations": {"大江": "大江（dàjiāng）与大奖（dàjiǎng）只有第二个音节声调不同，意思是大江。", "大奖": "正确：大奖，很大的奖励，只有最棒的人才能得到。", "大将": "大将（dàjiàng）与大奖只有第二个音节声调不同，意思是高级将领。", "大脚": "大脚（dàjiǎo）与大奖只有韵母不同（-ǎo 与 -ǎng），意思是大的脚。"}, "sentence_index": null, "correct_answer": "大奖"}, "level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "语义：作业是老师布置的，不是靠本事拿到的，与“最棒的人”不符。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“拿到”后不接感冒，句子不通。"}, {"text": "大奖", "is_correct": true, "explanation": "正确：大奖指只有最棒的人才能拿到的很大的奖励。"}, {"text": "比赛", "is_correct": false, "explanation": "搭配：“拿到”后不接比赛，比赛应说“参加”。"}], "explanations": {"作业": "语义：作业是老师布置的，不是靠本事拿到的，与“最棒的人”不符。", "感冒": "搭配：“拿到”后不接感冒，句子不通。", "大奖": "正确：大奖指只有最棒的人才能拿到的很大的奖励。", "比赛": "搭配：“拿到”后不接比赛，比赛应说“参加”。"}, "sentence_index": 0, "correct_answer": "大奖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛，每个参加的人都拿到了大奖。", "explanation": "这里应该用〈纪念品〉。纪念品可以人人都有，大奖只给最棒的人。"}, {"text": "学校给每个学生都发了大奖。", "explanation": "这里应该用〈奖学金〉。奖学金可以发给很多学生，大奖只颁给最棒的人。"}, {"text": "参加活动的人都能领一块糖，这块糖就是大奖。", "explanation": "这里应该用〈小礼物〉。人人都有的一块糖只是小礼物，大奖是很大的奖励，只给最棒的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93907, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "近视", "is_correct": false, "explanation": "语义：得近视与上台讲几句话无关，句意不通。"}, {"text": "肺炎", "is_correct": false, "explanation": "语义：得肺炎与上台讲几句话无关，句意不通。"}, {"text": "大奖", "is_correct": true, "explanation": "正确：大奖是只有最棒的人才能得到的奖，得奖的人要上台讲话。"}, {"text": "病假", "is_correct": false, "explanation": "搭配：“得”后接病假不自然，病假不需要上台讲话。"}], "explanations": {"近视": "语义：得近视与上台讲几句话无关，句意不通。", "肺炎": "语义：得肺炎与上台讲几句话无关，句意不通。", "大奖": "正确：大奖是只有最棒的人才能得到的奖，得奖的人要上台讲话。", "病假": "搭配：“得”后接病假不自然，病假不需要上台讲话。"}, "sentence_index": 6, "correct_answer": "大奖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每个月都能领到大奖。", "explanation": "这里应该用〈奖金〉。大奖是很大的奖励，不是按月领取的钱。"}, {"text": "老师给每个同学都发了大奖。", "explanation": "这里应该用〈奖状〉。奖状可以发给每个同学，大奖只有最棒的人才能得到。"}, {"text": "运动会上每个班级都拿到了大奖。", "explanation": "这里应该用〈奖牌〉。奖牌可以人人都拿到，大奖只颁给最棒的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93907, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他靠实力拿到了一条大奖，大家都很佩服。", "corrected_sentence": "他靠实力拿到了一个大奖，大家都很佩服。", "error_description": "量词错误：大奖应使用量词“个”，“条”用于细长的东西，这里用错了。正确说法是“一个大奖”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93907, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她终于得到了一大奖，大家都很激动。", "corrected_sentence": "她终于得到了一个大奖，大家都很激动。", "error_description": "量词缺失：大奖前必须有量词“个”，不能省略为“一大奖”。正确说法是“一个大奖”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
