INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93908, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "价值高或荣誉高的奖励；最高奖。", "primary_collocate": null, "pronunciation": "dà jiǎng", "ipa": "ta˥˩ tɕjaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这部电影得了一个国际大奖。", "target_word": "大奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次拿到大奖，激动得哭了。", "target_word": "大奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写的小说获得了文学大奖。", "target_word": "大奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛的大奖是一辆新车。", "target_word": "大奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁能赢得今年的大奖，还不知道。", "target_word": "大奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位歌手去年拿过三个音乐大奖。", "target_word": "大奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他得了大奖，朋友们都来祝贺他。", "target_word": "大奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影节的大奖今晚就要公布了。", "target_word": "大奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了拿大奖，练了整整五年。", "target_word": "大奖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把大奖的奖杯放在了书架上。", "target_word": "大奖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "大獎", "label": "繁体"}], "register": "中性", "sense_fingerprint": "价值或荣誉很高的最高奖励", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9121c34-cc79-4eb7-895a-10bbd4da9bea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93908, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大江", "is_correct": false, "explanation": "大江（dàjiāng）与大奖（dàjiǎng）只有第二个音节声调不同（第一声与第三声），意思是大江。"}, {"text": "大奖", "is_correct": true, "explanation": "正确：大奖，价值高或荣誉高的奖励，指最高奖。"}, {"text": "大将", "is_correct": false, "explanation": "大将（dàjiàng）与大奖只有第二个音节声调不同（第四声与第三声），意思是高级将领。"}, {"text": "大脚", "is_correct": false, "explanation": "大脚（dàjiǎo）与大奖只有第二个音节韵母不同（-ǎo 与 -ǎng），意思是大的脚。"}], "explanations": {"大江": "大江（dàjiāng）与大奖（dàjiǎng）只有第二个音节声调不同（第一声与第三声），意思是大江。", "大奖": "正确：大奖，价值高或荣誉高的奖励，指最高奖。", "大将": "大将（dàjiàng）与大奖只有第二个音节声调不同（第四声与第三声），意思是高级将领。", "大脚": "大脚（dàjiǎo）与大奖只有第二个音节韵母不同（-ǎo 与 -ǎng），意思是大的脚。"}, "sentence_index": null, "correct_answer": "大奖"}, "level_3": {"options": [{"text": "奖学金", "is_correct": false, "explanation": "语义：奖学金只颁给学生，与“电影”不搭。"}, {"text": "大奖", "is_correct": true, "explanation": "正确：大奖是价值高、荣誉高的最高奖，电影可以“得”到。"}, {"text": "学位", "is_correct": false, "explanation": "语义：学位是学业授予的，电影不能获得学位。"}, {"text": "比赛", "is_correct": false, "explanation": "搭配：“得”后不接比赛，比赛应说“参加”。"}], "explanations": {"奖学金": "语义：奖学金只颁给学生，与“电影”不搭。", "大奖": "正确：大奖是价值高、荣誉高的最高奖，电影可以“得”到。", "学位": "语义：学位是学业授予的，电影不能获得学位。", "比赛": "搭配：“得”后不接比赛，比赛应说“参加”。"}, "sentence_index": 0, "correct_answer": "大奖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛的大奖，所有参加的人都能拿到。", "explanation": "这里应该用〈纪念品〉。纪念品可以人人都有，大奖是最高的奖，只有极少数人能得到。"}, {"text": "学校给每个学生发了一个大奖。", "explanation": "这里应该用〈奖状〉。奖状可以人人都有，大奖是最高的一个奖，只能颁给极少数人。"}, {"text": "学校的大奖是一本笔记本。", "explanation": "这里应该用〈奖品〉。大奖指价值高、荣誉高的最高奖，一本笔记本只是普通奖品，不能叫大奖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93908, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感冒", "is_correct": false, "explanation": "语义：生病不值得朋友来祝贺，句意不合。"}, {"text": "大奖", "is_correct": true, "explanation": "正确：大奖是最高奖，得到后朋友会来祝贺。"}, {"text": "批评", "is_correct": false, "explanation": "配价：“得”后接批评不自然，应说“受到批评”。"}, {"text": "肺炎", "is_correct": false, "explanation": "语义：得肺炎不是值得祝贺的事，与句意相反。"}], "explanations": {"感冒": "语义：生病不值得朋友来祝贺，句意不合。", "大奖": "正确：大奖是最高奖，得到后朋友会来祝贺。", "批评": "配价：“得”后接批评不自然，应说“受到批评”。", "肺炎": "语义：得肺炎不是值得祝贺的事，与句意相反。"}, "sentence_index": 6, "correct_answer": "大奖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "运动会上每个选手都拿到了大奖。", "explanation": "这里应该用〈奖牌〉。大奖是唯一的最高奖，不能人人都拿到。"}, {"text": "他每个月都领到了大奖。", "explanation": "这里应该用〈奖金〉。大奖是一次性的最高奖，不是按月发放的奖金。"}, {"text": "我买了一包口香糖，店员说送我一个大奖。", "explanation": "这里应该用〈小礼品〉。大奖指价值高、荣誉高的最高奖，一包口香糖只是小礼品，不能叫大奖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93908, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她终于拿到了一条大奖，高兴极了。", "corrected_sentence": "她终于拿到了一个大奖，高兴极了。", "error_description": "量词错误：大奖的量词应为“个”，“条”用于细长的东西，不能修饰大奖。正确说法是“一个大奖”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93908, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在比赛中赢得了一大奖。", "corrected_sentence": "他在比赛中赢得了一个大奖。", "error_description": "量词缺失：大奖前必须有量词“个”，不能省略为“一大奖”。正确说法是“一个大奖”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02b7bedf-d815-4c8c-8568-ab64ad8a7169') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
