INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93910, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "集中收录某位歌手或某类作品的唱片或出版物。", "primary_collocate": null, "pronunciation": "zhuān jí", "ipa": "ʈʂuan˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "图书馆里有一本老照片专辑。", "target_word": "专辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套专辑收了他所有的电影歌曲。", "target_word": "专辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本摄影专辑里有很多风景照。", "target_word": "专辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出版社出了一本诗歌专辑。", "target_word": "专辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是歌手二十年来的精选专辑。", "target_word": "专辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她收藏了很多老歌手的专辑。", "target_word": "专辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店专门卖各国歌手的专辑。", "target_word": "专辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杂志社做了一本旅行专辑。", "target_word": "专辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张纪念专辑只做了一千张。", "target_word": "专辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本专辑收了二十张老照片。", "target_word": "专辑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一本专辑", "label": "量词"}, {"form": "摄影专辑", "label": "复合词"}, {"form": "專輯", "label": "繁体"}], "register": "通用", "sense_fingerprint": "集中收录某人或某类作品的唱片或出版物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f01308c1-157a-474f-8335-9b2ec1714ab6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93910, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "专辑", "is_correct": true, "explanation": "正确答案：专辑，指集中收录某人或某类作品的唱片或出版物，读作 zhuān jí。"}, {"text": "专机", "is_correct": false, "explanation": "zhuān 相同，jī（第一声）与 jí（第二声）声调不同，意思是专门用来载运重要人物的飞机。"}, {"text": "转机", "is_correct": false, "explanation": "zhuǎn（第三声）与 zhuān（第一声）声调不同，jī（第一声）与 jí（第二声）声调也不同，意思是转乘另一班飞机。"}, {"text": "传记", "is_correct": false, "explanation": "zhuàn（第四声）与 zhuān（第一声）、jì（第四声）与 jí（第二声）声调均不同，意思是记录人物生平的书。"}, {"text": "专职", "is_correct": false, "explanation": "zhí 与 jí 声母不同（zh 与 j），且 zhí 为第二声，意思是专门担任的职务。"}], "explanations": {"专辑": "正确答案：专辑，指集中收录某人或某类作品的唱片或出版物，读作 zhuān jí。", "专机": "zhuān 相同，jī（第一声）与 jí（第二声）声调不同，意思是专门用来载运重要人物的飞机。", "转机": "zhuǎn（第三声）与 zhuān（第一声）声调不同，jī（第一声）与 jí（第二声）声调也不同，意思是转乘另一班飞机。", "传记": "zhuàn（第四声）与 zhuān（第一声）、jì（第四声）与 jí（第二声）声调均不同，意思是记录人物生平的书。", "专职": "zhí 与 jí 声母不同（zh 与 j），且 zhí 为第二声，意思是专门担任的职务。"}, "sentence_index": null, "correct_answer": "专辑"}, "level_3": {"options": [{"text": "专辑", "is_correct": true, "explanation": "正确答案：专辑，指集中收录照片的本子，与“一本老照片”相符。"}, {"text": "试卷", "is_correct": false, "explanation": "语义：“试卷”是考试用的题目纸，不是收录照片的本子，与句意不符。"}, {"text": "小说", "is_correct": false, "explanation": "语义：“小说”是虚构的文字作品，不是收录老照片的本子，与句意不符。"}, {"text": "歌谱", "is_correct": false, "explanation": "搭配：“老照片”与“歌谱”搭配不当，前者指图片，后者指记录乐曲的乐谱。"}], "explanations": {"专辑": "正确答案：专辑，指集中收录照片的本子，与“一本老照片”相符。", "试卷": "语义：“试卷”是考试用的题目纸，不是收录照片的本子，与句意不符。", "小说": "语义：“小说”是虚构的文字作品，不是收录老照片的本子，与句意不符。", "歌谱": "搭配：“老照片”与“歌谱”搭配不当，前者指图片，后者指记录乐曲的乐谱。"}, "sentence_index": 0, "correct_answer": "专辑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首诗是专辑写的。", "explanation": "这里应该用〈诗人〉。写诗的是人，专辑是出版物，收录作品但不会写诗。"}, {"text": "出版社昨天开了一场专辑。", "explanation": "这里把“专辑”当成了可以举办的活动，应该用〈会议〉之类的活动。专辑是出版物，不能被举办，所以不能说“开专辑”。"}, {"text": "这只摄影专辑很厚。", "explanation": "这里应该用〈本〉。专辑用“本”计量，“只”用于动物，不能用于专辑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '565832eb-6e16-435c-bc95-9b8b731e7e39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93910, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专辑", "is_correct": true, "explanation": "正确答案：专辑，指集中收录某类作品的唱片或出版物，与“各国歌手的”相符。"}, {"text": "地图", "is_correct": false, "explanation": "语义：“地图”标示地理位置，与歌手作品无关，店铺也不会专门卖这类东西。"}, {"text": "零件", "is_correct": false, "explanation": "语义：“零件”是机械的组成部分，不是歌手的作品，与句意不符。"}, {"text": "文献", "is_correct": false, "explanation": "语义：“文献”指学术或历史资料，与歌手的作品不符，店铺一般不会专门卖这类东西。"}], "explanations": {"专辑": "正确答案：专辑，指集中收录某类作品的唱片或出版物，与“各国歌手的”相符。", "地图": "语义：“地图”标示地理位置，与歌手作品无关，店铺也不会专门卖这类东西。", "零件": "语义：“零件”是机械的组成部分，不是歌手的作品，与句意不符。", "文献": "语义：“文献”指学术或历史资料，与歌手的作品不符，店铺一般不会专门卖这类东西。"}, "sentence_index": 6, "correct_answer": "专辑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "专辑拍了很多风景照。", "explanation": "这里应该用〈摄影师〉。拍照的是人，专辑是册子，本身不会拍照。"}, {"text": "我买了三根专辑。", "explanation": "这里应该用〈本〉。专辑用“本”计量，“根”用于细长的东西，不能用于专辑。"}, {"text": "这本专辑的味道很甜。", "explanation": "搭配：“味道很甜”用于食物，“专辑”是出版物，没有味道，这样说不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '565832eb-6e16-435c-bc95-9b8b731e7e39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93910, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一只摄影专辑。", "corrected_sentence": "我买了一本摄影专辑。", "error_description": "量词错误。专辑用量词“本”，“只”用于动物等，不能用于专辑。应说“一本摄影专辑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '565832eb-6e16-435c-bc95-9b8b731e7e39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93910, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店卖各国歌手的专辑们。", "corrected_sentence": "这家店卖各国歌手的专辑。", "error_description": "名词复数用法错误。“们”一般只用于指人的名词，“专辑”是唱片或出版物，不能加“们”。应说“歌手的专辑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '565832eb-6e16-435c-bc95-9b8b731e7e39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
