INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93911, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "差距是两个东西不一样的地方，差了多少。", "primary_collocate": null, "pronunciation": "chā jù", "ipa": "ʈʂʰa˥ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "我和哥哥的身高差距很大。", "target_word": "差距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个队的差距越来越小。", "target_word": "差距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和我的成绩差距不大。", "target_word": "差距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看到了自己和别人的差距。", "target_word": "差距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市和农村的差距还很大。", "target_word": "差距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的收入差距有一万多块。", "target_word": "差距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比分差距只有两分。", "target_word": "差距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两家店的价格差距很小。", "target_word": "差距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的差距在于练习的时间。", "target_word": "差距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他努力学习，想缩小和同学的差距。", "target_word": "差距", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个差距", "label": "量词"}], "register": "中性", "sense_fingerprint": "两者相比差了多少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6890ad06-571d-4ab3-9fbc-f9d69fcc7e4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93911, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "差距", "is_correct": true, "explanation": "正确：差距指两者相比差了多少，即这里说的身高或成绩的差别。"}, {"text": "茶具", "is_correct": false, "explanation": "chá（第二声）与 chā（第一声）声调不同，意思是茶具，即喝茶用的器具。"}, {"text": "车距", "is_correct": false, "explanation": "chē 与 chā 韵母不同（ē/ā），意思是车与车之间的距离。"}, {"text": "出具", "is_correct": false, "explanation": "chū 与 chā 韵母不同（ū/ā），意思是开出（证明、文件）。"}], "explanations": {"差距": "正确：差距指两者相比差了多少，即这里说的身高或成绩的差别。", "茶具": "chá（第二声）与 chā（第一声）声调不同，意思是茶具，即喝茶用的器具。", "车距": "chē 与 chā 韵母不同（ē/ā），意思是车与车之间的距离。", "出具": "chū 与 chā 韵母不同（ū/ā），意思是开出（证明、文件）。"}, "sentence_index": null, "correct_answer": "差距"}, "level_3": {"options": [{"text": "差距", "is_correct": true, "explanation": "正确：“身高差距”指两人身高相差多少，与“很大”搭配。"}, {"text": "高度", "is_correct": false, "explanation": "语义：“身高”已经包含“高”的意思，再说“身高高度”语义重复，不符合句意。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”与“身高”不是同类属性，不能说“身高年龄很大”。"}, {"text": "数量", "is_correct": false, "explanation": "搭配：“数量”指个数的多少，不用来比较身高，不说“身高数量很大”。"}], "explanations": {"差距": "正确：“身高差距”指两人身高相差多少，与“很大”搭配。", "高度": "语义：“身高”已经包含“高”的意思，再说“身高高度”语义重复，不符合句意。", "年龄": "搭配：“年龄”与“身高”不是同类属性，不能说“身高年龄很大”。", "数量": "搭配：“数量”指个数的多少，不用来比较身高，不说“身高数量很大”。"}, "sentence_index": 0, "correct_answer": "差距"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张桌子和那个故事的差距很大。", "explanation": "这里应该用〈差别〉。差距指同类事物在水平或程度上的差距，桌子和故事不是可比较的同类，只能说差别。"}, {"text": "我们之间有一块差距，需要慢慢缩小。", "explanation": "这里应该用〈个〉。差距是抽象名词，量词用“个”或“种”，不能用“块”。"}, {"text": "我和他差距了二十分。", "explanation": "这里应该用〈差〉。“差距”是名词，不能当动词带“了”和数量，应该说“我和他差了二十分”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93911, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "差距", "is_correct": true, "explanation": "正确：“比分差距”指两队得分相差多少，只有两分，符合句意。"}, {"text": "分数", "is_correct": false, "explanation": "语义：“比分”本身已表示得分，再说“比分分数”语义重复。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”指时段，与“比分”表示的得分多少不符。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”指人或物的重量，不能用来说比分的差距，“比分体重”不成立。"}], "explanations": {"差距": "正确：“比分差距”指两队得分相差多少，只有两分，符合句意。", "分数": "语义：“比分”本身已表示得分，再说“比分分数”语义重复。", "时间": "语义：“时间”指时段，与“比分”表示的得分多少不符。", "体重": "搭配：“体重”指人或物的重量，不能用来说比分的差距，“比分体重”不成立。"}, "sentence_index": 6, "correct_answer": "差距"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两种动物的习性有明显差距。", "explanation": "这里应该用〈差异〉。“差距”指水平或程度上的高低，说习性、性质上的不同要用“差异”。"}, {"text": "我和朋友之间有一把差距。", "explanation": "这里应该用〈个〉。差距是抽象名词，量词用“个”或“种”，“把”只用于有把手的东西。"}, {"text": "这两个字的差距在于声调。", "explanation": "这里应该用〈区别〉。“差距”侧重水平或程度的高低，说具体的不同之处要用“区别”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93911, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个队之间有一根明显的差距。", "corrected_sentence": "两个队之间有一个明显的差距。", "error_description": "错误：“一根差距”；正确：“一个差距”。“差距”是抽象名词，量词用“个”，“根”只用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93911, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我和他的成绩差距。", "corrected_sentence": "我和他的成绩有差距。", "error_description": "错误：“差距”前缺少动词“有”；正确：“有差距”。“差距”是名词，不能直接作谓语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
