INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93912, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物之间的差别程度；距离。", "primary_collocate": null, "pronunciation": "chā jù", "ipa": "ʈʂʰa˥ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "两国经济发展的差距很明显。", "target_word": "差距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "理想和现实之间有差距。", "target_word": "差距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛让我们看到了差距。", "target_word": "差距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跟他比，我的汉语还有差距。", "target_word": "差距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人和年轻人的想法有差距。", "target_word": "差距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "贫富差距是个大问题。", "target_word": "差距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个城市的生活水平差距很大。", "target_word": "差距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要努力缩小与别人的差距。", "target_word": "差距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人的水平差距越来越大。", "target_word": "差距", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她发现自己和朋友有很大差距。", "target_word": "差距", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个差距", "label": "量词"}], "register": "中性", "sense_fingerprint": "事物之间差别的程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6890ad06-571d-4ab3-9fbc-f9d69fcc7e4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93912, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "差距", "is_correct": true, "explanation": "正确：差距指事物之间差别的程度。"}, {"text": "茶具", "is_correct": false, "explanation": "chá（第二声）与 chā（第一声）声调不同，意思是茶具，即喝茶用的器具。"}, {"text": "车距", "is_correct": false, "explanation": "chē 与 chā 韵母不同（ē/ā），意思是车与车之间的距离。"}, {"text": "出具", "is_correct": false, "explanation": "chū 与 chā 韵母不同（ū/ā），意思是开出（证明、文件）。"}], "explanations": {"差距": "正确：差距指事物之间差别的程度。", "茶具": "chá（第二声）与 chā（第一声）声调不同，意思是茶具，即喝茶用的器具。", "车距": "chē 与 chā 韵母不同（ē/ā），意思是车与车之间的距离。", "出具": "chū 与 chā 韵母不同（ū/ā），意思是开出（证明、文件）。"}, "sentence_index": null, "correct_answer": "差距"}, "level_3": {"options": [{"text": "差距", "is_correct": true, "explanation": "正确：“经济发展的差距”指两国发展水平相差多少，与“很明显”搭配。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”指时段，不能说“经济发展的时间很明显”，与句意不符。"}, {"text": "数量", "is_correct": false, "explanation": "搭配：“数量”指个数，不用来说经济发展的差别，“经济发展的数量”不成立。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”只用于人或物的重量，不能用于两国的经济发展，“体重很明显”不通。"}], "explanations": {"差距": "正确：“经济发展的差距”指两国发展水平相差多少，与“很明显”搭配。", "时间": "语义：“时间”指时段，不能说“经济发展的时间很明显”，与句意不符。", "数量": "搭配：“数量”指个数，不用来说经济发展的差别，“经济发展的数量”不成立。", "体重": "搭配：“体重”只用于人或物的重量，不能用于两国的经济发展，“体重很明显”不通。"}, "sentence_index": 0, "correct_answer": "差距"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们两国之间有一块差距，很难缩小。", "explanation": "这里应该用〈个〉。差距是抽象名词，量词用“个”或“种”，不能用“块”。"}, {"text": "这两种颜色的差距是一个红一个蓝。", "explanation": "这里应该用〈区别〉。“差距”指水平或程度上的高低，说颜色这种性质上的不同要用“区别”。"}, {"text": "跟他比，我有一把差距。", "explanation": "这里应该用〈个〉。差距是抽象名词，量词用“个”或“种”，“把”只用于有把手的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93912, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "差距", "is_correct": true, "explanation": "正确：“生活水平差距”指两个城市的水平相差多少，与“很大”搭配。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”不能用来比较城市的生活水平，“生活水平年龄很大”不通。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”只用于人，不用于城市的生活水平。"}, {"text": "速度", "is_correct": false, "explanation": "语义：“速度”指快慢，与“生活水平”的高低不相干。"}], "explanations": {"差距": "正确：“生活水平差距”指两个城市的水平相差多少，与“很大”搭配。", "年龄": "搭配：“年龄”不能用来比较城市的生活水平，“生活水平年龄很大”不通。", "身高": "搭配：“身高”只用于人，不用于城市的生活水平。", "速度": "语义：“速度”指快慢，与“生活水平”的高低不相干。"}, "sentence_index": 6, "correct_answer": "差距"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两条裙子的差距是颜色。", "explanation": "这里应该用〈区别〉。“差距”指水平或程度上的高低，说颜色、款式上的不同要用“区别”。"}, {"text": "两个人之间有一条差距。", "explanation": "这里应该用〈个〉。差距是抽象名词，量词用“个”或“种”，“条”多用于细长的东西。"}, {"text": "我和他之间有一座差距。", "explanation": "这里应该用〈个〉。差距是抽象名词，量词用“个”或“种”，“座”多用于山、楼等大型建筑或物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93912, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的汉语和他差距。", "corrected_sentence": "我的汉语和他有差距。", "error_description": "错误：“差距”前缺少动词“有”；正确：“有差距”。“差距”是名词，不能直接作谓语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93912, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两个城市的生活水平有一只很大的差距。", "corrected_sentence": "这两个城市的生活水平有一个很大的差距。", "error_description": "错误：“一只差距”；正确：“一个差距”。“只”多用于动物或成对物件中的一个，不能用于抽象的差距。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f04f7d25-fe69-48b6-9e9e-724737e28171') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
