INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93913, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "度过是把一段时间过完。", "primary_collocate": null, "pronunciation": "dù guò", "ipa": "tu˥˩ kuɔ˥˩", "syllable_count": 2, "sentences": [{"text": "我们在海边度过了一个快乐的假期。", "target_word": "度过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想在家里安静地度过周末。", "target_word": "度过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶在乡下度过了她的童年。", "target_word": "度过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暑假我们一家人是在北京度过的。", "target_word": "度过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和朋友一起度过了难忘的生日。", "target_word": "度过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我打算和家人度过这个春节。", "target_word": "度过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在山上度过了安静的一夜。", "target_word": "度过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想怎么度过这个周末？", "target_word": "度过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "退休以后，爷爷每天在公园度过很多时间。", "target_word": "度过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在国外度过了第一个新年。", "target_word": "度过", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "度过了", "label": "完成体"}], "register": "中性", "sense_fingerprint": "把假期、周末等一段时间过完", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21d5d4e3-cb6a-4e49-9798-364dbe498c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93913, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "度过", "is_correct": true, "explanation": "正确：度过（dù guò）是把一段时间过完。"}, {"text": "读过", "is_correct": false, "explanation": "读过（dú guò）与度过（dù guò）第一音节声调不同（第二声与第四声），意思是读过（书）。"}, {"text": "赌过", "is_correct": false, "explanation": "赌过（dǔ guò）与度过（dù guò）第一音节声调不同（第三声），意思是曾经赌博。"}, {"text": "吐过", "is_correct": false, "explanation": "吐过（tǔ guò）与度过（dù guò）声母不同（t 与 d），意思是吐出过东西。"}, {"text": "对过", "is_correct": false, "explanation": "对过（duì guò）与度过（dù guò）韵母不同（uì 与 ù），意思是对面，属北方口语。"}], "explanations": {"度过": "正确：度过（dù guò）是把一段时间过完。", "读过": "读过（dú guò）与度过（dù guò）第一音节声调不同（第二声与第四声），意思是读过（书）。", "赌过": "赌过（dǔ guò）与度过（dù guò）第一音节声调不同（第三声），意思是曾经赌博。", "吐过": "吐过（tǔ guò）与度过（dù guò）声母不同（t 与 d），意思是吐出过东西。", "对过": "对过（duì guò）与度过（dù guò）韵母不同（uì 与 ù），意思是对面，属北方口语。"}, "sentence_index": null, "correct_answer": "度过"}, "level_3": {"options": [{"text": "度过", "is_correct": true, "explanation": "正确：“度过”表示把一段时间过完，可以接“一个快乐的假期”。"}, {"text": "游览", "is_correct": false, "explanation": "搭配：“游览”的对象是地点、景点，不能接“假期”。"}, {"text": "搬运", "is_correct": false, "explanation": "语义：“搬运”是把东西从一处运到另一处，不能用于“快乐的假期”。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”是使坏了的器物恢复正常，不能用于“快乐的假期”。"}], "explanations": {"度过": "正确：“度过”表示把一段时间过完，可以接“一个快乐的假期”。", "游览": "搭配：“游览”的对象是地点、景点，不能接“假期”。", "搬运": "语义：“搬运”是把东西从一处运到另一处，不能用于“快乐的假期”。", "修理": "语义：“修理”是使坏了的器物恢复正常，不能用于“快乐的假期”。"}, "sentence_index": 0, "correct_answer": "度过"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他度过了一场比赛。", "explanation": "这里应该用〈参加〉。“度过”接的是一段时间，如假期、周末，不能接“比赛”这类具体活动。"}, {"text": "他一晚上度过了一千块钱。", "explanation": "这里应该用〈花〉。“度过”接的是时间段，花钱要用“花”，不能说“度过了一千块钱”。"}, {"text": "我们度过了海边的小镇。", "explanation": "这里应该用〈游览〉。“度过”接的是时间段，不能接“小镇”这样的地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93913, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "度过", "is_correct": true, "explanation": "正确：“度过”表示把一段时间过完，可以接“安静的一夜”。"}, {"text": "攀登", "is_correct": false, "explanation": "搭配：“攀登”的对象是山峰、高处，不能接“安静的一夜”。"}, {"text": "擦洗", "is_correct": false, "explanation": "语义：“擦洗”是清洁物体表面的动作，不能用于“安静的一夜”。"}, {"text": "修建", "is_correct": false, "explanation": "搭配：“修建”的对象是建筑、道路，不能接“一夜”。"}], "explanations": {"度过": "正确：“度过”表示把一段时间过完，可以接“安静的一夜”。", "攀登": "搭配：“攀登”的对象是山峰、高处，不能接“安静的一夜”。", "擦洗": "语义：“擦洗”是清洁物体表面的动作，不能用于“安静的一夜”。", "修建": "搭配：“修建”的对象是建筑、道路，不能接“一夜”。"}, "sentence_index": 6, "correct_answer": "度过"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小明在旅行中度过了一个朋友。", "explanation": "这里应该用〈认识〉。“度过”接的是时间段，不能接人。"}, {"text": "他们用船度过了河。", "explanation": "这句是“渡过河”的同音误写。“度过”表示把一段时间过完，不表示渡河，渡河应写作“渡过”。"}, {"text": "妈妈在商场度过了一件新衣服。", "explanation": "这里应该用〈买〉。“度过”接的是时间段，不能接“衣服”这类物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93913, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在山里正在度过了一个安静的周末。", "corrected_sentence": "我们在山里度过了一个安静的周末。", "error_description": "多出“正在”，与表示已完成的“了”冲突；“正在”表示进行中，应删去，写作“度过了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93913, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在老家度过了了一个热闹的春节。", "corrected_sentence": "他们在老家度过了一个热闹的春节。", "error_description": "“了”重复，“度过了了”多出一个“了”；应为“度过了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
