INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93914, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "经历并渡过（一段时间或一个难关）。", "primary_collocate": null, "pronunciation": "dù guò", "ipa": "tu˥˩ kuɔ˥˩", "syllable_count": 2, "sentences": [{"text": "公司终于度过了最难的时期。", "target_word": "度过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起努力，度过了这个难关。", "target_word": "度过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那年家里很穷，我们艰难地度过了冬天。", "target_word": "度过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，他已经度过了危险期。", "target_word": "度过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的话帮我度过了最难过的日子。", "target_word": "度过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起度过了很多困难的日子。", "target_word": "度过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店靠老客人度过了难关。", "target_word": "度过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要有信心，你一定能度过这段困难的时间。", "target_word": "度过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人互相帮助，度过了那次大水。", "target_word": "度过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生病的那段日子，是家人陪我度过的。", "target_word": "度过", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "度过了", "label": "完成体"}], "register": "中性", "sense_fingerprint": "经历并熬过困难的时期或难关", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21d5d4e3-cb6a-4e49-9798-364dbe498c05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93914, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "度过", "is_correct": true, "explanation": "正确：度过（dù guò）是经历并熬过困难的时期或难关。"}, {"text": "读过", "is_correct": false, "explanation": "读过（dú guò）与度过（dù guò）第一音节声调不同（第二声与第四声），意思是读过（书）。"}, {"text": "赌过", "is_correct": false, "explanation": "赌过（dǔ guò）与度过（dù guò）第一音节声调不同（第三声），意思是曾经赌博。"}, {"text": "吐过", "is_correct": false, "explanation": "吐过（tǔ guò）与度过（dù guò）声母不同（t 与 d），意思是吐出过东西。"}, {"text": "对过", "is_correct": false, "explanation": "对过（duì guò）与度过（dù guò）韵母不同（uì 与 ù），意思是对面，属北方口语。"}], "explanations": {"度过": "正确：度过（dù guò）是经历并熬过困难的时期或难关。", "读过": "读过（dú guò）与度过（dù guò）第一音节声调不同（第二声与第四声），意思是读过（书）。", "赌过": "赌过（dǔ guò）与度过（dù guò）第一音节声调不同（第三声），意思是曾经赌博。", "吐过": "吐过（tǔ guò）与度过（dù guò）声母不同（t 与 d），意思是吐出过东西。", "对过": "对过（duì guò）与度过（dù guò）韵母不同（uì 与 ù），意思是对面，属北方口语。"}, "sentence_index": null, "correct_answer": "度过"}, "level_3": {"options": [{"text": "度过", "is_correct": true, "explanation": "正确：“度过”表示熬过最难的时期，与“最难的时期”搭配。"}, {"text": "攀登", "is_correct": false, "explanation": "搭配：“攀登”的对象是山峰，不能接“时期”。"}, {"text": "修复", "is_correct": false, "explanation": "语义：“修复”指使损坏的东西恢复原状，不能用于“时期”。"}, {"text": "游览", "is_correct": false, "explanation": "语义：“游览”指参观风景，不能用于“时期”。"}], "explanations": {"度过": "正确：“度过”表示熬过最难的时期，与“最难的时期”搭配。", "攀登": "搭配：“攀登”的对象是山峰，不能接“时期”。", "修复": "语义：“修复”指使损坏的东西恢复原状，不能用于“时期”。", "游览": "语义：“游览”指参观风景，不能用于“时期”。"}, "sentence_index": 0, "correct_answer": "度过"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他度过了一瓶水。", "explanation": "这里应该用〈喝〉。“度过”接的是困难或时间段，不能接“水”这类饮品。"}, {"text": "他在饭桌上度过了一顿饭。", "explanation": "这里应该用〈吃〉。“度过”用于时间段或困难，不能接“饭”这类日常活动。"}, {"text": "我们度过了博物馆。", "explanation": "这里应该用〈参观〉。“度过”接的是时间或困难，不能接“博物馆”这样的地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93914, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "度过", "is_correct": true, "explanation": "正确：“度过”表示熬过困难，与“难关”搭配。"}, {"text": "拍摄", "is_correct": false, "explanation": "语义：“拍摄”指录下景物或人，不能用于“难关”。"}, {"text": "修建", "is_correct": false, "explanation": "搭配：“修建”的对象是建筑、道路，不能接“难关”。"}, {"text": "访问", "is_correct": false, "explanation": "搭配：“访问”的对象是人或地方，不能接“难关”。"}], "explanations": {"度过": "正确：“度过”表示熬过困难，与“难关”搭配。", "拍摄": "语义：“拍摄”指录下景物或人，不能用于“难关”。", "修建": "搭配：“修建”的对象是建筑、道路，不能接“难关”。", "访问": "搭配：“访问”的对象是人或地方，不能接“难关”。"}, "sentence_index": 6, "correct_answer": "度过"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在路上度过了一个新朋友。", "explanation": "这里应该用〈认识〉。“度过”接的是困难或时间段，不能接人。"}, {"text": "她度过了一件新衣服，很高兴。", "explanation": "这里应该用〈买〉。“度过”接的是困难或时间段，不能接“衣服”这类物品。"}, {"text": "他们用船度过了河。", "explanation": "这句是“渡过河”的同音误写。“度过”表示经历并熬过困难，不表示渡河，渡河应写作“渡过”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93914, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的父亲终于正在度过了那场大病。", "corrected_sentence": "她的父亲终于度过了那场大病。", "error_description": "多出“正在”，与表示完成的“了”冲突；“正在”表示进行中，应删去，写作“度过了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3894a8ea-a8a5-4871-bf70-0f017d0b756a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
