INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93917, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "抗战是我们国家的人民起来打侵略的敌人的那场战争。", "primary_collocate": null, "pronunciation": "kàng zhàn", "ipa": "kʰɑŋ˥˩ ʈʂan˥˩", "syllable_count": 2, "sentences": [{"text": "抗战开始于一九三七年。", "target_word": "抗战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷常给我讲抗战时的故事。", "target_word": "抗战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "抗战期间，很多学校搬到了西南。", "target_word": "抗战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国人民坚持了八年抗战，终于赢了。", "target_word": "抗战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在博物馆看了一部关于抗战的电影。", "target_word": "抗战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "抗战结束后，爷爷回到了老家。", "target_word": "抗战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人年轻时参加过抗战。", "target_word": "抗战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "课本里有一课专门讲抗战。", "target_word": "抗战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "抗战时，他的家人从北京搬到了重庆。", "target_word": "抗战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每年九月三日，人们都会纪念抗战胜利。", "target_word": "抗战", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "中国人民抵抗日本侵略的那场战争（1937—1945）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ac5386f-a5c3-4a5f-b7d7-6ad2731789e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93917, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抗战", "is_correct": true, "explanation": "“抗战”指1937年开始的中国人民抗日战争，与句中的年份相符。"}, {"text": "春节", "is_correct": false, "explanation": "语义：“春节”是节日，不能作为战争开始的主语。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家用电器，不能说“开始于一九三七年”。"}, {"text": "干架", "is_correct": false, "explanation": "语域：“干架”是口语词，不适合书面的历史叙述。"}], "explanations": {"抗战": "“抗战”指1937年开始的中国人民抗日战争，与句中的年份相符。", "春节": "语义：“春节”是节日，不能作为战争开始的主语。", "冰箱": "语义：“冰箱”是家用电器，不能说“开始于一九三七年”。", "干架": "语域：“干架”是口语词，不适合书面的历史叙述。"}, "sentence_index": 0, "correct_answer": "抗战"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "清朝末年，中国人民进行过八年抗战。", "explanation": "这里应该用〈战争〉。“抗战”专指1937—1945年抗日的那场战争，不能用于清朝末年的战争。"}, {"text": "老师在课堂上和学生进行了抗战。", "explanation": "这里应该用〈争论〉。“抗战”专指抵抗侵略的那场战争，不能用于老师和学生之间的争论。"}, {"text": "两家公司在市场上进行了抗战。", "explanation": "这里应该用〈竞争〉。“抗战”专指抵抗侵略的那场战争，不能用于公司之间的竞争。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93917, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抗战", "is_correct": true, "explanation": "“参加过抗战”指参加过1937—1945年的抗日战争，与“年轻时”相符。"}, {"text": "地毯", "is_correct": false, "explanation": "搭配：“参加”的对象是活动、比赛等，不能说“参加地毯”。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“河流”是自然事物，不能被“参加”。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家用电器，不能被“参加”。"}], "explanations": {"抗战": "“参加过抗战”指参加过1937—1945年的抗日战争，与“年轻时”相符。", "地毯": "搭配：“参加”的对象是活动、比赛等，不能说“参加地毯”。", "河流": "语义：“河流”是自然事物，不能被“参加”。", "冰箱": "语义：“冰箱”是家用电器，不能被“参加”。"}, "sentence_index": 6, "correct_answer": "抗战"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两个人为了钱进行了抗战。", "explanation": "这里应该用〈争夺〉。“抗战”专指抵抗侵略的那场战争，不能用于两人为钱而争。"}, {"text": "士兵们在阵地上进行了一场抗战。", "explanation": "这里应该用〈战斗〉。“抗战”指整场抵抗侵略的战争，不能用于阵地上的一次交战。"}, {"text": "两国在赛场上进行了抗战。", "explanation": "这里应该用〈对抗〉。“抗战”指抵抗侵略的战争，不能用于体育比赛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93917, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "中国人民经历了一个抗战。", "corrected_sentence": "中国人民经历了一场抗战。", "error_description": "“抗战”作为一场战争，通常用量词“场”，写作“一场抗战”；“个”不合习惯。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93917, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他年轻时在北方参加了过抗战。", "corrected_sentence": "他年轻时在北方参加过抗战。", "error_description": "错误：“了”与体标“过”不能同时使用。应去掉“了”，写作“参加过抗战”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
