INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93918, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "抗日战争的简称；泛指抵抗侵略的战争。", "primary_collocate": null, "pronunciation": "kàng zhàn", "ipa": "kʰɑŋ˥˩ ʈʂan˥˩", "syllable_count": 2, "sentences": [{"text": "抗战是抗日战争的简称。", "target_word": "抗战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全国人民一起支持抗战。", "target_word": "抗战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "抗战时期，很多青年去了前线。", "target_word": "抗战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家的抗战打了很多年，人民没有投降。", "target_word": "抗战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写的是八年抗战的历史。", "target_word": "抗战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了抗战，工厂也搬到了山里。", "target_word": "抗战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "抗战中，无数战士献出了生命。", "target_word": "抗战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，抗战让中国人更团结了。", "target_word": "抗战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在那场抗战里，农民也拿起了枪。", "target_word": "抗战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌是抗战时期最有名的歌。", "target_word": "抗战", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抗日战争", "label": "复合"}], "register": "中性", "sense_fingerprint": "抗日战争的简称，也泛指抵抗外来侵略的战争", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ac5386f-a5c3-4a5f-b7d7-6ad2731789e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93918, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抗战", "is_correct": true, "explanation": "“抗战”是“抗日战争”的简称，与句意相符。"}, {"text": "春节", "is_correct": false, "explanation": "语义：“春节”是节日名，不是“抗日战争”的简称。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：“咖啡”是饮品，与“抗日战争”无关。"}, {"text": "哥们", "is_correct": false, "explanation": "语域：“哥们”是口语词，不适合用在书面的定义句中。"}], "explanations": {"抗战": "“抗战”是“抗日战争”的简称，与句意相符。", "春节": "语义：“春节”是节日名，不是“抗日战争”的简称。", "咖啡": "语义：“咖啡”是饮品，与“抗日战争”无关。", "哥们": "语域：“哥们”是口语词，不适合用在书面的定义句中。"}, "sentence_index": 0, "correct_answer": "抗战"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两派在国内的抗战打了很多年。", "explanation": "这里应该用〈内战〉。“抗战”指抵抗外来侵略的战争，不能用于国内两派之间的战争。"}, {"text": "父子俩在饭桌上进行了抗战。", "explanation": "这里应该用〈争吵〉。“抗战”指抵抗侵略的战争，不能用于家人之间的争吵。"}, {"text": "这家公司和对手进行了抗战，最后赢得了市场。", "explanation": "这里应该用〈竞争〉。“抗战”指抵抗侵略的战争，不能用于公司之间的竞争。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93918, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抗战", "is_correct": true, "explanation": "“抗战中”指抗日战争期间，与“无数战士献出了生命”相符。"}, {"text": "聊天", "is_correct": false, "explanation": "语义：“聊天”期间不会有战士献出生命，两者不相容。"}, {"text": "暑假", "is_correct": false, "explanation": "语义：“暑假”是假期，与战士牺牲的内容不相容。"}, {"text": "瞎扯", "is_correct": false, "explanation": "语域：“瞎扯”是口语，不适合书面的历史叙述。"}], "explanations": {"抗战": "“抗战中”指抗日战争期间，与“无数战士献出了生命”相符。", "聊天": "语义：“聊天”期间不会有战士献出生命，两者不相容。", "暑假": "语义：“暑假”是假期，与战士牺牲的内容不相容。", "瞎扯": "语域：“瞎扯”是口语，不适合书面的历史叙述。"}, "sentence_index": 6, "correct_answer": "抗战"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两个孩子为了一块糖进行了抗战。", "explanation": "这里应该用〈争夺〉。“抗战”指抵抗侵略的战争，不能用于两个孩子为一块糖而争。"}, {"text": "士兵们在山上打赢了一次抗战。", "explanation": "这里应该用〈战斗〉。“抗战”指抵抗侵略的整场战争，不能指山上的一次交战。"}, {"text": "两队在赛场上进行了一场抗战。", "explanation": "这里应该用〈比赛〉。“抗战”指抵抗侵略的战争，不能用于体育比赛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93918, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他参加过一个抗战。", "corrected_sentence": "他参加过一场抗战。", "error_description": "“抗战”作为一场战争，通常用量词“场”，写作“一场抗战”；“个”不合习惯。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93918, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们每年都纪念很抗战胜利。", "corrected_sentence": "我们每年都纪念抗战胜利。", "error_description": "错误：“抗战”是名词，不能受程度副词“很”修饰。应去掉“很”，写作“纪念抗战胜利”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00082aa3-2036-49be-9da5-d362fc7cfc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
