INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93919, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "搜是仔细地找，一个地方一个地方地找。", "primary_collocate": null, "pronunciation": "sōu", "ipa": "soʊ̯⁵⁵", "syllable_count": 1, "sentences": [{"text": "我把房间搜了一遍，还是没找到钥匙。", "target_word": "搜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在书包里搜来搜去，找不到手机。", "target_word": "搜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在草丛里搜了一遍，想找那只小猫。", "target_word": "搜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟在床底下搜了半天，才找到球。", "target_word": "搜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她搜遍了每个柜子，也没找到戒指。", "target_word": "搜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你再搜一搜口袋，也许钥匙在里面。", "target_word": "搜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把沙发下面搜了个遍。", "target_word": "搜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在山上搜了一个下午，才找到小狗。", "target_word": "搜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在包里搜出一张旧照片。", "target_word": "搜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸在仓库里搜了一遍，想找那把旧锤子。", "target_word": "搜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "搜了", "label": "体标（了）"}, {"form": "搜过", "label": "体标（过）"}, {"form": "搜着", "label": "体标（着）"}, {"form": "搜搜", "label": "重叠"}], "register": "中性", "sense_fingerprint": "在某处一处一处仔细翻找东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4215d43d-f30b-4b99-bb09-a9960ea2a2a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93919, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "搜", "is_correct": true, "explanation": "搜：一处一处仔细翻找，与“没找到钥匙”相符。"}, {"text": "装修", "is_correct": false, "explanation": "语义：“装修”指装饰房屋，与“找钥匙”无关，不能表示翻找。"}, {"text": "布置", "is_correct": false, "explanation": "语义：“布置”指安排、陈设，与“找钥匙”的翻找动作不符。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”一般用于花果、树叶，不能说“摘房间”。"}], "explanations": {"搜": "搜：一处一处仔细翻找，与“没找到钥匙”相符。", "装修": "语义：“装修”指装饰房屋，与“找钥匙”无关，不能表示翻找。", "布置": "语义：“布置”指安排、陈设，与“找钥匙”的翻找动作不符。", "摘": "搭配：“摘”一般用于花果、树叶，不能说“摘房间”。"}, "sentence_index": 0, "correct_answer": "搜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在网上搜了一下这个问题的答案。", "explanation": "这里“搜”是网络检索信息的义项，与本条“在具体地点一处一处仔细找”不同，不能用来描述在实体空间里翻找。"}, {"text": "他一生都在搜真理。", "explanation": "这里应该用〈寻找〉。搜指在具体地点一处一处仔细翻找，不用于抽象的真理。"}, {"text": "他一直在搜帮助。", "explanation": "这里应该用〈寻求〉。搜是具体翻找的动作，不能搭配“帮助”这类抽象事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93919, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "搜", "is_correct": true, "explanation": "搜：一处一处仔细翻找，与“搜了个遍”相符。"}, {"text": "缝", "is_correct": false, "explanation": "语义：“缝”指用针线连缀，与翻找无关，“缝了个遍”不成立。"}, {"text": "熨", "is_correct": false, "explanation": "语义：“熨”指用熨斗烫平，不能表示翻找。"}, {"text": "浇", "is_correct": false, "explanation": "搭配：“浇”用于水、花草，不能说“浇沙发下面”。"}], "explanations": {"搜": "搜：一处一处仔细翻找，与“搜了个遍”相符。", "缝": "语义：“缝”指用针线连缀，与翻找无关，“缝了个遍”不成立。", "熨": "语义：“熨”指用熨斗烫平，不能表示翻找。", "浇": "搭配：“浇”用于水、花草，不能说“浇沙发下面”。"}, "sentence_index": 6, "correct_answer": "搜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察在机场搜了他的身，发现了毒品。", "explanation": "这里“搜”是警察依法搜查人身的义项，与本条“自己在某处一处一处翻找东西”不同。"}, {"text": "我在手机上搜了一下明天的天气。", "explanation": "这里“搜”是网上检索信息的义项，与本条“在具体地点一处一处仔细翻找”不同。"}, {"text": "他一直在搜别人的理解。", "explanation": "这里应该用〈寻求〉。搜是具体翻找的动作，不能搭配“理解”这类抽象的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93919, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把书包里里外外搜着一遍。", "corrected_sentence": "我把书包里里外外搜了一遍。", "error_description": "表示搜查已经完成要用“了”，写成“搜着”表示动作持续，与“一遍”的完成义不符，应改为“搜了一遍”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93919, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把抽屉搜着一遍，才找到那张发票。", "corrected_sentence": "妈妈把抽屉搜了一遍，才找到那张发票。", "error_description": "“一遍”表示动作已经完成，应用“了”；“搜着”表示动作持续，与“一遍”不符，应改为“搜了一遍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc82097c-baa6-4411-aa01-89898c696ef1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
